window.__D("text/torat-chaim/c036",{"p":[[2300550700,"מה שיהי' בכל בריא' הכרה והשגה בבורא ית' ויהי' בו בחי' ביטול הי\"ש לאי\"ן בכל עולם ועולם לפי ערכו והוא מ\"ש בראתיו במח'<sup data-n=\"7473\">453</sup> ויצרתיו בדבור אף עשיתיו כו' ואם זה מדבר בנשמות שנק' בשמי שם הוי' ממש שהן בחי' הפנימי' בכל ההשתל' כו', אבל בחיצוני' העולמות ג\"כ יש כוונה בהעלם מאחר שמטבע הטוב להטיב לכל כי חפץ חסד הוא שחפץ שישתמודעו' לי' וכמ\"ש להודיע לבנה\"א כו' וכבוד הדר מלכותו<sup data-n=\"7474\">454</sup> כו'. והנה כוונה זו נמשכה בדרך פרט בכל עולם ובכל בריאה עד שמחמת זה הי' המשכת הבריאה מאי\"ן לי\"ש בציור אופן פרטי בצו\"ח [כ]זה דוקא כנ\"ל והוא בחי' מל' שבכל עולם כמו מל' דבריאה מהוה עולם הבריאה נשמות ומלאכים בע\"ג כו', שז\"ש לכבודי בראתי\"ו כבוד מלכותו שיהי' נמשך עליהם עול מלכותו ויתבטלו מי\"ש לאי\"ן כו', וכך בעולם היצי' ועשי' וכך עד רום המעלות עד הכלל הראשון שהוא מח' הכללי' דמל' דא\"ס בקו\"ח כנ\"ל שמה שעלה במח' זו להיות כללות ההשתל' הי' בזה כוונה כללי' בהעלם שזהו לכבוד\"י הוא שנק' בשמי שמו הגדול בחי' מל' דא\"ס<sup data-n=\"7475\">455</sup> שנתצמצם להיות מל' כ\"ע [דהיינו] בגין דישתמודעון לי' בכללות כו'.\n<b>ואע\"פ</b> שאין ערך כלל למציאות כל ההשתלשלו' לגבי אור העצמות ממש שיפול בזה ענין כבו\"ד שיקרא לכבוד\"י בראתי\"ו כו', הענין הוא דבאמת זהו הצמצום שמצמצם א\"ע להיות לו כבוד מזה לפי שכל יכול הוא ויש בו גם כח המגביל כל גבול וצמצום <span data-k=\"pg\">תרג</span> ּ ולכך יש עונג גם בצמצום זה להיות משתמודעי' לגדולתו שמתפשט בצמצום. ובאמת פי' לכבוד\"י ממש כבוד העצמי שהוא פנימי' מל' דא\"ס כמו שהוא ושמו בלבד יכירו העולמות אחר העלא' דאו\"ח שלהם וכמ\"ש ה' צבאות הוא מלך הכבוד<sup data-n=\"7476\">456</sup> וכן א' וכבוד הדר מלכותו וכן כבוד מלכותך יאמרו<sup data-n=\"7477\">457</sup> כו', והיינו פנימי' הכוונה שבמח' דמל' דא\"ס הכללי' שזה הי' למעלה סיבת בחי' מדת ההתפשטו' וגילוי דמדת מל' למרחוק ולחוץ ממנו דוקא שזה הי' אמיתי' המקור כללי לכל חיות העולמות, שמחמת כח זה דוקא יוצא אח\"כ מן ההעלם לגילוי אור מכח אל הפועל בהתפשטות וגילוי פרטי' לכל עולם ועולם לפי מדרגתו כמו בפרט דו\"מ<sup data-n=\"7478\">458</sup> ביהי אור ורקיע שכל הי\"מ הי' מוכן ועומד בהעלם מח' הכללי' רק שיצא מכח אל הפועל בגילוי אותיות הדבור, וז\"ש ויאמר אלקים שבאמירה זו אין כל חדש רק שבא מהעלם דמח'<sup data-n=\"7479\">459</sup> הכללית שהוא מא' דבראשית בכלל שנק' מאמר אחד כנ\"ל שהוא שנק' מחשבה אחת בכלל קודם שנתחלק בקו\"ח שהוא הפרט שיוצא מן",[["7473","453","<b>בראתיו במח'</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תר. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, א</a>. מאמרי אדה\"א בראשית ע' תמא. ו \"נ."],["7474","454","<b>להודיע לבנה\"א. . מלכותו</b>: תהלים קמה, יב."],["7475","455","<b>שמו הגדול בחי' מל' דא\"ס</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["7476","456","<b>ה' צבאות הוא מלך הכבוד</b>: תהלים כד, י."],["7477","457","<b>כבוד מלכותך יאמרו</b>: תהלים קמה, יא."],["7478","458","<b>דו\"מ</b>: טז: דמא'. יז: די\"מ די' מאמרות."],["7479","459","<b>הכללי'. . דמח'</b>: טז: ליתא. וכנראה נשמט מפני תיבות הדומות: מח' הכללי'. . דמח' הכללי'."]]],[2300550704,"הכלל כנ\"ל. אך הנה בהכרח לומר שיש כוונה וטעם גם בסיבת של התפשטות דמדת מל' דא\"ס בצמצום דמח' כללית שזהו שנק' מדת מלוכה והתנשאות והתפשטות שחוץ מן העצמות ע\"י צמצום גדול כנ\"ל, שבודאי יש בה סיבה וטעם המביא וגורם לבחי' גילוי אור רצון במח' זו שהיא בחי' המלוכה וההתפשטות להיות מלך גאות לבש כו'. הענין הוא דזהו בחי' ענג המצומצם הנמשך מענג העצמי דמל' דא\"ס כמו שהוא בעצם בבחי' שעשועי המלך בעצמו<sup data-n=\"7480\">460</sup> כו' (כמ\"ש נכו\"ן כסא\"ך מאז מעולם<sup data-n=\"7481\">461</sup> הא\"ס כו') להיות לו רצון להתפשטות דבחי' מלוכה שהוא הגורם במח' זו המצומצמת להתהוות כללות העולמות כנ\"ל, ואם לא בחי' צמצום דעונג הזה שירד מן הענג ושעשועי' העצמי' כנ\"ל לא הי' הרצון הפשוט הזה [ל]מדה זו דמל' בהתפשטו' שחוץ ממנו שאין ערוך לו כלל וכלל [כנ\"ל], ובחי' הארת אור העונג הנעלם הזה שבא לגילוי אור במדה זו דמל' דא\"ס בקו\"ח כו' זהו שנק' זיו השכינה בכלל דשכינה זו מח' הכללית שבאה בגילוי במקיף ופנימי לשכון בעולמות וזיו השכינה [הוא] בחי' העלם הע[ו]נג דמל' דא\"ס עד מל' דאצי' בגעה\"ע לנשמות [עד מל' דעשי' בג\"ע דעשי' כמ\"ש אני ראשון ואני אחרון וכן ראו כי אני אני הוא<sup data-n=\"7482\">462</sup> כו' בלי שינוי כלל וע\"ז א' כי עמך מקור חיים<sup data-n=\"7483\">463</sup> ] מקור כל העונג העליון כו' וד\"ל.\n<b>אך</b><sup data-n=\"7484\">*464</sup> הנה עדיין יש להבין איך יוכל להיות בחי' דילוג הערך כ\"כ להשפיל א\"ע כ\"כ [מ]עונג ושעשועים דמל' דא\"ס עצמו להיות עונג ורצון במח' הכללי' כו' אחר שאין ערך כלל ביניהן, ואם לפי שאמר דבמקום גדולתו שם<sup data-n=\"7485\">464</sup> כו' דזהו מצד טבע הטוב להטיב בגין דישתמודעו' לי' כו', עכ\"ז מאחר שמזה הצמצום יהי' מקור להתהוות העולמות וא\"ל הרי אין עוד מלבדו א\"כ מאיזה טעם יהי' עונג בזה כלל. והנה להבין זה יש להקדים ביאור מאמר א' במס' פסחים שאמר לענין מה שיעקב אמר בשכמל\"ו כו' התקינו שיאמרו אותו בחשאי משל לבת מלך שהריחה ציקי קדירה<sup data-n=\"7486\">465</sup> תאמר יש לה גנאי לא תאמר יש לה צער מה עשו עבדי' הביאו לה בחשאי כו' ע\"ש. <span data-k=\"pg\">1208</span> ּ וזה המאמר פלאי דאיך בת מלך שרגילה כל ימיה במעדני מל[כים] תריח ציקי קדרה שהנפש קצה בהן, וגם מהו שאם לא תאמר מפני הגנאי שיש לה מזה מהו הגנאי אם הריחה ונפשה חשק[ה] לזה,",[["7480","460","<b>שעשועי המלך בעצמו</b>: נסמן לעיל פ' תרומה שיח, ב."],["7481","461","<b>נכו\"ן כסא\"ך מאז מעולם</b>: תהלים צג, ב. ראה גם לקמן תו, ג. תח, א. תיב, ב."],["7482","462","<b>ראו כי אני אני הוא</b>: האזינו לב, לט [בדילוג]."],["7483","463","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["7484","*464","<b>אך</b>: יב נרשם: ואו [ה נרשם לעיל על יד הערה *422. ז נרשם לקמן על יד הערה 626]."],["7485","464","<b>דבמקום גדולתו שם</b>: נסמן לעיל פ' יתרו רנט, ב."],["7486","465","<b>במס' פסחים. . שיעקב אמר בשכמל\"ו. . ציקי קדירה</b>: ראה שם נו, א."]]],[2300550707,"ומהו שעבדי' הביאו לה בחשאי כו' שלא יהי' לה גנאי מפני הרואי' כו'. אך הנה עיקר המכוון במשל זה הוא למעלה בבחי' בת מלך העליון שעלי' א' כל כבודה בת<sup data-n=\"7487\">466</sup> מלך<sup data-n=\"7488\">467</sup> פנימה כו' שהריחה ציקי קדרה כו'. דהנה ידוע בענין יח\"ע דפסוק ראשון דשמע<sup data-n=\"7489\">468</sup> ישראל כו' שהוא בבחי' ע\"ס דאצי' באו\"כ בג' מדרגו' דחב\"ד כו' שיח\"ע זה הכל הוא בבחי' האצי' דשם א' דאיהו וחיוהי וגרמוהי חד<sup data-n=\"7490\">469</sup> בבחי' א\"ס ממש, וזהו [שית תי]בין דיח\"ע עד ד' רבת\"י דאחד שהוא בחי' מל' דאצי' [באצי'] שהוא עצם המדה דהתנשאו' והתפשטות בגילוי כל אור דע\"ס הכל באצי' עצמו. וזהו שא' השבטים ליעקב שמע ישראל כו' כשם שאין בלבך<sup data-n=\"7491\">470</sup> אלא אחד (שהוא בבחי' קו האמצעי דת\"י<sup data-n=\"7492\">471</sup> כו') כך אין בלבינו (בבחי' מל' דאצי' בבריאה כו' אלא אחד דיח\"ת שוה ליח\"ע כמאמר דכגוונא דאינון<sup data-n=\"7493\">472</sup> כו' כידוע, וע\"כ מיד פתח יעקב ואמר בשכמל\"ו שזהו שמבחי' [ת\"ת] דיעקב<sup data-n=\"7494\">473</sup> נמשך למל' בבי\"ע כי בריח התיכון [דיעקב]<sup data-n=\"7495\">474</sup> מבריח לקצה התחתון לבקוע גם המסך שבין אצי' לבריאה<sup data-n=\"7496\">475</sup> (וזהו יעק\"ב אותיות יבק\"ע<sup data-n=\"7497\">476</sup> כו').\n<b>וזהו</b> שאמר שם במס' פסחים אמרי רבנן היכי נעביד נימרינהו לבשכמל\"ו לא אמרו משה שהוא בבחי' שם מ\"ה<sup data-n=\"7498\">477</sup> דיחו\"ע דאצי' שלמעלה מהיות מקור למוחי' דנוק' דז\"א ולא נימרי' אמרו יעקב (שנשא ב' אחיות<sup data-n=\"7499\">478</sup> לאה ורחל מח' ודבור<sup data-n=\"7500\">479</sup> שהוא קול יעקב באותיות הדבור די\"מ כו'). ואע\"ג דמשה מלגיו ויעקב מלבר<sup data-n=\"7501\">480</sup> וזהו בחי' דעת ות\"ת ומשה שהוא בחי' דעת לא א' בשכמל\"ו ויעקב אמרו לפי שבריח התיכון כו', התקינו שיהיו אומרי' אותו בחשאי דוקא ולא בקול רם [רק ביו\"כ או' אותו בקול רם<sup data-n=\"7502\">481</sup> ] כו', והטעם הוא לפי שא\"א להיות המשכה זו דבחי' ת\"ת דיעקב בעל עולם האצי'<sup data-n=\"7503\">482</sup> לבחי' המל' להיות המשכת כתר מל' בבריאה כי הרי אין ערך כלל וכלל לבריאה עם האצי'<sup data-n=\"7504\">483</sup> ולפי שבע\"ג אין לו ערך כלל לבלתי בע\"ג ואיך יצמצם א\"ע כ\"כ להיות ראש ומקור לעולם הבריאה שהן בע\"ג שנתהוו מאין ליש מאותיות הדבור, ואע\"פ שאמר כשם שאין בלבך כו' כך כו' זהו במדת מל'<sup data-n=\"7505\">484</sup> דאצי' עצמה כמו שהיא מיוחדת וכלולה בבחי' האצי' במדות ומוחי' דז\"א כו' (שהוא דלי\"ת רבתי דאחד שמלבשת המל' לתנה\"י דז\"א<sup data-n=\"7506\">485</sup> כידוע) ולזה הטעם לא אמרו משה כנ\"ל, וא[ף] שיעקב אמרו זהו כמו שיהי' לע\"ל ששם אלקי'",[["7487","466","<b>כל כבודה בת מלך פנימה</b>: תהלים מה, יד."],["7488","467","<b>מלך</b>: בתו\"ח באים כאן עוה\"פ התיבות: העליון. . מלך."],["7489","468","<b>יח\"ע. . דשמע ישראל</b>: זהר בראשית יח, ב. ואתחנן ו, ד."],["7490","469","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב)."],["7491","470","<b>שא' השבטים. . כשם שאין בלבך</b>: ראה פסחים שם. לעיל פ' תצוה שנא, ב. משפטים רצ, ב. וש\"נ."],["7492","471","<b>קו האמצעי דת\"י</b>: ראה גם לעיל פ' תצוה שלא, ג. תרומה שטז, ב."],["7493","472","<b>דכגוונא דאינון</b>: ראה זהר תרומה קלה, א."],["7494","473","<b>[ת\"ת] דיעקב</b>: זהר (ס\"ת) ויצא קנז, ב. שם ח\"ג (תוספות) שב, א."],["7495","474","<b>בריח התיכון [דיעקב]</b>: ראה זהר תרומה קעה, ב. מאמרי אדה\"א שמות ח\"א ע' יט. וש\"נ."],["7496","475","<b>המסך שבין אצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["7497","476","<b>יעק\"ב אותיות יבק\"ע</b>: ראה ע\"ח (שער הארת המוחין) של\"ב, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680299\" data-slug=\"torat-chaim\" data-id=\"2300680299\">תו\"ח וישלח קפה, ב</a> הערה 17."],["7498","477","<b>משה. . שם מ\"ה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["7499","478","<b>יעקב (שנשא ב' אחיות</b>: ויצא כט, טז. ואילך."],["7500","479","<b>לאה ורחל מח' ודבור</b>: ראה גם לעיל פ' שמות יח, רע\"ב. וש\"נ."],["7501","480","<b>דמשה מלגיו ויעקב מלבר</b>: ראה ת\"ז תי\"ג (כט, א)."],["7502","481","<b>ביו\"כ. . בקול רם</b>: ראה שו\"ע אדה\"ז הל' יוה\"כ סתרי\"ט, ס\"ט. לעיל פ' וארא עה, ד הערה 241."],["7503","482","<b>דיעקב בעל עולם האצי'</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"א."],["7504","483","<b>אין ערך. . לבריאה עם האצי'</b>: ראה גם לעיל פ' בא צו, ד. וש\"נ."],["7505","484","<b>מל'</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: בבריאה כי הרי אין ערך. . במדת מל'."],["7506","485","<b>שמלבשת המל' לתנה\"י דז\"א</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"א. פע\"ח (שער התפילין) ש\"ד, פט\"ז (הדרך הג'). (שער הק\"ש) ש\"ח, פי\"ב."]]],[2300550710,"דמל'<sup data-n=\"7507\">486</sup> לא יסתיר לשם הוי' ויהי' הוי' א' ושמו אחד<sup data-n=\"7508\">487</sup> בשוה ממש למהוי אחד באחד<sup data-n=\"7509\">488</sup> <span data-k=\"pg\">תרד</span> ּ כו' וכמ\"ש ונגלה כבוד הוי'<sup data-n=\"7510\">489</sup> דאצי' וראו כ\"ב כי פי הוי' עצמו דיבר בי\"מ דשם אלקים בלי העלם ולבוש כלל, משא\"כ עכשיו ששם אלקים מסתיר כמ\"ש באורך נראה אור<sup data-n=\"7511\">490</sup> רק בהארה דהארה בשינוי המהות כמו דרך מסך הנ\"ל (וגם את זלעו\"ז עשה האלקי'<sup data-n=\"7512\">491</sup> כו' שהוא בחי' ק\"נ שמקבלי' מחיצוני' ואחוריים דשם אלקים ממש). וע\"כ אין אומרים בשכמל\"ו שזהו צמצום דשם אלקי' להיות מלך על עם נפרד כו' כענין ה' מלך גיאות לבש כו' וירידה גדולה ועצומה היא מאד להיות לו רצון וע[ו]נג לבחי' מל' על עולמות הנפרדים שהן בע\"ג כו' רק אומרים אותו בחשאי וצנעא זהו<sup data-n=\"7513\">492</sup> ע\"י המלאכים שמקבלים עליהם עומ\"ש ביראה וביטול היש לאין כו', ולכך או' ישראל גם שהן ביח\"ע כמשה בחשאי עכ\"פ ולא בקול רם כמלאכים ולע\"ל יאמרו בקול רם<sup data-n=\"7514\">493</sup> דוקא, וכמ\"כ יוכ\"פ עכשיו שהוא כמו מעין דלע\"ל<sup data-n=\"7515\">494</sup> כמו שאו' בנעילה דיו\"כ ז\"פ הוי' הוא האלקים כו'<sup data-n=\"7516\">495</sup> אחד<sup data-n=\"7517\">496</sup> ממש כמו שיהי' לע\"ל שיהי' אור הלבנה כאור החמה<sup data-n=\"7518\">497</sup> כו' (שוין בקומתן כמו קודם מיעוט הירח).\n[י]<b> וזהו</b><sup data-n=\"7519\">498</sup> שא' ע\"ז משל<sup data-n=\"7520\">499</sup> לבת מלך שהריחה ציקי קדרה תאמר יש לה גנאי כו', דהנה יש ב' מיני עונג, [א' עונג] העצמי שיש בטבע בעצם הדבר שהוא טוב יערב<sup data-n=\"7521\">500</sup> לנפש כמו הע[ו]נג בטעם ערב [לחיך] וטוב לנפש בחיך הטועם במתיקות ועריבות במאכל הטוב במעדנים ומטעמים שמבשלים בקדרה שטועמים בהן כל מיני טעם וחיות לנפש כו'. והב' העונג שמורכב בהיפוכו דוקא כמו מה שנשרף באש ונשאר בקדרה מפסולת המאכל המבושל לאחר שיצא ממנו כל הטעם הטוב ונדבק בכותלי הקדרה ובשולי' זהו שנק' ציקי קדרה<sup data-n=\"7522\">501</sup> כידוע, ואמנם יש בזה טעם קיוהא וחריפות וחמיצות<sup data-n=\"7523\">502</sup> שמשיב הנפש ומחזק הלב מצד חריפותו וגסותו ומריח ריח חזק ביותר שלזה הריח דוקא יתאוה כל חלש הלב ונפש רקניות שתמלא חסרונה להשיב נפשה<sup data-n=\"7524\">504</sup> כידוע<sup data-n=\"7525\">503</sup>, ויכול להיות עונג הנפש<sup data-n=\"7526\">505</sup> בריח זה מריח וטעם מתיקות<sup data-n=\"7527\">506</sup> יותר<sup data-n=\"7528\">507</sup> ממעדני מלך כו'. וזהו פי' המשל לבת מלך שרגילה במטעמי'<sup data-n=\"7529\">508</sup> ערבים ומתוקי'<sup data-n=\"7530\">509</sup> בדקות העונג",[["7507","486","<b>ששם אלקי' דמל'</b>: ראה זהר בראשית כב, א. אחרי סה, א. לעיל פ' וארא עה, ב. וש\"נ."],["7508","487","<b>הוי' א' ושמו אחד</b>: זכרי' יד, ט. ראה גם לעיל פ' יתרו רסב, א. וש\"נ."],["7509","488","<b>למהוי אחד באחד</b>: ראה זהר תרומה קלג, סע\"ב ואילך. קלה, סע\"א."],["7510","489","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["7511","490","<b>באורך נראה אור</b>: תהלים לו, י. ראה גם לעיל פ' וארא ס, ב ובהערה 24."],["7512","491","<b>את זלעו\"ז עשה האלקי'</b>: קהלת ז, יד."],["7513","492","<b>זהו</b>: טזיז: והן."],["7514","493","<b>ולע\"ל יאמרו בקול רם</b>: ראה גם לעיל פ' וארא עה, ד. וש\"נ."],["7515","494","<b>יוכ\"פ. . מעין דלע\"ל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380623\" data-slug=\"likkutei-torah\" data-id=\"4001380623\">לקו\"ת</a> להאריז\"ל נח ו, יג. לעיל פ' וארא עה, ד. וש\"נ."],["7516","495","<b>הוי' הוא האלקים כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, ב. לעיל פ' וארא ס, א. וש\"נ."],["7517","496","<b>כו' אחד</b>: יז: כולא חד. יבטז: כבפנים."],["7518","497","<b>אור הלבנה כאור החמה</b>: ישעי' ל, כו. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג."],["7519","498","<b>וזהו</b>: מכאן (ועד להתיבות: שמשיב לנפש כנ\"ל) נעתק בהמשך תער\"ב ע' תלז (בשינויים והוספות)."],["7520","499","<b>ע\"ז משל</b>: טז: שם משל. יז: שם משל ע\"ז."],["7521","500","<b>יערב</b>: שם: וערב."],["7522","501","<b>ציקי קדרה</b>: ראה אוה\"ת בראשית מט, ב."],["7523","502","<b>וחמיצות</b>: תיבה זו לא נעתקה בהמשך תער\"ב שם."],["7524","504","<b>ריח חזק. . להשיב נפשה</b>: ראה סה\"מ מלוקט ח\"ב ע' רטז הערה 52."],["7525","503","<b>וגסותו. . כידוע</b>: תיבה זו לא נעתקה שם."],["7526","505","<b>הנפש</b>: יז ניתוסף: יותר. ראה הערה 507."],["7527","506","<b>מריח וטעם מתיקות</b>: ליתא בהמשך תער\"ב."],["7528","507","<b>יותר</b>: יז ליתא. וראה הערה 505."],["7529","508","<b>במטעמי'</b>: טז ובהמשך תער\"ב: בטעמי'. יז: במעדני'."],["7530","509","<b>ומתוקי'</b>: בהמשך תער\"ב לא הועתק."]]],[2300550713,"והטעם בעצם כל הדברים הטובים כדבש ושמן הטוב שמבשלים בתבלין כל בשר שמן וטוב בכמה מיני ע[ו]נג וטעם עצמי, אך<sup data-n=\"7531\">510</sup> לפעמים כאשר יחלש כח הנפש ולא תקבל כל התענוגי' ממאכלים הטובים העולים על ש\"מ<sup data-n=\"7532\">511</sup> יוכל להיות שתתאוה הנפש בהריחה ריח חזק וקשה דציקי קדרה דוקא שמשיב לנפש כנ\"ל. אך שהוא גנאי ובזיון לנפש הגבוה כבת מלך שתתאוה לציקי קדרה שאוכלים העבדים הפחותי' יערב עליהן יותר מכל מעדני' כו', ואע\"פ שלא תאמר להביא לה ציקי קדרה לפי שגנאי הוא לה לפי כבודה של בת מלך כו', אבל מחמת שהריחה הריח החזק הזה דציקי קדירה ותתאוה נפשה לזה יש לה צער בגופה על שלא תשיג למלאות תאוותה ולזאת יביאו לה עבדי' בחשאי דוקא כו'.\n<b>והנמשל</b> מזה יובן למעלה בבחי' בת מלך העליון כו', בהיות מבואר למעלה בבחי' מל' דאצי' שנק' בת מלך<sup data-n=\"7533\">512</sup> למעלה כידוע (דאבא יסד ברתא<sup data-n=\"7534\">513</sup> ונק' ברתא דמלכא<sup data-n=\"7535\">514</sup> ) <span data-k=\"pg\">1210</span> ּ כו', והיינו ה\"א האחרונה דשם הוי'<sup data-n=\"7536\">515</sup> שהוא בחי' הדבור בצירופי אותיות בה' מוצאות כו', והוא בחי' התגלות האורות דרצון וחכ' ומדות שיש בזה בחי' ע[ו]נג עצמי והוא בחכ' ומדות שבדבור ששרשה בחכמה ועיניו<sup data-n=\"7537\">516</sup> שבראש דאבא יסד ברתא כו' דמצרף לאותיות בא מן החכמה [ש]בראש כו', וכתיב אכלו ריעים כו' שהוא חו\"ב<sup data-n=\"7538\">517</sup> שנק' ריעים שיש בחי' עונג מורגש באוכ\"ל דחכ' כחיך יטעם אוכל<sup data-n=\"7539\">518</sup> בשמו<sup data-n=\"7540\">519</sup> כו' (כלחם הפנים<sup data-n=\"7541\">520</sup> וכסעודה דע\"י בשבת<sup data-n=\"7542\">521</sup> כו') עד באתי לגני<sup data-n=\"7543\">522</sup> אחותי כלה אכלתי יערי כו' שכ\"ז הוא בחי' השפע הפנימי' ועצמיות שמלובש במטעמי' כרזין וסודות התורה שמתוקי' מדבש ונק' דבשי ייני וחלבי<sup data-n=\"7544\">523</sup> כו' ונעשי' מטעמים. אך בחי' פסולת השפע דאצי' הוא שנשאר למטה להיות מזון וחיות לנשמות ומלאכים דבי\"ע כו' והוא שנק' ציקי קדרה שנשאר בשולי' דבוק אך שיש בו טעם חריף וקשה להשיב נפש כנ\"ל, והוא העונג שבהיפך למעלה להיות הע[ו]נג דבת מלך לטעום טעם הפסולת בחי' ציקי קדרה שנשאר למטה בעולם הפירוד להיות מזון בנבראים ב[ע]\"ג (כמו שמפסולת השפע בג\"ע<sup data-n=\"7545\">524</sup> דעשי' נמשך שרש התענוגי' הגשמיי' דעוה\"ז",[["7531","510","<b>כדבש. . אך</b>: שם: כו'. הנה."],["7532","511","<b>ש\"מ</b>: טז: שולחן מלכים."],["7533","512","<b>מל'. . בת מלך</b>: ראה זהר (רע\"מ) צו כז, ב (ובאוה\"ח שם). תצא רפב, א. פרדס (שער עה\"כ) שכ\"ג מערכת בת. הערה 514."],["7534","513","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' תשא שפג, ד."],["7535","514","<b>ברתא דמלכא</b>: ראה זהר (סבא) משפטים צד, ב. (רע\"מ) פינחס רכז, ב (ובאוה\"ח שם)."],["7536","515","<b>ה\"א האחרונה דשם הוי'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["7537","516","<b>ועיניו</b>: טזיז: ועונג."],["7538","517","<b>אכלו ריעים. . חו\"ב</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["7539","518","<b>כחיך יטעם אוכל</b>: ע\"פ איוב יב, יא. לד, ג."],["7540","519","<b>בשמו</b>: טזיז: גשמי."],["7541","520","<b>כלחם הפנים</b>: תרומה כה, ל."],["7542","521","<b>וכסעודה דע\"י בשבת</b>: נסמן לעיל שצא, ג."],["7543","522","<b>באתי לגני</b>: התחלת הכתוב אכלו ריעים."],["7544","523","<b>כרזין וסודות התורה. . דבשי ייני וחלבי</b>: שה\"ש שם. ראה גם מאמרי אדה\"א שמות ח\"א ע' עז. וש\"נ. לעיל פ' בא צו, א הערה 455. בשלח רלו, ד."],["7545","524","<b>שמפסולת השפע בג\"ע</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' נח. וש\"נ. לעיל פ' וארא ס, ד ובהערה 62."]]],[2300550716,"כידוע). ואע\"פ שאין ערך כלל לעונג זה שבטעם הפסולת בציקי קדרה לגבי עונג העצמי שבמטעמי' ומעדנים העליונים מ\"מ הריחה ריח שמשיב לנפש כו', והיינו מה שעולה ומתברר מרפ\"ח ניצוצי' דתהו ששרשן בבחי' גבורות עליונות שיש בהן חיות רב ותוקף גדול בתגבורת אור חזק ביותר (שמפני זה לא יכלו הכלים לסבול האור ונפלו כו') והוא בחי' ס\"ג שלמעלה משם מ\"ה<sup data-n=\"7546\">525</sup> דאצי' כידוע). אך בנפילתן למטה שהוא רשפי אש החום הקשה ברצון חזק ותוקף גדול שהן כמו גבורות קשות דבחי' ב\"ן דנוגה למטה כבהמות וחיות וכמו [ה]פסולת דציקי קדירה שבאים מחום האש שכלה הכל כו', ואמנם מ\"מ יש בהן [בחי'] פיקוח לנפש כמו דבר חריף וקשה [כ]סממנים חריפים שמחמת חריפותם ומרירות שלהם כשנהפך לטעם טוב יערב לנפש להחיותה ולחזק[ה] מחלישותה ביותר, וכמו ריח הבושם שנעשה מדם החי' ששמה ידו\"ע שנק' מו\"ר<sup data-n=\"7547\">526</sup> כו' וכידוע שכל הרפואות שמרפאים נעשים מסממנים חריפים וקשים ביותר שניתקנו ונעשו סם חיים לפיקוח נפש יותר ממאכל הטוב וערב ביותר לפי שיש בהן כח חזק יותר כו'.\n<b>וזהו</b> משל לענין היפוך הגבורות הקשות דנוגה ואף בגבורות עליונות דב\"ן דמרכבה דפני ארי' דקדושה בביטול היש לאין כו' שזהו בחי' גבורות דתהו שלמעלה מתיקון דאד\"ם כנ\"ל, וזהו ענין היפוך חשך לאור שיש בו יתרון מעלה מגוף האור ונעשה תוס' [אור] רב באור יותר (וכקרבנות דבהמה מחו\"ד<sup data-n=\"7548\">527</sup> גשמי נעשה לריח ניחוח להוי' דתיקון דאצי' מטעם הנ\"ל וכן ריח הקטרת מי\"א סממנים חריפים שמארור נעשה ברוך<sup data-n=\"7549\">528</sup> ומקטיגור נעשה סניגור<sup data-n=\"7550\">529</sup> שהוא היפוך חשך לאור ורע עצמו לטוב נעשה מזה ריח המשיב לנפש [כו'], כענין סם חיים שיותר נעלה מחיים דחכמה וחסד ועונג העצמי' דאצי' כמו שא' טוב זה מלאך חיים מאד <span data-k=\"pg\">תרה</span> ּ זה מה\"מ<sup data-n=\"7551\">530</sup> שנהפך לחיים כו', והיינו מטעם הנ\"ל בהיפוך חשך לאור למעלה מבחי' התהו שקדם לתיקון ולמטה זהו הנופל בבחי' פסולת וגסות כמו בגבורות דחום קשה וסם חריף כו'. וזהו שא' שהריחה ציקי קדירה שהוא מה שעלה ריח החזק מבחי' בירורי' דרפ\"ח כו' שנפל למטה שזהו [ש]נשאר ממזון ושפע העליון דאצי' בבחי' פסולת (כידוע בע\"ח דכל מה",[["7546","525","<b>ס\"ג שלמעלה משם מ\"ה</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה שם."],["7547","526","<b>מדם החי' ששמה ידו\"ע שנק' מו\"ר</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קלו. וש\"נ. נ\"ך ע' שפו. מאמרי אדה\"ז תקע\"א ע' קלד וע' קמג. וש\"נ."],["7548","527","<b>מחו\"ד</b>: מחלב ודם."],["7549","528","<b>הקטרת. . שמארור נעשה ברוך</b>: ראה מאמרי אדה\"א בראשית ע' תיב. דברים ח\"א ע' ז. ח\"ב ע' תרסא ובהנסמן בהנ\"ל."],["7550","529","<b>ומקטיגור נעשה סניגור</b>: ע\"פ ברכות נט, א."],["7551","530","<b>טוב. . זה מה\"מ</b>: בראשית א, לא. יל\"ש שם (רמז טז). זהר בהקדמה יד, א."]]],[2300550719,"שיוכל להתברר משם מ\"ה באצי' עולה ונכלל באצי' ומה שלא יוכל להתברר שם נופל למטה בבריאה<sup data-n=\"7552\">531</sup> כו' עד הפסולת הגס ביותר בסוף העשי' כו', וזהו ענין הטיקלא<sup data-n=\"7553\">532</sup> כו'), והוא שעולה באו\"ח נעשה מזה ריח חזק להשיב נפש ביותר מכל מעדני' העליונים כמו וירח ריח בגדיו<sup data-n=\"7554\">533</sup> כו' שבגדי עשו החמודות<sup data-n=\"7555\">534</sup> היו משיורי הז\"מ<sup data-n=\"7556\">536</sup> דתהו שלא נתבררו עדיין, והוא בחי' החשמ\"ל העליון שנפל למטה בחטא עה\"ד, והיינו ענין כתנו\"ת עו\"ר<sup data-n=\"7557\">537</sup> דא[ד]ה\"ר<sup data-n=\"7558\">535</sup>, ולפי שאחר הבירור דתהו עולה למעלה מעלה בגבורות עליונות דאו\"ח שלמעלה מאו\"י ע\"כ א' ריח בני כריח שדה<sup data-n=\"7559\">538</sup> כו' וכמ\"ש במ\"א. וכך כאן בירידת המל' בהיכלות דב\"ן דנוג\"ה הריחה ציקי קדירה כו' שיש בזה עונג נפלא להשיב נפש מטעם יתרון האור מהיפוך החשך, ולזאת שזהו יהי' לריח ניחוח למעלה יותר מעונג וטעם שבחכמה ורצון ומדות שבאצי' לכך מתצמצם עצם מדה זו דמל' דאצי' להיות מלך על עם כו', שזהו ירידה וצמצום גדול דשם ב\"ן דמל'<sup data-n=\"7560\">539</sup> דאצי' להיות כת\"ר ורא\"ש לבי\"ע בק\"ך צירופי' דשם אלקי'<sup data-n=\"7561\">540</sup>, שזהו ירידה דחכמה שבדיבור העליון למטה להיות מזה מקור להתהוות נבראים בע\"ג כידוע, כמו להיות מקור ושרש לנבראים דעולם הבריאה כשרפים חיות ואופנים כו' בשם אלקים בחי' ב\"ן<sup data-n=\"7562\">541</sup> והוא שם אד[נ\"י] לאשתמודע אדון על כולא<sup data-n=\"7563\">542</sup> כו' וכמ\"ש אד[נ\"י] ב\"ם כו' ונק' רכב אלקים<sup data-n=\"7564\">543</sup> כו'. וכ\"ז רק בשביל בירור [ד]נוג\"ה דבי\"ע שנפלו שם מרפ\"ח כו' להפוך חשך שלמטה שנק' חשמ\"ל התחתון לאור והוא ירידת שם ב\"ן דמל' בלילה דכתיב ותקם בעוד לילה<sup data-n=\"7565\">544</sup> ותתן טרף לביתה טר\"ף רפ\"ח ע\"ה<sup data-n=\"7566\">545</sup>, והוא מ\"ש בזהר דבלילה אזלת לטורי חשוכא<sup data-n=\"7567\">546</sup> ומשם ארח[ת] מזונא כו' כידוע. והיינו ענין שהריחה ריח דציקי קדירה שיבורר להיות השבת נפש מזה כריח ניחוח דקטורת וקרבן בהמ[ה] לשם הוי' דתיקון בתוס' אור יותר מטעם הנ\"ל וד\"ל.\n<b>וביאור</b> ענין זה ידוע כמו בענין ההפרש שבין צדיקים לבע\"ת, דצ\"ג מבחי' האור דשם [הוי'] דאדם דאצי' בתיקון דשם מ\"ה דחכ' דתו\"מ (שהן כמו מטעמים ומעדנים שעולה על שו\"מ<sup data-n=\"7568\">547</sup> כאכלו רעים אכלתי<sup data-n=\"7569\">548</sup> כו') והוא עצמו' ופנימי' התענוג ורצה\"ע שבח\"ע ומדות שיורד לשם<sup data-n=\"7570\">549</sup> ב\"ן דבחכ'",[["7552","531","<b>בע\"ח. . שיוכל להתברר. . באצי'. . בבריאה</b>: ראה גם לעיל פ' תשא שפה, ג. וש\"נ."],["7553","532","<b>ענין הטיקלא</b>: ראה גם בענין הטיקלא הנסמן במאמרי אדה\"א דברים ח\"א ע' סב."],["7554","533","<b>וירח ריח בגדיו</b>: תולדות כז, כז [בדילוג — ראה לעיל פ' שמות ח, ב. וש\"נ]."],["7555","534","<b>שבגדי עשו החמודות</b>: תולדות שם, טו [בדילוג]. ראה גם לעיל פ' משפטים רפז, ב. וש\"נ."],["7556","536","<b>הז\"מ</b>: טז: הז' מלכים."],["7557","537","<b>החשמ\"ל העליון. . כתנו\"ת עו\"ר דאדה\"ר</b>: ראה גם לעיל פ' בשלח קנח, ב. וש\"נ. (לעיל הערה 359)."],["7558","535","<b>שבגדי עשו החמודות. . כתנו\"ת עו\"ר דא[ד]ה\"ר</b>: ראה פדר\"א פכ\"ד. מאמרי אדה\"א בראשית ע' קעב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680284\" data-slug=\"torat-chaim\" data-id=\"2300680284\">תו\"ח תולדות קנג, ג</a> <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680450\" data-slug=\"torat-chaim\" data-id=\"2300680450\">הערה 61. קס, רע\"ד</a>."],["7559","538","<b>ריח בני כריח שדה</b>: ראה ד\"ה זה במאמרי אדה\"ז תקס\"ה ח\"א ע' יז ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו\"א תולדות כ, ב</a> ואילך (ובהנסמן במ\"מ לשם)."],["7560","539","<b>דשם ב\"ן דמל'</b>: נסמן לעיל פ' יתרו רנה, ג."],["7561","540","<b>בק\"ך צירופי' דשם אלקי'</b>: נסמן לעיל פ' יתרו רסג, ג."],["7562","541","<b>אלקי' בחי' </b>[יז: שם]<b> ב\"ן</b>: ראה רמ\"ז לזהר משפטים צז, א. לעיל פ' שמות יט, ג ובהערה 814."],["7563","542","<b>לאשתמודע אדון על כולא</b>: ראה ת\"ז בהקדמה (יז, ב)."],["7564","543","<b>אד[נ\"י] בם כו'. . רכב אלקים</b>: תהלים סח, יח (בהיפך הסדר)."],["7565","544","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["7566","545","<b>טר\"ף רפ\"ח ע\"ה</b>: ראה פע\"ח (שער ק\"ש שעהמ\"ט) שט\"ז, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלא. מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["7567","546","<b>דבלילה אזלת לטורי חשוכא</b>: ראה זהר פינחס רמט, א ואילך."],["7568","547","<b>שו\"מ</b>: טז: שולחן מלכי'."],["7569","548","<b>אכלתי</b>: שה\"ש ה, א."],["7570","549","<b>לשם</b>: טז: לברר לבחי'. יז: לברר לשם."]]],[2300550722,"אתברירו כו'. אך בע\"ת הן מהפכי' הרע עצמו לטוב שזהו היפוך חושך לאור שמזה ארור עצמו נעשה ברוך לפי שקטיגור דרע עצמו נעשה סניגור. וזהו שנק' סם חיים שיותר מפקח לנפש מן האוכל הטוב כנ\"ל <span data-k=\"pg\">1212</span> ּ (וזהו ענין ציקי קדירה כנ\"ל), לכך בע\"ת גדולי' מצ\"ג שאין יכולים לעמוד במקום בע\"ת<sup data-n=\"7571\">550</sup>, ומשה זכה לתשובה קודם מותו<sup data-n=\"7572\">551</sup> דוקא כידוע. וזהו שלבש יעקב צ\"ע ב\"ע<sup data-n=\"7573\">553</sup> שנעשה ב[ע]\"ת<sup data-n=\"7574\">552</sup> כו' ולכך ויר\"ח ריח בגדיו ויברכהו שהוא תוס' ברכה שנעשה מבירורי' דרפ\"ח כו' והוא מטל השמים העליונים כו' כמ\"ש במ\"א, והכל מטעם הנ\"ל דבחי' ס\"ג דתהו למעלה מבחי' מ\"ה ולכך בע\"ת גדולים מצ\"ג כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן ביאור מא' הנ\"ל בענין בשכמל\"ו דאנשי יריחו היו כורכים את שמע כו' שלא היו אומרים בשכמל\"ו כמשה שלא אמרו, לפי שעיקר ירידה וצמצום דשם ב\"ן דמל' להיות שם כבוד מלכותו עד למטה לברר בחושך גמור בק\"נ כנ\"ל. ושרש משה הי' באור דח\"ע דתיקון דשם הוי' דאצי' וכמו שיהי' לע\"ל אך יעקב שאמר בשכמל\"ו שהוא בשביל הבירורים דרפ\"ח כיתרון האור מן היפוך החושך לאור דוקא כמו בע\"ת (לאחר שא\"ל השבטים כך אין בלבינו אלא אחד דיחו\"ת שוה ליחו\"ע שאז דוקא יכול להיות בירור החשך לאור כמו שיהי' לע\"ל ממש). ובאמת זהו מ\"ש כל הנק' בשמי ולכבודי כו', הרי א' בשמ\"י ולכבוד\"י ב' הדברים הללו יוכ[ל]לו כא' והוא הנק' בשמות<sup data-n=\"7575\">554</sup> דשם הוי' דתו\"מ שנק' שמי ממש שהן צ\"ג וכמו הקורא בתורה קורא בשמותיו<sup data-n=\"7576\">555</sup> ממש כו', וגם לכבוד\"י שזהו [כ]ענין בע\"ת להפוך [גם] חשך לאור (שהוא בחי' ב\"ן דנוגה שעולה בס\"ג דתהו) כנ\"ל, שעיקר הכבוד והתפארת הוא דוקא מן הרחוקים<sup data-n=\"7577\">556</sup> ביותר כשנעשים קרובים כמלך שכבש מדינה רחוקה שלא ידעו מגדולתו והיו מורדים ופושעים כו' יהפכו גם הם לעבדים שיש מזה רוממות וכבוד גדול יותר מביטול הקרובים כידוע (וכמו במ\"ת שהי' מזה שא' יתרו [שהי'] ראש לע\"ז<sup data-n=\"7578\">558</sup> עתה ידעתי<sup data-n=\"7579\">557</sup> כי גדול הוי' כו' כמ\"ש במ\"א). והוא מ\"ש לכבודי בגין דישתמודעי' לי' גם הרחוקי' שנפרדו מיחודו בבחי' ק\"נ שיהופך חושך לאור דוקא שזהו למעלה מן העונג דחכ' דתו\"מ כנ\"ל בבע\"ת, ולכך א' יפה שעה אחת<sup data-n=\"7580\">559</sup> בתשו' ומעש\"ט בעוה\"ז דוקא יותר מחיי העוה\"ב כו').\n<b>וזהו</b> המשל לבת מלך שהריחה ציקי קדירה שהוא התענוג הנעלם שיש בהיפוך החושך לאור בסוף מעשה הבירורים דרפ\"ח כו', תאמר יש לה גנאי פי' דהגם שיש לבת מלך העליון ריח ועונג נעלם בבירורי' [דרפ\"ח] כו' שנק' חושך למטה. אך אם",[["7571","550","<b>מצ\"ג שאין יכולים לעמוד במקום בע\"ת</b>: ראה ברכות לד, ב. לעיל פ' שמות מא, א. וש\"נ."],["7572","551","<b>ומשה זכה לתשובה קודם מותו</b>: נסמן לעיל פ' תצוה שמג, ד."],["7573","553","<b>צ\"ע ב\"ע</b>: טזיז: צ\"ג בגדי עשו."],["7574","552","<b>שלבש יעקב. . שנעשה ב[ע]\"ת</b>: נסמן לעיל פ' תצוה שכה, א."],["7575","554","<b>בשמות</b>: שם: בשמי."],["7576","555","<b>הקורא בתורה קורא בשמותיו</b>: נסמן לעיל פ' תצוה שנט, ד."],["7577","556","<b>והתפארת. . הרחוקים</b>: ראה גם שעה\"י קמג, א ובהערה 3. לעיל פ' משפטים רצד, ד."],["7578","558","<b>יתרו [שהי'] ראש לע\"ז</b>: ראה לעיל פ' יתרו ערב, ג. מאמרי אדה\"א שם."],["7579","557","<b>במ\"ת. . יתרו. . עתה ידעתי</b>: יתרו יח, יא. ראה לעיל פ' יתרו רעא, ד ואילך (ובהנסמן בריש המאמר שם). משפטים רצד, ד. מאמרי אדה\"א הנחות תקע\"ז ע' רכד. וש\"נ (ובהנסמן בריש המאמר שם)."],["7580","559","<b>יפה שעה אחת</b>: ראה אבות פ\"ד, מי\"ז."]]],[2300550725,"תאמר בבחי' דיבור בהתפשטות והתגלות גמור (כמו שיאמרו בשכמל\"ו בקול רם) שיגיע הארת אור האלקי בגילוי גם להיכלות דק\"נ יש לה גנאי, כמו שגנאי היא לבת מלך שתאמר להביא לה<sup data-n=\"7581\">560</sup> ציקי קדירה כו', כך יש בחי' גנאי ובזיון לבת מלך העליון גם מהיפוך החשך לאור דרע דק\"נ [הוא בחי'] פסולת גס ביותר. ואף שנהפך לטוב כבע\"ת אין כבוד למל' דקדושה להאיר במקום שפל כזה (וכנחש כרוך על עקבו<sup data-n=\"7582\">561</sup> כו' קודם הבירור דב\"ן דק\"נ דחויא קטיר לרגלוהי דנוק'<sup data-n=\"7583\">562</sup> [דוקא] <span data-k=\"pg\">תרו</span> ּ וכענין בא נחש על חוה<sup data-n=\"7584\">563</sup> כו', ואף לאחר בירור דנחה\"ק ע\"י תשו' נק' גנאי לבת מלך כו'). ואם לא תאמר בגילוי ולא יהי' התפשטות הרצון ותענוג בחכמה ומדות כלל ולא יהי' בירור זה דק\"נ (כמו כשאין או' בשכמל\"ו כלל), יש לה צער שהוא גרעון אור בהעדר העונג כמו כאשר חפץ ומשתוקק ומתאוה לדבר מה בהריח ריח ואינו משיגו (ומה גם כמו בחולה שמהעדר בריאותו לא יוכל לקבל חיות לנפשו ממאכלי' ומעדנים הטובים כי כל אוכל תתעב נפשו, ולא יוכל לפקח נפשו כ\"א בריח דבר חריף וקשה ומר שיריח ממנו ריח חזק להרגיש בו הלב והמוח יותר מבושם הטוב, וזהו כמו בזמן הגלות דכנ\"י שהוא בחי' בת מלך למעלה בחולת אהבה כו' ולא יש כח הבריאו' לחיות נפשו ממאכלים דתו\"מ כ\"א מן התשובה שזהו כטעם וריח מדבר חריף וחמוץ שמשיב לנפש בהתעלפה וכקטרת באפו כו'). וצער זה עושה גרעון בעצם הנפש מצד שהריחה כו' שלא יועיל התענוג שבמאכל וכה\"ג לפקח הנפש החלושה כ\"א בבע\"ת וכה\"ג, ואם תאמר יש לה גנאי להיות כבע\"ת [כו'], ולא יוכל להיות שלא יהי' לבת מלך שהריחה א' משתי אלה או גנאי או צער אם לא שיביאו לה עבדיה בחשאי ובצנעא מעין הרואי', דגנאי אין בזה כי עיקר הגנאי מפני הרחוקי' אבל לא לקרובים כעבדים המשרתים אותה וגם צער אין לה אחר שהשיגה לציקי קדירה להשיב נפשה כו'. והנמשל מזה למעלה דזהו שאו' בשכמל\"ו בחשאי שלא יתגלה גילוי אור כבוד מל' לק\"נ וכמ\"ש כבוד אלק\"י' הסת\"ר דבר<sup data-n=\"7585\">564</sup> וכתי' וכבודי לאחר לא אתן<sup data-n=\"7586\">565</sup> דיש גנאי בזה אף שיהופך חשך לאור, רק לע\"ל שיזוכך ויבוער הרע לגמרי. ועכ\"ז מתבררי' ועולים למאכל לפני בת מלך העליון בחשאי ובצנעא (כמו ותקם בעוד ליל\"ה דוקא שיורדת המל' בסתר המדריגות בהיכלות דק\"נ ותתן טרף כו' וכמו בשינה שמעכל המאכל ביותר גם מחלק הפסולת דוקא כו' כמ\"ש במ\"א) והוא שאו' בשכמל\"ו בחשאי שאין לה צער ולא גנאי וד\"ל.\n[יא]<b> והנה</b> ע\"ד כל הנ\"ל יובן ג\"כ למעלה יותר גם במל' דא\"ס כמו שהוא לפני צמצום הראשון כמ\"ש אני",[["7581","560","<b>לה</b>: טזיז: ליתא."],["7582","561","<b>וכנחש כרוך על עקבו</b>: ברכות ל, ב (במשנה). ראה תו\"ח ויצא קעח, ג."],["7583","562","<b>דחויא קטיר לרגלוהי דנוק'</b>: ראה ת\"ז תכ\"ו (עב, א). מאמרי אדה\"א דברים ח\"א ע' עז. וש\"נ. ח\"ב ע' תצג."],["7584","563","<b>בא נחש על חוה</b>: שבת קמו, א."],["7585","564","<b>כבוד אלק\"י' הסת\"ר דבר</b>: משלי כה, ב."],["7586","565","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."]]],[2300550728,"ראשון כו' כנ\"ל, שכמו שמל' דאצי' בבי\"ע נמשך ע\"י צמצום ומסך מפסיק מצד שאין ערך לבע\"ג לבלתי בע\"ג כנ\"ל, כך מבחי' מל' דא\"ס שנק' מלך יחיד שמצד עצמות הרוממות להיות מלך כ\"ע<sup data-n=\"7587\">566</sup> בקו\"ח הוא ע\"י צמצום הראשון שנק' מקו\"פ וחלל<sup data-n=\"7588\">567</sup> כו', שזהו ענין בשכמל\"ו למעלה שנמשך מבחי' ד' רבת\"י דאח\"פ בתכלית כו'. והיינו מח' ה[קדומה] דאנא אמלוך כו' בהתנשאות שחוץ ממנו, שבזה עצמו נמשך בחי' מקור הכללי לכל ההשתל' דקו\"ח בכללות שנק' מח' הכללי' כמ\"ש לכבודי בראתיו במחשבה כו'. והוא מצד טבע הטוב להטיב לזולתו שמזה יהי' נשלם שלימות דטוב העצמי, אע\"פ שנק' שלימותא דכולא<sup data-n=\"7589\">568</sup> כו' ואין דבר זולתו שישלים אותו, אבל זהו הי' מיני' ובי' שצמצם א\"ע להיות מלך גיאות לבש כו' שיהי' התפשטות מלוכה והתנשאות בחוץ ממנו ולכך <span data-k=\"pg\">1214</span> ּ הוצרך להיות צמצום ומק\"פ כו'. ולפי שעונג ברצון זה הוא [ב]ירידה ושפלות מעצם התענוג שבעצם מדת מלכותו (כשעשוע המלך בעצמו ממש כידוע) שמרומם לבדו כו', זהו כמשל לבת מלך שהריחה ציקי קדרה שהוא העונג היורד בטעם ושפל ביותר והוא מה שיהי' היפך חושך העליון לאור וישתמודעי לי' מתוך ההעלם וההסתר, שז\"ש לכבודי בראתיו כו' והוא ענין הירידה והצמצום במח' הכללית שא' והי' העולם בכללות (וכמו שא' ולעת נעשה בחפצו ורצונו הפשוט כל<sup data-n=\"7590\">569</sup> אזי מלך שמו נק' מל' כ\"ע כו'). וא\"ל לא יתכן בחי' ירידת עונג זה שבהתפשטות שחוץ ממנו כו', ומבואר למעלה דסיבת ההתפשטו' דמח' הכללי' במדת מל' בא ע\"י העונג העצמי שירד ונתצמצם בזה. ולפי שירידה גדולה היא לבת מלך מלכי המלכים כו', לזה א' תאמר פי' תאמר להתפשט במא' א[חד] דמח' הכללית שיהי' היפך חושך לאור יש לה גנאי להיות ראש לשועלים כו' בלבוש גיאות שאין לו ערך כלל, ולא תאמר שלא תצמצם במא' דמח' הכללית ולא יהי' דבר חוץ מן העצמות וממילא אין גנאי להיות ראש לעולמות (שנק' מלך זוטא מלך על עבדים שאין לו ערך למלך רב<sup data-n=\"7591\">570</sup> שנק' אגוסטו\"ס מלך על המלכים<sup data-n=\"7592\">571</sup> שקודם הצמצום כמו דכתי' נכון כסאך מאז כו' שלע\"ל יהי' אגוסטוס יושב ומלך עומד לפניו<sup data-n=\"7593\">572</sup> כמ\"ש ה' ימלוך לע\"ו<sup data-n=\"7594\">573</sup> וכתיב וע\"י יתיב כו'). אך אם לא תאמר להביא לה ציקי קדירה יש לה צער שבא מהעדר ע[ו]נג זה שיורד בהתפשטות שחוץ ממנו, כמו [ב]רחוקים ונפרדים דוקא שבביטול היש הנפרד ורחוק שיבוטל לאי\"ן אחר הצמצום יש בזה עונג חדש ונפלא יותר מעונג שבעצם הרוממות כשהוא מלך יחיד לבדו כו' כנ\"ל. וצער זה גדול<sup data-n=\"7595\">574</sup> מעונג שבעצם מדת מל' כו' (וגם יתפרש ע\"ד הנ\"ל במל' בבי\"ע",[["7587","566","<b>כ\"ע</b>: טז: כל עולמים."],["7588","567","<b>צמצום הראשון שנק' מקו\"פ וחלל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב."],["7589","568","<b>שלימותא דכולא</b>: ראה ת\"ז בהקדמה (יז, ב). עבודת הקדש ח\"א רפ\"ח."],["7590","569","<b>ולעת </b>[טז: לעת]<b> נעשה בחפצו. . כל</b>: נוסח אדון עולם."],["7591","570","<b>מלך זוטא. . למלך רב</b>: ראה זהר ויחי רלט, א. זח\"ג (תוספת) ש, א. ראה גם לעיל פ' וארא עה, ב. וש\"נ."],["7592","571","<b>אגוסטו\"ס מלך על המלכים</b>: ראה לעיל פ' בא קכב, א: שנק' קיסר."],["7593","572","<b>אגוסטוס יושב ומלך עומד לפניו</b>: ראה שמו\"ר רפכ\"ג. לעיל פ' בא ק, ג ובהערה 184."],["7594","573","<b>ה' ימלוך לע\"ו</b>: בשלח טו, יח."],["7595","574","<b>גדול</b>: בתו\"ח באים כאן עוה\"פ התיבות: מעונג. . צער גדול."]]],[2300550731,"ענין גנאי במה שצמצום הראשון שלמעלה [ב]בחי' חוש\"ך סתר\"ו<sup data-n=\"7596\">575</sup> יורד למטה ונק' חשך גמור דק\"נ בחי' חשמ\"ל דנוג\"ה התחתון דאת זלעו\"ז עשה האלקי' גם למעלה במק\"פ כו' כמ\"ש במ\"א) כי אין מלך בלא עם<sup data-n=\"7597\">576</sup> שיתפשט מלכותו בהתנשאות שחוץ ממנו דוקא (ובזה נשלם שלימות דרוממות העצמות כמו בשלטון דבר מלך לרחוקי' שכבש מחדש שבזה ניכר עצם הרוממות יותר) (ולכך לא יתכן המלוכה כ\"א על העבדים ולא על הבנים<sup data-n=\"7598\">577</sup> שהן נמשכי' מעצמותו ואינם בביטול יש נפרד אלא ביטול עצמי' וכך נש\"י שעלו במחה\"ק נק' בנים<sup data-n=\"7599\">578</sup> רק שנעשו עבדים<sup data-n=\"7600\">579</sup> שיפול בזה ענין הנ\"ל בחוץ ממנו) (ועוד ירצה במה שא' תאמר, לא על מח' הכללי' אלא מן המח' הכללי' לי\"מ בפרט כמו בבחי' חכ' ומדות שבמל' דבי\"ע, כך למעלה זהו ממח' הכללי' דמל' דא\"ס בקו\"ח שזהו בפרט שיוצא מן הכלל שזהו עיקר של התפשטו' המל' שיש מזה גנאי בירידה והשפלה, ולא תאמר לא תתפשט בפרט המאמרות <span data-k=\"pg\">תרז</span> ּ יש לה צער מהעדר העונג שיש במא' דפרט אע\"פ שנק' ציקי קדרה לגבי עצם מקור התענוגי' העצמי' כנ\"ל).\n<b>והנה</b> כדי שלא יהי' גנאי ולא צער הביאו לה בחשאי כו', שזהו שאו' בשכמל\"ו בחשאי ולמעלה היינו כבוד אלקי' הראשון הסתר דבר שיהי' בצנעא שלא יתגלה כבוד מל' העצמיי' כמו שהוא ממש רק לע\"ל כנ\"ל והוא כמו שהי' הוא ושמו מל' דא\"ס בעצם הרוממו', ועכשיו בא ירידת עונג זה העצמי' בקו\"ח כו' בהעלם ובחשאי בלא גילוי אור כי לא נשלם הבירור האחרון בהיפוך חשך הגס למטה שיש לה גנאי מזה כו' וגם למעלה ירידה ושפלות הוא כנ\"ל, רק בלחש ובחשאי בצלותא בלחש ע\"י הנשמות דצ\"ג שנק' קרובים שמביאים ומעלים מ\"ן מתפלות שלהם בבחי' ביטול היש לאין מחשך לאור באו\"ח לעורר למעלה בחי' העונג ורצון למל' בהתנשאות שחוץ ממנו (כמו בי\"פ דמלכיות בר\"ה<sup data-n=\"7601\">580</sup> שאומרים נש\"י דוקא מעוררים להעלם העונג שבצמצום דמל' להיות מלך גאות לבש כו', רק ביו\"כ שהוא מעין דעוה\"ב שנק' שבת שבתון<sup data-n=\"7602\">581</sup> כידוע אומרי' בשכמל\"ו בקול רם כמו שמע ישראל ממש שהוא ושמו באח\"פ אחר הבירור דחשמ\"ל התחתון שנהפך חושך העליון לאור ואינו בהסתר והעלם כלל למטה כמו למעלה ממש<sup data-n=\"7603\">582</sup> ולא נק' בחי' ירידה ושפלות כלל והוא שמהפך חושך עצמו לאור ומרירו עצמו למיתקא, ולא נק' ציקי קדרה בעונג מושפל אלא יערב לטעם מתוק כמטעמים ומעדנים והוא שיבא הע[ו]נג המורגש שיהי' לנשמות בעוה\"ב כמו סעוד' דלויתן כו' וד\"ל (וזהו שהביאו לה בחשא\"י הן הנשמות ולא מלאכים שנק' עבדים<sup data-n=\"7604\">583</sup> ממש אלא נשמות נק' עבדי הוי'<sup data-n=\"7605\">584</sup> כו' והן שנק' גבורי כח עושי דברו<sup data-n=\"7606\">585</sup> בבנין פרצוף שלם במל' בבי\"ע אחר דאזעיר גרמי'<sup data-n=\"7607\">586</sup> ונעשי' נקודה א' באצי' כו', ולכך המשמיע קולו בתפלתו<sup data-n=\"7608\">587</sup> זהו מקטני אמנה היינו עכשיו שצריך להיות בצנעא והסתר מאלקי' אחרים דנחה\"ק שלא יהי' גנאי כו', וזהו שהי' רחב\"ד מתפלל ונחש על עקיבו ולא הפסיק<sup data-n=\"7609\">588</sup> כו' וכך יש יח\"ס<sup data-n=\"7610\">589</sup> בכל דור בתפלתם גם עתה). (וגם משיח נא' בו והריחו ביראת ה'<sup data-n=\"7611\">590</sup> שיאיר בו מבחי' מל' דא\"ס עצמו שיהי' בלי העלם והסתר כלל ולכך נק' נורא מלך גדול על כל הארץ<sup data-n=\"7612\">591</sup> למטה כמו למעלה ממש, ויש גם עכשיו מיראה פנימי' כזו ביח\"ס בדור כידוע).\n<b>אך</b> הנה עדיין י\"ל במש\"א דהביאו לה בחשאי מהו התועלת מזה שעי\"ז לא יהי' לה גנאי וצער, הרי הצער יש לה ממה שלא תאמר ולא תתפשט במל' לרחוקי' דוקא והעדר התפשטותה זאת רק מצד הגנאי שהוא גורם הצער היפוך [העונג] העצמי דמל'. וגם יש לה גנאי אף שהביאו",[["7596","575","<b>שצמצום הראשון. . חוש\"ך סתר\"ו</b>: תהלים יח, כב. ראה גם לעיל פ' בא קכג, ג. וש\"נ."],["7597","576","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["7598","577","<b>המלוכה. . העבדים ולא על הבנים</b>: ראה שער היחוד והאמונה רפ\"ז."],["7599","578","<b>נש\"י. . נק' בנים</b>: שמות ד, כב. ראה יד, א. אבות פ\"ג, מי\"ד."],["7600","579","<b>נש\"י. . בנים. . עבדים</b>: ראה גם לעיל פ' משפטים רפה, ב ובהנסמן שם."],["7601","580","<b>בי\"פ דמלכיות בר\"ה</b>: ר\"ה לב, א (במשנה). ראה גם לעיל פ' בא צז, א. וש\"נ."],["7602","581","<b>ביו\"כ. . שנק' שבת שבתון</b>: אחרי טז, לא. אמור כג, לב. ראה גם לעיל פ' בא צד, ב. וש\"נ."],["7603","582","<b>ממש</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות: שהוא ושמו. . למעלה ממש."],["7604","583","<b>מלאכים שנק' עבדים</b>: ראה מקראי קדש לר' יוסף בר' בנימין סאמיגה (וויניציא שמ\"ו) ח\"א פ\"ג. ח\"ב פ\"ג. עה\"כ לבעל סדר הדורות מערכת עבד (מלאכים)."],["7605","584","<b>נשמות נק' עבדי הוי'</b>: ראה גם לעיל שצז, ב."],["7606","585","<b>גבורי כח עושי דברו</b>: תהלים קג, כ."],["7607","586","<b>דאזעיר גרמי'</b>: ראה זהר בלק קצא, א. מאמרי אדה\"א שמות ח\"ב ע' תמז. וש\"נ."],["7608","587","<b>המשמיע קולו בתפלתו</b>: ראה ברכות כד, ב."],["7609","588","<b>רחב\"ד מתפלל. . ולא הפסיק</b>: ראה תוספתא ברכות פ\"ג, ה\"כ. ירושלמי שם פ\"ה, ה\"א. מאמרי אדה\"א קונטרסים ע' שפה. וש\"נ."],["7610","589","<b>יח\"ס</b>: טז: יחידי סגולה."],["7611","590","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["7612","591","<b>נורא מלך גדול על כל הארץ</b>: תהלים מז, ג."]]],[2300550734,"לה בחשאי, כי הרי ירדה להסתתר במל' על עם להיות ראש לשועלים שזהו גנאי כו' ולא הועיל כלל מה שהביאו בחשאי, דאדרבה יש לה גנאי וצער, ואם לא הי' <span data-k=\"pg\">1216</span> ּ העלאה זו בחשאי לא הי' התפשטות כלל למטה לא הי' רק צער ולא גנאי כו'. ומה זה שהתקינו לומר בשכמל\"ו בחשאי שיותר טוב הי' אם שלא לומר כלל כמשה שלא אמר (מצד הגנאי) והי' צער בלא גנאי ואם כיעקב שאמר בשכמל\"ו בקול רם וגם שיש גנאי אין צער כו'. אך הנה זה הענין ש[הביאו] בחשאי [ש]הוא כמו תפלה בלחש זהו ענין המרירות וצער בתכלית הקצה כמו תפלת חנה שהיתה מרת נפש<sup data-n=\"7613\">592</sup> כו' וזהו העונג הנעלם וגנוז ומלובש בהיפוכו שהוא הצער ומרירות בתכלית על אשר לא יוכל להשיג את שאהבה נפשו באה\"ר בתענוגים ע\"כ יתמרמר מזה שזהו קצה השני שבעונג, שהוא במשקל שוה לפ\"ע העונג העצמי דוקא ונק' גבו' שבקו השמאל דעונג עצמי שימצא כחו בהיפוכו המנגד אליו כשנעדר ממנו הדבר האהוב שמתענג בו ביותר כו', כמו הבקשה במרירות הנפש ע\"ד שנחסר לו שנוגע לחיי נפשו בעצמות התענוג כחנה ששאלה בנים<sup data-n=\"7614\">593</sup> וכמבקש פרנסה ורפואה וכה\"ג שבהעדרם יגיע לעצמות נפשו, שלפ\"ע העונג כן הצער מהעדרו<sup data-n=\"7615\">594</sup> וכידוע הכלל דכל יסורים וצער זהו בא לפ\"ע האה\"ר בעונג עצמי שאם לא העונג בעצם בדבר זה לא הי' בצער ויסורים כלל, ולכך יכול אדם לקבל כל יסורים וצער באהבה ורצון כדי שיגיע להעונג שיש לו בזה וכה\"ג (והיינו משל ודמיון להבין ענין הנ\"ל במ\"ש לא תאמר יש לה צער היפוך",[["7613","592","<b>חנה שהיתה מרת נפש</b>: שמו\"א א, י."],["7614","593","<b>כחנה ששאלה בנים</b>: שמו\"א א, יא."],["7615","594","<b>שלפ\"ע העונג כן הצער מהעדרו</b>: ראה אגה\"ק סכ\"ט (קמט, ב). שעה\"י קיג, א. קכו, א. קמז, א. מאמרי אדה\"א הנחות תקע\"ז ע' עט. וש\"נ."]]],[2300550737,"התענוג שהוא קו השני שמלובש במנגד לעונג שבמדת מל' כו' (וכמשי\"ת), וכמרירות וצער דאב על הבן בריחוקו ממנו זמן רב כו' וכאובד אבן יקר ביותר וכדואג ומיצר בהעדר פרנסתו שמקבל בעצמו יסורים וצער הנפש לייגע עצמו בכל מלאכה ועבודה בבית ובשדה עד מיצוי הנפש ממש כדי שישיג תאוות נפשו בעושר והון, דודאי קודם שהשיג הריוח והעושר במו\"מ שלו נפשו בעצבות ומרירות במסתרים תבכה נפשו עד שמתייאש לגמרי ואז יהי' בצער הנפש המנגד בתכלית לעונג המופלא שהי' בנפשו להשגת הון יקר כו'. וכמו ילך ובכה נושא משך הזרע<sup data-n=\"7616\">595</sup> כו' בכיה זו לפ\"ע העונג הנפלא שיחפוץ בהצלחת התבואה כרצונו ולפ\"ע בכי' ומרירות זו עד שאו' נואש כו' [כן] בא יבא ברנה ושמחה ותענוג אח\"כ בהצלחת רב אלומותיו וכה\"ג וד\"ל.\n<b>ולפ\"ז</b> אין העונג שבסוף בירור<sup data-n=\"7617\">596</sup> והצלחה רק כפי רצונו ותאוותו שהי' בתחלה רק שהגיע לזה ע\"י בכיי' ומרירות היפך העונג במה שנתייאש ובמיצוי הנפש כו', לפי שצער ומרירות זו ה[י]א משקל א' ממש עם בחי' העונג שיש לו בדבר בלי תוס' וגרעון, ואנו רואים בחוש שיש יתרון אור בעונג שבסוף אחר היגיעה ופיזור הנפש ובכיה ומרירות מהיפוכו כשישיג עושר והצלחה מיגיע כפיו יתענג בע[ו]נג נפלא שלא הי' לו עונג כזה בתחלת חפצו להתעשר כו' (וכן בכבוד וגדולה כבן מלך ושר אין עונג זה שברוממות בעצם ערך לגבי השגת הכבוד וגדולה ושררה שבא לו ע\"י יגיעתו ועבודתו והשכלת<sup data-n=\"7618\">597</sup> נפשו מנגד במלחמה עד מיצוי הנפש והצליח (כעובד אדמה) שישבע ויתענג בעונג גדולה זו <span data-k=\"pg\">תרח</span> ּ יותר ממה שהי' לו גדולה וכבוד בעצם כו', וכמשל הנ\"ל [ב]בן מלך ששלח לו<sup data-n=\"7619\">598</sup> אביו למרחקים שילמוד אומנות ויפרנס א\"ע ביגיע כפיו דוקא כו' שבזה נשלם שלימות דחכ' וכבוד שהי' לו בבית אביו מצד העצם כו'. וכך הוא ממש בעסק החכמה והלימוד, דכל העונג הגדול שיש בחכמה שמשכיל שכליים עמוקים שתאיר פניו בעונג נפלא מחידוש השכל מאי\"ן בכח חכמתו העצמי' שנק' משכיל כו', שזהו עונג דאו\"י שהולך בקל<sup data-n=\"7620\">599</sup> מלמעלה למטה [כמו] בהברקה במושכל ראשון מצד כח עצם החכ' כו', אין לעונג וחכמה זו ערך לעונג שבחכמה שמצא ע\"י יגיעה רבה ועצומה עד מיצוי הנפש בלתי השגה מצד עוצם הספיקות והמבוכות בקושיות רבות שמעלימים בהעלם אחר העלם לאמיתית עומק השכל עד שאומר נואש כענין מה פשפש\"ת<sup data-n=\"7621\">600</sup> כו' ותכלית הידיעה שלא נדע<sup data-n=\"7622\">601</sup> וכה\"ג, אזי דוקא יבוא על אמיתי' עומק החכמה על בוריו",[["7616","595","<b>ילך ובכה נושא משך הזרע</b>: תהלים קכו, ו."],["7617","596","<b>בירור</b>: טזיז: בריוח."],["7618","597","<b>והשכלת</b>: יז: והשלכת."],["7619","598","<b>ששלח לו</b>: טז: ששלחו. יז: ששלח."],["7620","599","<b>בקל</b>: טז: בקו. יז: בקול."],["7621","600","<b>מה פשפש\"ת</b>: זהר בהקדמה א, ב."],["7622","601","<b>ותכלית הידיעה שלא נדע</b>: לעיל פ' בא צט, א: מא' החכם — ראה בחינות עולם ח\"ח, פ\"ב. עקרים מאמר ב, ספ\"ל. של\"ה מס' שבועות בהג\"ה קצא, ב."]]],[2300550740,"שלא הי' ביכולת כלל בעצם כח החכ' להשכילו וכידוע במ\"ש הרמב\"ם דאין עונג גדול [כ]התרת הספיקות<sup data-n=\"7623\">602</sup> כו' וכמ\"ש בזהר למחכ\"ה למאן דדייק מילי' דחכ' להתיר ולתרץ הקושי' והספיקות המעלימים עד שיכלה כל כח שכלו מיגיע ועמל זה, שזהו שנק' עמל תורה ו[כ]ממית עצמו עליה כו' אז יגיע לאור העומק בחכ' שיש בזה ע[ו]נג נפלא שאין כמוהו בכל עונג שבחכ' מצד העצם כו', וכמו בהשגת הון יקר מצד היגיעה ועמל בנפשו ביותר שיערב לנפש יותר מכל הון יקר שהי' ניתן לו במתנה כו' כנ\"ל (וזהו הרוצה לחיות ימית א\"ע ). וזהו יתרון מעלת או\"ח דתענוג הבא מן ההיפוך שהוא היסורים וצער ביגיעתו במיצוי הנפש יותר מעצם התענוג דאו\"י שבתחלה כו', אע\"פ שערך היסורים וצער בהיפוך העונג אינו אלא לפ\"ע העונג בעצם לבד כנ\"ל וד\"ל.\n<b>וכך</b> יובן גם בנש\"י שעלה במחה\"ק שנק' בת מלך למעלה דכ\"י [בני מלכים] הן<sup data-n=\"7624\">603</sup> כו' שהי' שם בבחי' עונג העצמי' ושעשועי' עצמיי' כבן שאביו משתעשע בו כו' וירדו למרחקים בנה\"ט דק\"נ שמסתיר אלקו' לגמרי כו' עד שאו' נואש בנפשו ומתמרמר ביותר על ריחוקו ממקורו העצמי', וזהו המרירות העצומה שלפ\"ע ההתקשרות דאה\"ר בתענוגי' ושעשועים למעלה. אך באמת יש יתרון אור גדול באמצעות המרירות ובכי' בנה\"א בבחי' יאוש כילך ובכה כו' שיבא מזה אח\"כ העונג הנפלא מאשר בא לקירוב אחר הריחוק דוקא כנ\"ל בעונג דאו\"ח הבא מן ההיפוך המנגדו מטעם הנ\"ל (וכיוסף צ\"ע שנאבד מיעקב<sup data-n=\"7625\">604</sup> שהצדיק אבד בגלות[א]<sup data-n=\"7626\">605</sup> ענו בכבל רגלו<sup data-n=\"7627\">606</sup> ואח\"כ שעלה לגדולה מן ההיפך נתגלה ליעקב שחי רוח יעקב ביותר מעונג שהי' לו בהיותו אצלו בשעשועי' עצמיי' י\"ג<sup data-n=\"7628\">607</sup> שנה<sup data-n=\"7629\">608</sup> כו'). וזהו שאין מתפללי' אלא לפ\"ע כובד ראש<sup data-n=\"7630\">609</sup> ומרירות שקודם זה וכתיקון חצות כו', וז\"ש בבכי יבואו בבכי' של שמחה וכן מן המשפי\"ע למקבל בגלות נתעורר בחי' הפנימי' דאה\"ר בעונג יותר נפלא וזהו דאחית תרין דמעי[ן]<sup data-n=\"7631\">610</sup> כו'. וזהו ולבי ער משום דרשפי' רשפי אש<sup data-n=\"7632\">611</sup> יותר בגלותא והלואי כן בקדש חזיתיך<sup data-n=\"7633\">612</sup> כידוע ומבואר במ\"א, וע\"כ קול דודי דופ\"ק ג\"כ בהתגברות <span data-k=\"pg\">1218</span> ּ התענוג מצד הריחוק שהי' עד כאן כו' וד\"ל.\n[יב]<b> ובכ\"ז</b> יובן בתוס' ביאור ענין מה שהריחה ציקי קדרה שזהו כמו עונג שבא מצד ההיפך כמו ביגיעה ועמל הנפש המנגדו שהוא בהיפוך חשך לאור, והיינו באמצע[ו]ת המל' על עבדי' ב[ע]\"ג כו' כנ\"ל שרחוק מערך העונג בעצם כמו שהבן אצל האב אוכל מעדנים כו', [ו]להיות שגדול יותר עונג זה עצמו",[["7623","602","<b>במ\"ש הרמב\"ם דאין עונג גדול [כ]התרת הספיקות</b>: כ\"ה גם במאמרי אדה\"א ויקרא ח\"א ע' קי. וש\"נ. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680441\" data-slug=\"torat-chaim\" data-id=\"2300680441\">תו\"ח מקץ רכה, ד</a> הערה 64."],["7624","603","<b>דכ\"י [בני מלכים] הן</b>: שבת סז, א."],["7625","604","<b>וכיוסף צ\"ע שנאבד מיעקב</b>: ראה וישב פל\"ז ואילך."],["7626","605","<b>שהצדיק אבד בגלות[א]</b>: ישעי' נז, א. ראה זהר שמות יא, א."],["7627","606","<b>ענו בכבל רגלו</b>: תהלים קה, יח."],["7628","607","<b>י\"ג</b>: יז: י\"ז."],["7629","608","<b>י\"ז שנה</b>: וישב לז, ב."],["7630","609","<b>שאין מתפללי'. . כובד ראש</b>: ברכות ל, ב (במשנה)."],["7631","610","<b>דאחית תרין דמעי[ן]</b>: ראה זהר שמות ט, א ובדרך אמת שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680168\" data-slug=\"torat-chaim\" data-id=\"2300680168\">תו\"ח תולדות קנא, ב</a> הערה 2."],["7632","611","<b>דרשפי' רשפי אש</b>: נסמן לעיל פ' תצוה שלז, ג."],["7633","612","<b>והלואי כן בקדש חזיתיך</b>: נסמן לעיל פ' תצוה שלז, ד."]]],[2300550743,"כשמלובש בקו השמאל דגבו' המנגד לעונג כמו ביגיעה ומיצוי הנפש בחכמה ופרנסה כנ\"ל שבא אח\"כ ביתרון מעלה רבה מעונג שבתחלה כנ\"ל, זהו ענין שהריחה ריח התענוג המשיב את הנפש כציקי קדירה שהוא הבירורים [ב]עבודה קשה [כ]טעם מר וקשה דצ\"ק<sup data-n=\"7634\">613</sup> שבהיפך לעונג כו' יש ריח המשיב ומפקח לנפש יותר בבחי' או\"ח שלמעלה מעונג דאו\"י בעצם התענוג כנ\"ל. וזהו תאמר בהתפשטות בהיפך זה המנגד לעונג יש לה גנאי שאין דרכה של ב\"מ<sup data-n=\"7635\">614</sup> לפחיתות ערך מזון כזה שבא בכליון ופיזור הנפש כו' והוא כעבודת עבד בעמל נפשו כמו וכי ימכור [איש את] בתו לאמ\"ה<sup data-n=\"7636\">615</sup> כו'. לא תאמר יש לה צער בהעדר העונג זה שיש בו אח\"כ ביתרון מעלה כשבא מתוך ההיפוך כנ\"ל, הביאו לה בחשאי והוא כמו מרירות הנפש בצלותא בלחש שבא באמצעות העונג שמלובש בקו השמאל [כרשפי'] רשפי אש הצמאון בגלותא יותר מצד הריחוק כו' כמו ותתפלל חנה ובכה תבכה<sup data-n=\"7637\">616</sup> כו' ועי\"ז דוקא תעלה ליתרון האור בעונג שבסוף כו'. אך מרירות זו צריך שיהי' נעלם וגנוז בתוך קירות הלב והוא בדיבור בלחש דוקא ולא ישמיע קולו בתפלתו שלא יהי' גנאי שיאחזו בזה החיצוני' כו', וע\"י העלא' מ\"ן כזה במרירות ושפלות מן ההיפוך המנגד כו' שהוא קו השמאל דגבו' שבתענוג שעולה באו\"ח (כתנוע[ת] עוצב שבניגון ושיר שעושה רושם התפעלות לעורר את האהבה יותר במשפיע כו'), כך יהי' אתעדל\"ע במל' למעלה שנק' בת מלך להיות השפלתה בקו השמאל [ש]בעונג להריח צ\"ק כו' להיות ראש לשועלי'<sup data-n=\"7638\">617</sup> בחשאי והוא שאו' בשכמל\"ו בחשאי, ואין לה גנאי לפי שהביאו הנשמות העלא' מ\"ן זה בחשאי כו', ולא צער מהיפוך העונג ממה שלא תאמר שהרי זהו העונג המלובש בהיפוכו שעי\"ז יהי' יתרון מעלה במל' בעצם והוא להפוך חושך לאור ביגיעה ועמל כו' שזהו עיקר הכוונה בהעלם העונג במל' על הרחוקי' דוקא (כמלך אלקי' על<sup data-n=\"7639\">618</sup> כו') שהוא בגלות השכינה כדי לברר כו' שעולה אח\"כ יותר מעונג דב\"מ למעלה קודם הצמצום הראשון, ולכך לע\"ל יאמרו בשכמל\"ו בקול רם לפי שיעלה עונג זה שהי' במנגדו ביתרון אור מן החושך למעלה מתענוג דאו\"י כנ\"ל וד\"ל<sup data-n=\"7640\">619</sup> (והיינו ע\"י קבלת מ\"ש בא' בשכמל\"ו בחשאי דוקא שהוא בשפלות והכנעה כעבד לעול פשוט בלתי עונג ואהבה כלל רק מיראה שמזה דוקא בא העבודה ביגיעה ומיצוי הנפש בעול תו\"מ כל היום, משא\"כ ע\"י [האהבה ו]הדביקות בהגבהת הלב מיד יפול מכל עבודה אף מאהבה כו' וילך בפר\"ע בהוללות כו' וכידוע דבר זה בחוש הנסיון לכל העובדים ועוסקים בעבודת ה' וחפיצים בקרבת אלקי' באמת לאמיתו כו'. וזהו באמת דבר חידוש ונפלא אשר נראה בעליל שכל [ה]עבודה <span data-k=\"pg\">תרט</span> ּ האלקי' עכשיו",[["7634","613","<b>דצ\"ק</b>: טזיז: דציקי קדרה."],["7635","614","<b>ב\"מ</b>: טז: בת מלך."],["7636","615","<b>וכי ימכור [איש את] בתו לאמ\"ה</b>: משפטים כא, ז."],["7637","616","<b>ותתפלל חנה ובכה תבכה</b>: שמו\"א ב, א. א, י. וראה לעיל פ' משפטים חצר, א הערה 208."],["7638","617","<b>במל'. . ראש לשועלי'</b>: ראה ז\"ח (מדהנ\"ע) שה\"ש עא, א. לעיל פ' וארא נד, ב הערה 72."],["7639","618","<b>כמלך אלקי' על</b>: תהלים מז, ט."],["7640","619","<b>כנ\"ל וד\"ל</b>: טז: כו'. יז: כנ\"ל."]]],[2300550746,"הוא רק בקו השמאל דגבו' שבתענוג האלקי שמלובש בהיפוכו המנגדו, והוא כמו המרירות ועוצב גם בקול וניגון בתפלה עד שגם בהתענג[ם] על ה' בשבח[ו] ש\"מ<sup data-n=\"7641\">620</sup> ונפלאותיו וגדולתו יבא לבחי' מרירות ושפלות על ריחוקו כמו מה תשתוחחי נפשי<sup data-n=\"7642\">621</sup> כו' מתי אבא ואראה פני אלקי'<sup data-n=\"7643\">622</sup>, וכה\"ג צמאון ברשפי אש בקו השמאל דגבו' באו\"ח דתענוג כו' (כמו מ\"ש<sup data-n=\"7644\">623</sup> טבעי'). משא\"כ בזמן הבית הי' עבודתם האלקי' בשמחה וטוב לבב מרוב כל באה\"ר בדביקות ולהב בתענוגים בחדוה וקירוב ולא בעוצב ומרירות כלל וגם<sup data-n=\"7645\">624</sup> מזה הי' יסוד עבודתם כל היום בתו\"מ ג\"כ בשמחה ועונג בעצם כו'. וזהו בבכי יבואו בשמחה שמתוך בכיה כו', וכך הוסד כל יסוד ושרש המשכות אלקות בתו\"מ שיבא מן ההיפוך המנגד דוקא ביגיעה ועמל תורה בעומ\"ש לבד שזהו שהקים עולה של תומ\"צ (כמשי\"ת). וכל זה לפי שאור אותו העונג האלקי העצמי' שבקירוב ושעשועי' העליונים בעצמות התענוג נמשך וירד ונתלבש בהיפוכו המנגדו שזהו המרירות שיתמרמר בנפשו על הריחוק אף בצ\"ק<sup data-n=\"7646\">625</sup> כנ\"ל, לפי שמלמעלה למטה מן המשפיע למקבל במל' דאצי' בבריאה ומל' דא\"ס בקו\"ח כו' הושפל וירד מעונג העצמי' דמדת מל' העצמי' ממש שנק' שעשועי המלך בעצמו להיות מתלבש בהיפוכו בקו השמאל דגבורות שבעונג זה, והוא להיות מלך על עם כו' בבחי' ירידה ושפלות היפוך העונג שברוממות העצמות שנק' זי\"ו השכינה כו', ואמנם מלובש בזה העונג היותר נעלה שבא מהיפוך החש\"ך לאור באו\"ח כמו מעמל ויגיעה וכמו עונג ביטול של הרחוקים כנ\"ל וד\"ל).\n<b>והנה</b><sup data-n=\"7647\">626</sup> עם כל הנ\"ל יובן ג\"כ מ\"ש לע\"ל בנה\"ד נגיד ונפיק מן קדמוהי [כו' מקדמוהי] ממש כנ\"ל שזהו מדבר בגילוי אור דכתר מל' דא\"ס כמו שהוא ברוממות העצמות קודם צמצום הראשון כנ\"ל שע\"ז אמר נכו\"ן כסא\"ך מאז מעולם דא\"ס כו', ולע\"ל יהי' זה הגילוי דאור העצמות דא\"ס ב\"ה למטה כמו למעלה ממש וכשעשועי המלך בעצמו כו'. וזהו וע\"י יתיב לבושי' כתלג חיור כו' כורסי' כו' (וגם עכשיו זהו גילוי אור דמל' דאצי' בגעה\"ע [דמל'] דבריאה שנק' זיו השכינה כנ\"ל), והרמז בזה להיות שכל עיקר ירידת העונג העליון העצמי בקו השמאל בגבו' דבחי' ב\"ן דנוג\"ה שיהופך מחושך לאור (ע\"י התלבשות המל' בד' גליות לברר לב\"ן דנוג\"ה שהן ד' נהרות<sup data-n=\"7648\">627</sup> דעדן כידוע כו') שלזה יהי' הכסא דע\"י מאש דוקא וגלגל[י] הכסא נ[ו]ר דלוק כו', שזהו שנמשך גבורות דאש שלמעלה",[["7641","620","<b>ש\"מ</b>: של מקום."],["7642","621","<b>מה תשתוחחי נפשי</b>: תהלים מב, ו. יב. מג, ה."],["7643","622","<b>מתי אבא ואראה פני אלקי'</b>: תהלים מב, ג."],["7644","623","<b>מ\"ש</b>: טז: מרה שחורה. ראה גם לעיל פ' בשלח רכה, ג. וש\"נ."],["7645","624","<b>וגם</b>: טזיז: ודוקא."],["7646","625","<b>בצ\"ק</b>: יז: בצ\"ג."],["7647","626","<b>והנה</b>: יב נרשם: זיין [ו: נרשם לעיל על יד הערה *464. ח: נרשם לקמן על יד הערה 663]."],["7648","627","<b>בד' גליות. . ד' נהרות</b>: ראה ב\"ר פט\"ז, ד. לעיל פ' שמות לו, ד. מ, ג."]]],[2300550749,"להיות בבחי' נורא כמ\"ש כי ה' עליון נור\"א<sup data-n=\"7649\">628</sup> מלך גדול כו' כמו בר\"ה שנק' כס\"א<sup data-n=\"7650\">629</sup> כו' ששמך נור\"א על כל כו'. והיינו מצד בחי' העונג שבא בהיפוכו להיות מלך על עם כו' כנ\"ל כמו העונג שמלובש בצער ומרירות מהיפוכו כנ\"ל שמזה יבורר ויהי' עונג נפלא יותר כנ\"ל, אך זהו שיהי' בבחי' או\"ח דאש לוהט שבכסא דע\"י שמזה נמשך הפחד ויראה כמו עכשיו במלאכי' שזעות מחיל כסא<sup data-n=\"7651\">630</sup> (כמשי\"ת).\n<b>וזהו</b> ענין הנהר דינור דנגיד ונפיק מקדמוהי כו', דהנה כמו שהכסא <span data-k=\"pg\">1220</span> ּ שגלגלוהי של אש שזהו לפי שהוא כורסייא דדינא<sup data-n=\"7652\">631</sup> לדון הרשעים בגבו' שבמל' (שנק' תכלת<sup data-n=\"7653\">632</sup> אשא תכלא<sup data-n=\"7654\">633</sup> כו') שבא מבירורי' דרפ\"ח כו' מגבו' דש[ם] ב\"ן בגליות כו' והוא היפך הכסא דחסד העצמי' שע\"ז א' והוכן בחס\"ד כסא<sup data-n=\"7655\">634</sup> כו' וכן נכון כסאך מאז כו' בבחי' התענוג שבחסדי' דאו\"י שבעצמות ממש כו' כי אמרתי עולם חס\"ד יבנה כו'. אך בתשלום הבירורי' דנוג\"ה ע\"י עומ\"ש דש[ם] ב\"ן דקדושה יהי' כסא של דין כמו בר\"ה שנק' מלך המשפט<sup data-n=\"7656\">635</sup> כו' כך יהי' כסא דע\"י לע\"ל דכתי' וכרסוון רמיו<sup data-n=\"7657\">636</sup> מגבוה לנמוך בהתלבשות בקו השמאל דגבו' דע\"י כו'. וזהו ענין הנהר דינור שהוא היפך דנה\"ר שיוצא מעדן העליון שיוצא ונמשך מעצמות התענוג הפשוט שבשעשועי המלך בעצמו כמו שיהי' בעוה\"ב שנא' בעדן עין לא ראתה כו', ונהר זה הוא בחי' בינה<sup data-n=\"7658\">637</sup> שעונג העצמו' מורגש בו כמו השגת הנשמות בג\"ע עכשיו [מזי\"ו] ועונג העצמי<sup data-n=\"7659\">638</sup> דמל' דאצי' שנק' זיו השכינה שמקבלים מבינה שבמל' כו' כמו נהרי אפרסמונא דכיא<sup data-n=\"7660\">639</sup> כו' כידוע, וכמו ונח\"ל עדני\"ך תשקם<sup data-n=\"7661\">640</sup> כו' וזהו כמו שנמשך מלמעלה למטה בבחי' או\"י דתענוג וחכ' כמו שהיא בעצמו' המאציל כנ\"ל, אבל ביריד' והתלבשות העונג הזה עצמו בהיפוכו כמו בצער ומרירות מצד המנגד לעונג כו' כנ\"ל או יגיעה ועמל וכך להיות ראש לשועלים ע\"י צמצום העצמו' כו' זהו שנעשה מזה בחי' גבורות דאו\"ח שהוא בבחי' אש שורף ודולק כו'. וכך הוא ענין המשכת נה\"ד זה דנגיד ונפיק כו' דהיינו כמו שיוצא הנהר מעדן בבחי' חסדי' דתענוג דאו\"י כך נמשך בהיפך בהתלבשות בקו השמאל דגבורות שבתענוג העליון והוא נה\"ד ממש דנגיד ונפיק מן קדמוהי ממש שהוא בחי' עתיק כו' שהוא המשכה עצמי' דאלקו' עצמו מבחי' התענוג בעצם רק שיוצא מהיפוכו כמו מבחי' מרירות וצער המנגד לעונג שבא בבחי' או\"ח [בבחי'] רשפי אש דוקא כמו רשפי' רשפי אש בגלות דוקא כנ\"ל וד\"ל.",[["7649","628","<b>כי ה' עליון נור\"א</b>: תהלים מז, ג."],["7650","629","<b>בר\"ה שנק' כס\"א</b>: ראה גם לעיל פ' בשלח רלג, ב ובהערה 731."],["7651","630","<b>שזעות מחיל כסא</b>: ראה פיוט והחיות במוסף [בנוסח הקדושה אשכנז) לר\"ה."],["7652","631","<b>כורסייא דדינא</b>: לשון הזהר קדושים פה, ב. צט, א. בהעלותך קמט, ב."],["7653","632","<b>שבמל'. . תכלת</b>: ראה זהר (רע\"מ) צו לג, א. ע\"ח (שער סדר אבי\"ע) שמ\"ז, ספ\"ה. פע\"ח (שער הציצית) ש\"ג, פ\"ד. מאמרי אדה\"א שמות ח\"ב ע' תרעה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670437\" data-slug=\"torat-chaim\" data-id=\"2300670437\">תו\"ח בראשית מא, ג</a> ובהערה 19."],["7654","633","<b>אשא תכלא</b>: זהר (רע\"מ) צו כט, ב. בראשית נא, א."],["7655","634","<b>והוכן בחס\"ד כסא</b>: ישעי' טז, ה."],["7656","635","<b>בר\"ה שנק' מלך המשפט</b>: ברכות יב, ב."],["7657","636","<b>וכרסוון רמיו</b>: דניאל ז, ט [ושם: כרסון]."],["7658","637","<b>ונהר. . בינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["7659","638","<b>שעונג העצמו'. . העצמי</b>: טז: ליתא. ומובא לקמן על יד הערה 655."],["7660","639","<b>נהרי אפרסמונא דכיא</b>: ראה תענית כה, א. לעיל פ' שמות לד, ב. וש\"נ."],["7661","640","<b>ונח\"ל עדני\"ך תשקם</b>: תהלים לו, ט."]]],[2300550752,"<b>אך</b> הנה עדיין י\"ל איך נמשך בחי' גבורות דאו\"ח דאש העולה מלמטה למעלה להיות כנה\"ד שהולך ונמשך כמו בהמשכה דאו\"י מגבוה לנמוך כמ\"ש דנגיד ונפיק מקדמוהי כו' שזה אינו אלא בטבע המים ולא באש כו', ואמנם הענין מבואר במ\"א ע\"פ ואני אהי' לה חומת אש סביב<sup data-n=\"7662\">641</sup> כו' דכל בחי' העלא' מ\"ן דכנ\"י בגלות בבחי' רשפי אש דרץ לבך כו' שבא מצד המרירות ולב נשבר בעומק מפני הריחוק שנק' אשא אוכמא<sup data-n=\"7663\">642</sup> בשחור שבדם שמחמת רוע לב כאש השורף ומכלה כו' שעולה למעלה בבחי' או\"ח וזהו<sup data-n=\"7664\">643</sup> יהי' לע\"ל בחי' שוב מן המשפיע למקבל בבחי' מקיף דחומת אש כו' (והיינו בחי' רח\"ר שבא ונמשך בבחי' גבורות דאש כמו כי נכמרו רחמיו<sup data-n=\"7665\">644</sup> כו' והוא חומת אש דתורה שמגין ומפסיק כו'). וכך הוא ענין המשכת הנה\"ד זה שהולך ונמשך בבחי' שוב להיות מזה ביטול במציאות לנשמות ומלאכים כמו הושיט אצבעו הקטנה ביניהן ושרפן<sup data-n=\"7666\">645</sup> הרי בחי' אש האלקי שורף ומכלה לאש דמלאכים ונק' אש אוכלה<sup data-n=\"7667\">646</sup> וכן יש אש שותה כמים <span data-k=\"pg\">תרי</span> ּ שבאש שנמשך כנהר אש לטבול בו הנשמות. וזהו [כ]דוגמא דנהר דינור דעכשיו שהוא בסמוך לג\"ע לטבול בו הנשמות שיבאו בבחי' ביטול במציאות בכליון מכל בחי' יש ולגרמי' כו' קודם עלותם לקבל שכרם ליהנות מזיו השכינה כו'.\n<b>ושרש</b> הענין הוא לפי שהטעם מה שהמשכה דנה\"ד זה יוצא מבחי' הגבו' שבתענוג הוא<sup data-n=\"7668\">647</sup> כמו [אש] המרירות מן ההיפך בנשמות, שזהו מבחי' הרצוא שלהם נעשה מזה בחי' שוב להיות טובלים בו קודם שיהנו מזיו כו' (כמשי\"ת). היינו מפני שבחיות נאמר והחיות רצוא ושוב בחי' הרצוא הוא בבחי' ההסתלקות למעלה במקורו בלתי מתיישב ומתפשט כלל באו\"כ ומיד אחר הרצוא שוב שמתפשט ונסוג אחור להיות האור מתיישב בכלי דוקא, שזהו כענין אהוי\"ר שמבחי' גודל [הפלאת התלהבות] האהבה והתשוקה רץ לבך לצאת מן הכלי לגמרי מגודל התשוקה ואה\"ר הנפלאה כו' ובהגיע למקורו מפני שמתקרב ביותר תפול בלב היראה ופחד אלקי' מגודל ביטול המציאות מצד הקירוב כמו וירא העם וינועו ויעמדו מרחוק<sup data-n=\"7669\">648</sup> שמחמת גודל הפחד יתרחקו ממעמדם וקרבתם למעלה ויהיו נסוגי' אחור להתיישב בכלי גופם כו', וזהו בחי' השוב דמלאכי' כמו בעמדם תרפינה כנפיהם<sup data-n=\"7670\">649</sup> ולא יוכלו לעלות עוד בתשוקה למעלה אלא יהי' כמו בחי' דומם [לגמרי] כו'. וכך הוא כמו בענין החיות רו\"ש במלאכים יש בכל בריאה ובריאה הסתלקות והתפשטות שזהו כרו\"ש ממש, וכמו דפיקו דלבא ברוח ואש ביסוד אש ומים כלולים יחד שהחיות שבדם דופק להסתלק כטבע האש שעולה ויורד [מיד] בבחי' שוב להאיר בכלי",[["7662","641","<b>ואני אהי' לה חומת אש סביב</b>: זכרי' ב, ט [בדילוג]. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'ג. ע' א'כג ואילך. שע\"ת פד, ב. לעיל פ' בשלח רלח, ב ואילך."],["7663","642","<b>אשא אוכמא</b>: זהר בראשית טז, א. (סבא) משפטים קיד, א. (רע\"מ) אמור צט, א. בהעלותך קנד, ב."],["7664","643","<b>וזהו</b>: טזיז: מזה."],["7665","644","<b>כי נכמרו רחמיו</b>: מקץ מג, ל."],["7666","645","<b>הושיט אצבעו הקטנה </b>[טזיז: קטנה]<b> ביניהן ושרפן</b>: סנהדרין לח, ב. ראה גם לעיל פ' שמות ל, ב. וש\"נ."],["7667","646","<b>אש אוכלה</b>: ראה יומא כא, ב. ראה גם מאמרי אדה\"א נ\"ך ע' טז וע' כב."],["7668","647","<b>הוא</b>: טז: זהו. יז: דוקא שזהו."],["7669","648","<b>וירא העם וינועו ויעמדו מרחוק</b>: יתרו כ, טו. ראה גם לעיל פ' בשלח קסד, ג. וש\"נ."],["7670","649","<b>בעמדם תרפינה כנפיהם</b>: יחזקאל א, כד. כה. ראה לעיל פ' בא קיח, ד. וש\"נ."]]],[2300550755,"ולהתיישב בכלי הגוף וכך חוזר חלילה, וכך הוא בנשימ[ה] שבחוטם בהתפשטות והסתלקות כי נשמת רוח החיים באפו<sup data-n=\"7671\">650</sup> זהו ג\"כ בבחי' גבורות שכולל או\"ח ואו\"י יחד כמו נר ה' נשמת אדם כאור הנר שעולה ויורד ברו\"ש כו'. וכך הוא בכל בע\"ח וגם בצמח האדמה עד צבא השמים העליונים שמשתחוים<sup data-n=\"7672\">651</sup> בסיבובם, והילוכם ג\"כ בבחי' רו\"ש [כמו גלגלים בסיבובם בעולה ויורד למטה מטה<sup data-n=\"7673\">*652</sup> וחוזר ועולה כאופנים בסיבובם ולכתם ורוח החי' באופנים<sup data-n=\"7674\">652</sup> כו' וכתיב והחיות רו\"ש] בכלל ובפרט דכמו שבפרט יש בחי' [רו\"ש בכל בריאה כך החיות אלקות רו\"ש בכללות בנבראים (וכל פעולה דומה לפועל ע\"כ ימצא בחי' רו\"ש] בכל פרט מכח הפועל האלקי לפי שהוא ג\"כ בבחי' רו\"ש).\n<b>והענין</b> הוא דבחי' המל' הוא כלול מחו\"ג בחי' או\"י ואו\"ח [ואו\"ח] קודם לאו\"י שזהו רצוא בבחי' גבורות דאש לעלות למעלה בלתי מתיישב בעולמות להחיותם בחיי'<sup data-n=\"7675\">653</sup> הלב שעולה ומסתלק וכאור הנר כו', וכנשימ[ה] כו' כנ\"ל, [ו]נק' עולת תמיד כו' וכמ\"ש למען יזמרך כבוד ולא ידום<sup data-n=\"7676\">654</sup> דנה\"ת קארי תדיר לנה\"ע ולא שכיך כו'. והוא מה שמבואר למעלה שזהו ירידה גדולה להיות ראש לשועלים ומלך על עם כו' ויש לה גנאי לכך<sup data-n=\"7677\">655</sup> עולה למעלה באצי' דוקא ולא להשפיל א\"ע כ\"כ, וזהו שמשה לא אמר בשכמל\"ו כלל כנ\"ל וכמו שאמר תאמר בי\"מ בהתפשטו' יש לה גנאי כו'<sup data-n=\"7678\">656</sup>, אך מצד הצער מהעדר העונג [ב]בירורי' דרפ\"ח כו' להפוך חושך לאור שיש בזה ריח להשיב נפש ביתרון אור מעונג העצמו' כנ\"ל תאמר להשפיל א\"ע להיות ראש לשועלים כנ\"ל. וזהו בחי' השוב שלמעלה במל' שמזה יהי' מקור וחיות הנבראי' שימצא[ו] במציאות מאין ליש (וזהו מבחי' רצוא דמלאכים בביטול היש לאין כנ\"ל) ומבחי' <span data-k=\"pg\">1222</span> ּ רצוא דמל' למעלה מצד הגנאי כנ\"ל מזה יהי' בחי' הרצוא במלאכים שבלתי מתיישבי' בכלי כלל וד\"ל.\n[יג]<b> ונמצא</b> מובן מזה דזהו הטעם בעיקר סיבת המשכת הנה\"ד הנ\"ל דנגיד ונפיק מעצמו' עונג האלק[י] ממש שהוא כמו בחי' זיו השכינה בג\"ע שהוא מ\"ש דע\"י יתיב כו', לפי שהחיות אלקי דשכינה בא בבחי' רו\"ש ובחי' הרצוא זהו שלא תאמר מצד הגנאי כנ\"ל לכך עולה למעלה בעצמותו והוא בחי' זיו השכינה שהוא העונג שבעצמו' דוקא כנ\"ל, אך להיותו בבחי' צער מהעדר ההתפשטו' בעונג להיות ראש למטה יומשך בקו השמאל שבעונג זה בבחי' שוב להשפיל א\"ע להריח צ\"ק כו'. והוא סיבת המשכה [כללי' לנבראי' שהוא מבחי' קו השמאל דגבור' שבעונג בצער הזה שאם לא תאמר כו' והוא ענין סיבת",[["7671","650","<b>נשמת רוח החיים באפו</b>: ע\"פ נח ז, כב."],["7672","651","<b>צבא השמים העליונים שמשתחוים</b>: נחמי' ט, ו."],["7673","*652","<b>מטה</b>: יז: ליתא."],["7674","652","<b>ורוח החי' באופנים</b>: יחזקאל א, כ. כא."],["7675","653","<b>בחיי'</b>: טזיז: כחיו'."],["7676","654","<b>למען יזמרך כבוד ולא ידום</b>: תהלים ל, יג."],["7677","655","<b>לכך</b>: טז: (שעונג. . העצמי [המובא לעיל בפנים על יד הערה 638] (ולכך."],["7678","656","<b>כו'</b>: שם: כו'). ראה הערה שלפנ\"ז."]]],[2300550758,"המשכה] דנה\"ד זה שנמשך מהעדר העונג כנ\"ל שהוא היפך דזיו השכינה בעונג העצמי, וא\"כ יובן דנה\"ד זה שבא מן בחי' הצער שלא תאמר, ה[ו]א מקור מציאת הנבראים כמלאכים ונשמות דבריאה כו', ואמנם קבלת שכר דנשמות ומלאכים ע\"י בחי' הביטול דרצוא שלהם בביטול המציאות מיש לאין כו' זהו בג\"ע שנהנין מזיו השכינה דהיינו מעונג העצמו' דשכינה ([כ]נהר שיוצא מעדן כו' וד\"ל<sup data-n=\"7679\">657</sup> ) (וזהו בא מבחי' או\"ח דרצוא שעולה למעלה מאו\"י דתענוג הנשמות בתחלה כנ\"ל (כמשי\"ת). ובזה יתורץ הקושיא הנ\"ל דאיך יוכל להיות נהר של אש כנה\"ד זה כו' שהרי עיקר סיבתו יוצא רק מבחי' שוב שבא בירידה והמשכה דוקא מעונג העצמות דע\"י שהוא העונג שברוממות שמתלבש בהיפוכו בגבו' דאש (כמו בצער ומרירות מהיפוך העונג שזהו ענין לא תאמר יש לה צער דבחי' צער זהו נה\"ד כו' וכמו שיש המשכ[ה] דחסדים שבתענוג בנהר שיוצא מעדן כנ\"ל וד\"ל.\n<b>וזהו</b> ג\"כ ענין הטבילה דנשמות בנה\"ד כזה קודם שעולים לגעה\"ע ליהנות מזיו השכינה כמו בעליות הנשמות מדי שבת וחדש כו' דודאי כמו שלפעמים אמרו דלפום צערא אגרא<sup data-n=\"7680\">658</sup> שלפ\"ע הצער כך יהי' ערך קבלת השכר כך לפ\"ע הצער בטבילה זו דנה\"ד כך יהי' ערך קבלת השכר בג\"ע, אך א\"כ למה צריך לצער הזה בנה\"ד לא יצטערו ולא יקבלו שכר כ\"כ. אלא מוכרח לומר דנהפוך הוא שלפ\"ע השכר בעונג הנפלא צריך להיות בהכרח הצער תחלה בטבילה זו וכמו נה\"ד התחתון שסמוך לגעה\"ת (כמשי\"ת) משום דהא בהא תליא דוקא דאם אין צער אין עונג וכמו שא' מוטב לידייני' וליתי<sup data-n=\"7681\">659</sup> כו', ולכאורה אין מובן למה לא יוכל להיות העונג בג\"ע מצד עצמות התענוג העליון האלקי דזיו השכינה אף בלא צער תחלה כלל כו'. אך הענין הוא כמ\"ש למעלה דיש ב' מיני עונג א' באו\"י מצד העצם שזהו שנברא ג\"ע בעונג מצומצם מעדן הנעלם כו' כמ\"ש ויברא ה'<sup data-n=\"7682\">660</sup> כו', ועונג הב' שבא מן ההיפוך דמרירות וצער דוקא (כיגיעה ועמל במיצוי הנפש והתרת הספיקות וכזורע בדמעה כו' שנתייאש וכמרירות בנה\"א מצד הריחוק כנ\"ל שאינו רק לפ\"ע העונג שמלובש בהיפוכו שמתגבר הרבה יותר מעונג העצמי כו', וזהו אגרא ושכר העונג בג\"ע וזי\"ו<sup data-n=\"7683\">661</sup> השכינ\"ה שניתוסף ביתרון אור רב לפ\"ע הצער דוקא שהוא מקו השמאל שבעונג שירד בבירורי' כו' להיות היפך חשך לאור כענין בע\"ת שגדולי' מצ\"ג כנ\"ל. ולזאת הוא ענין הטבילה <span data-k=\"pg\">תריא</span> ּ הזאת שזהו באש דגבורות שבעונג העליון שבקו השמאל שבו שהוא כמו בבחי' מרירות עצומה שנוגעת עד הנפש על הריחוק כו' (כמו שאדם מצטער מאד בנפשו מתי אבא ואראה<sup data-n=\"7684\">662</sup> פני אלקים וכעומד",[["7679","657","<b>כו' וד\"ל)</b>: טזיז: כנ\"ל) וד\"ל."],["7680","658","<b>דלפום צערא אגרא</b>: אבות ספ\"ה. ולפי גי' אדה\"ז בסידורו מכ\"א."],["7681","659","<b>מוטב לידייני' וליתי</b>: ראה חגיגה טו, ב."],["7682","660","<b>ויברא ה'</b>: בראשית ב, ח [ושם: ויטע — ראה לעיל פ' בשלח קנט, ד הערה 518]."],["7683","661","<b>וזי\"ו</b>: טזיז: בזיו."],["7684","662","<b>אבא ואראה</b>: שם: יבא ויראה."]]],[2300550761,"מאחורי הפרגוד בריחוק כו'), והוא מאש ש\"מ דנגיד ונפיק מקדמוהי ממש שירד בבחי' צער כנ\"ל שמזה יהי' היתרון אור בקבלת שכר מזיו השכינה בעלותם ו[כ]עכשיו בעומק לב נשבר בכובד ראש שלפני התפלה שעי\"ז יעלה בתפלה בעילוי יותר כידוע וד\"ל.\n<b>אך</b><sup data-n=\"7685\">663</sup> עדיין י\"ל דלפ\"ז טבילה זו בנה\"ד לעונש ולצער הנשמה האלקי' בהיפוך לעונג שתבא בבחי' ביטול וכליון כל עצמותה כמו בשפלות ומרירות עצומה כנ\"ל, ולכאורה הטבילה הזאת [כ]טובל במקוה לטהרה לבד שיוכל לעלות ולא לעונש ולצער כי נה\"ד זה הוא שעומד בין געה\"ת לגעה\"ע שאחר עלי' מגעה\"ת איך יהי' מקבל עונש (שזהו כמו בין ימוהמ\"ש לעוה\"ב שיעברו בנהר פרת<sup data-n=\"7686\">664</sup> שהוא הנהר שיוצא מעדן<sup data-n=\"7687\">665</sup> ) (כמ\"ש במ\"א). ועוד דהלא מבואר למעלה דנה\"ד זה דנגיד כו' הוא יורד ונמשך בבחי' שוב מעונג דעצמות שמזה יהי' מקור חיות הנבראים שיהי' להם מציאות מאין ליש היפוך הביטול (דטביל\"ה אותיות ביטו\"ל<sup data-n=\"7688\">666</sup> כידוע). והנה להבין שרש ענין טבילה זו (שהוא לעשות בנשמות בחי' שכחה גמורה וביטול כל המציאות מעונג והשגה אלקי' דגעה\"ת כו' (כמו ר\"ז שהתענה מ' יום<sup data-n=\"7689\">667</sup> לשכוח ת\"ב כשעולה לא\"י לקבל ת\"י וכה\"ג (וכמ\"ש במ\"א), הנה י\"ל תחלה במה שארז\"ל דמזיעתן של חיות הקדש נעשה נה\"ד כו', דזהו פלא גדול לכאו' כנ\"ל, וצ\"ל דלא קא' על נה\"ד זה דנגיד ונפיק מן קדמוהי ממש שהוא כמו נה\"ד שאצל געה\"ע אלא [מדבר] בנה\"ד התחתון שבין הגיהנם לגעה\"ת, והיינו שנשמות דגעה\"ת טובלים בנה\"ד זה קודם עלותם לגעה\"ת אחר שמתבררי' בגיהנם תחלה ונה\"ד זה הוא שנעשה מזיעתן של חיות כו' וד\"ל.\n<b>וביאור</b> הענין הנה ידוע דהגיהנם הוא אש דק ברוחני' שמכלה ומלבן לחומריות הרע שנעשה מתאוה רעה באש זרה וחום הקשה שהוא בחי' רע גמור, ואף כמדות הבהמי' כתאות זנות אפי' בהרהור רע שנק' הרהורי עבירה שבא מחמת חימום הגוף ביותר, ובכעס וקנאה שבא בפ\"מ להרע לרעהו כמלבין פני חבירו וכמדבר רק רע וכמו מלשינות וליצנות והוללות ופר\"ע כידוע, אך ע\"י התשובה בלב נשבר בבכי' מקירות הלב על ח\"נ בפ\"מ כקרי והרהורים רעים וכה\"ג בכל רע וטומאה ינקה ויטהר וע\"י יסורים בגיהנם להוציא האש הזרה הנ\"ל (כמו ע\"י יסורים קשים ומרים בצרות וביטושי' גדולים בעוה\"ז) וזהו לבער גבורות קשות דרע גמור. אך יש עוד מדריג' בתשו' במרירות הנפש ברוחניות ודקות יותר והוא על הריחוק שנתרחק לבו והי' כאבן ולא יקבל במוחו ולבו גילוי אור אלקי כלל וכמת יחשב בעצמו",[["7685","663","<b>אך</b>: יב נרשם: ח [ז: נרשם לעיל על יד הערה 626. יא: נרשם להלן על יד הערה 853 (הפרקים ט-י לא נסמנו)]."],["7686","664","<b>שיעברו בנהר פרת</b>: בענין העברה בנהר פרת ראה ישעי' יא, טו ובמפרשים. לעיל פ' שמות מ, ד הערה 165. לקמן תי, ד."],["7687","665","<b>בנהר פרת. . שיוצא מעדן</b>: ראה בכורות נה, ב."],["7688","666","<b>דטביל\"ה אותיות ביטו\"ל</b>: ראה לקמן תי, ד. סידור כוונת המקוה קנט, סע\"ד (ואותיות ביטול כאותיות טבילה אלא שנתחלף הוי\"ו בה\"א בלבד). מאמרי אדה\"א במדבר ח\"ב ע' שסב. מכתב י\"ג כסלו תשי\"ד נדפס באגרות קודש ח\"ח ע' נה בשם חכמי האמת."],["7689","667","<b>ר\"ז שהתענה מ' יום</b>: ב\"מ פה, א. ראה מאמרי אדה\"א ויקרא ח\"א ע' מז. וש\"נ. ח\"ב ע' תתכב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670059\" data-slug=\"torat-chaim\" data-id=\"2300670059\">תו\"ח בראשית לד, ב</a> ובהערה 8. ח\"ש קמ, ג ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301550095\" data-slug=\"likkutei-sichot\" data-id=\"1301550095\">לקו\"ש ואתחנן כרך לד ע' 24</a> ואילך. וראה גם לעיל פ' תצוה שכ, ג. שמות ו, ד. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקיד ואילך."]]],[2300550763,"בטמטום הלב והמוח<sup data-n=\"7690\">668</sup> כו', וגם מצד גסות וחומריות גופו אע\"פ שלא נמשך אחר הרע אף בהרהור עבירות אבל בתאוות היתר מושקע ומושרש ביותר ובתאות הממון והכבוד בכל <span data-k=\"pg\">1224</span> ּ לבו רודף אחרי ההבל ויבלע כל חיותו בזה וכל הדו\"מ בטלים וריקים ומחשבות של הבל הולכים אחר הנפש<sup data-n=\"7691\">669</sup> בצאתה מגופה. וזהו ענין הטבילה בנה\"ד<sup data-n=\"7692\">670</sup> שאחר בירור גיהנם מן התאוות הרעות ממש והוא אש רוחני ודק יותר שמוציא ומכלה כל הגשמה גופני' וחומריות שקיבלה הנשמה בעוה\"ז (וזהו כמו תשובה בלב נשבר במ\"ש טבעי' על רדפו בהבל כל ימיו כו' ומצטער ויתמרמר בנפשו עד שנבזה בעיניו נמאס כו', זהו אש דנה\"ד זה שהוא כאש המרירות ובכי' בהתפעלות אש שנק' אש שחורה<sup data-n=\"7693\">671</sup> בלקותא שבדמי' ברוע הלב ופני[ם] כו'), והוא כמו מ\"ת בוכי'<sup data-n=\"7694\">672</sup> כו' כמשי\"ת. וזהו שא' דכל עיקר טבילה זו דנשמות בנה\"ד זה רק לשכוח כל חיז\"ו דהאי עלמא<sup data-n=\"7695\">673</sup> כו' שהוא הגסות וחומרי' דמדות הטבעי' ומודו\"מ שע[ו]סק בכל ימיו בטרדא בלו\"נ<sup data-n=\"7696\">674</sup> כו', ואז יוכלו הנשמות לעלות לגעה\"ת לקבל שכר בהנא' עונג אלקי במורגש בשכל ומדות אוי\"ר אלקי' כו' (כמו בב\"ר<sup data-n=\"7697\">675</sup> קודם התפלה וכבכי' מסט' דא וחדוה מסט' דא<sup data-n=\"7698\">676</sup> כו' שע\"י המרירות ובכי' על ריחוקו מאלקות יבא לפ\"ע זה לקירוב וחדוה אלקי' בהתפעלו' אה\"ר בתענוגי' כעכשיו בק\"ש ופסוד\"ז וכה\"ג כידוע), ולפ\"ע הצער ומרירות מן ההיפוך כך יהי' ערך העונג אלקי במורגש לנשמות בגעה\"ת (שזהו לפ\"ע הפשט' הגסות והגשמיות לאי\"ן בבחי' כלי ריקן יותר (כרקבון הגרעין כו' וכזורעים בדמעה כו' ומתייאש כנ\"ל). וזהו שא' דמזיעתן של חיות הקדש נמשך נה\"ד זה שקודם לגעה\"ת (כלהט החרב כו' שיש בו טו\"ר ולפעמים מתהפך לטוב<sup data-n=\"7699\">677</sup> כו' והוא נוגה דיצי' שחציו טוב<sup data-n=\"7700\">678</sup> כו' והיינו בתאוות היתר שמתברר בנה\"ד זה כנ\"ל).\n<b>והענין</b> הוא דודאי נה\"ד זה יותר טוב מן הגיהנם<sup data-n=\"7701\">679</sup> שהגיהנם נק' עונש ודין גמור לייסר לרשעים לבער הרע ממש שהוא אש קשה דאכיל ושצי ומבער כל לכלוך ופסולת (כמו שאש אוכלת אש המכוה<sup data-n=\"7702\">680</sup> כו') (וכמשל עלוקה שמושכת דם<sup data-n=\"7703\">681</sup> הפסולת כך יש דינין קשי' שכל חיותם לכלות הרע ונק' רצועא לאלקאה<sup data-n=\"7704\">682</sup> כאיש רע בטבעו שכל חיותו לפעול רע לענוש<sup data-n=\"7705\">683</sup> ולהכות כל חי וכמו ועל חרבך תחי'<sup data-n=\"7706\">684</sup> כו') וכמו יסורים קשים",[["7690","668","<b>בטמטום הלב והמוח</b>: ראה גם לעיל ב, ב. וש\"נ."],["7691","669","<b>הדו\"מ. . ומחשבות. . אחר הנפש</b>: ראה גם שע\"ת ו, ב ובהערה 21."],["7692","670","<b>הדו\"מ. . ומחשבות. . הטבילה בנה\"ד</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תרעה. וש\"נ. ש\"א ז, א ובהנסמן שם. לקמן תכח, ב."],["7693","671","<b>אש שחורה</b>: פסיקתא דרב כהנא פסקא א (ויהי ביום כלות משה) וש\"נ. תנחומא שמיני ח."],["7694","672","<b>מ\"ת בוכי'</b>: ראה ת\"ז ת\"ה (יט, ב). מאמרי אדה\"א בראשית ע' קג. וש\"נ. שמות ח\"א ר\"ע לו."],["7695","673","<b>לשכוח כל חיז\"ו דהאי עלמא</b>: ראה זהר ויקהל ריא, ב."],["7696","674","<b>בלו\"נ</b>: בלב ונפש."],["7697","675","<b>בב\"ר</b>: יז: כב\"ר. טז: כובד ראש — נסמן לעיל הערה 609."],["7698","676","<b>וכבכי' מסט' דא וחדוה מסט' דא</b>: נסמן לעיל פ' תצוה שכב, ד הערה 175."],["7699","677","<b>כלהט החרב. . מתהפך לטוב</b>: ראה בראשית ג, כד. לעיל פ' בשלח רט, א ובהערה 20. וראה גם לעיל פ' שמות ה, ד ואילך."],["7700","678","<b>נוגה דיצי' שחציו טוב</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו."],["7701","679","<b>נה\"ד. . הגיהנם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680426\" data-slug=\"torat-chaim\" data-id=\"2300680426\">תו\"ח וישלח קצז, ב</a>."],["7702","680","<b>שאש אוכלת אש המכוה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680423\" data-slug=\"torat-chaim\" data-id=\"2300680423\">תו\"ח וישלח קצז, א</a>."],["7703","681","<b>עלוקה שמושכת דם</b>: ראה גם לעיל פ' בא קכה, ב. וש\"נ."],["7704","682","<b>רצועא לאלקאה</b>: ראה זהר בהקדמה יא, ב."],["7705","683","<b>לענוש</b>: יז: לענות."],["7706","684","<b>ועל חרבך תחי'</b>: תולדות כז, מ."]]],[2300550765,"שבאי' לייסר האדם [בפו\"מ] שנלקה בגופו ובממונו כו'. אבל יש עוד יסורים שהן רק לתיקון נפשו, שיוכל לעלות למעלה כמו להיות מקבל קרבת אלקי' בתו\"מ ותפלה שצריך להפשיט גשמיות וחומריות שלו כו' שלא יהי' גס בלבו ורוחו מתאוות היתר, עושי' אותו כלי ריקן בלב נשבר ושפלות ג\"כ ע\"י יסורים שזהו נק' יסורים של אהבה<sup data-n=\"7707\">685</sup> שאשר יאהב ה' ויחפוץ בו יוכיחנו<sup data-n=\"7708\">686</sup> ביסורים למרק אותו. וזה רק לנקות אותו להיות בר לבב<sup data-n=\"7709\">687</sup> בלי שום לכלוך או קלקול כו', וזהו לא לעונש רק כדי שיוכשר לעלות בעילוי כו' כמ\"ש מי יעלה<sup data-n=\"7710\">688</sup> כו'. וזהו ענין נה\"ד זה שהן מים רותחים [כ]אש (כחמי טברי' שמרפאים<sup data-n=\"7711\">689</sup> ומסירי' ומנקים כל קלקול כו') שטובלים בו הנשמות שאין זו שריפה ממש אלא שמתלבשים<sup data-n=\"7712\">690</sup> בנהר זה יותר מליבון וריחוץ במים טהורים (והוא מפני שהמים דנהר זה נק' מים שבאש שמוציאים ומנקים כל לכלוך כמו באש שותה כו').\n<span data-k=\"pg\">תריב</span> ּ<b> וזהו</b> שנה\"ד זה יוצא מזיעתן של חיות דוקא, דהנה ידוע שהזיעה הוא חלק המים שבחום הדם שזהו שיוצא בבחי' פסולת<sup data-n=\"7713\">691</sup> מן החיות שבדם [כ]זיעה דחולה שמתרפא בזה, לפי שיוצא כל הקלקול שבדמים בזיעה זו שנדחק בנקבי העור הנק' נקבי זיעה והן באים מן החום הקשה ביותר, והרי הזיעה נמשך כמים ממש עד שיוכל להיות נופל<sup data-n=\"7714\">692</sup> מים ממש והן מרותחים כאש לפי שבאים מן האש ממש ונק' מים שבאש (וזהו שמנקי' כל רע וקלקול בפנימי' יותר מהקזת דם בחיצוני' ומעלוקו' המושכות הפסולת החיצוניות שבדמים. וכך הוא ברוחניות דנה\"ד שמנקי' כל קלקול שבתאות היתר שנמשך כמים שאינו בקרירות כמים ממש שא\"כ אין זו תאוה כלל, אלא זהו המשכת ודביקות הנפש שנתמשך אחר כל תאות שיש בזה חום דוקא אלא שחום זה אינו בוער כאש בכליון הנפש אלא אדרבה נמשך כמים ונק' מים שבאש, שזהו [כ]זיעה שיוצא כמים מחום האש כמו בכל המשכת תאוה בחום שנמשך כמים בזיעה כחום תאות המשגל והמאכל [והשחוק] והחשק בהתלהבות או במלאכה וטרחא שמחמם הדם כו' (וזהו ההפרש בין אש הגיהנם שבוער כאש ממש לכלות שמבער החום עצמו שבוער כאש ממש<sup data-n=\"7715\">693</sup> כמו בעוברי עבירות ([ו]כמ\"ש אם יהיו חטאיכם כשנים<sup data-n=\"7716\">694</sup> כו' שהוא עצם האדמומית בחום שבדם כו' וכתי' כל דבר אשר באש<sup data-n=\"7717\">695</sup>",[["7707","685","<b>יסורים של אהבה</b>: ברכות ה, א. ראה גם לעיל פ' תצוה שנב, ב. וש\"נ."],["7708","686","<b>שאשר יאהב ה'. . יוכיחנו</b>: ע\"פ משלי ג, יב."],["7709","687","<b>בר לבב</b>: תהלים כד, ד. ראה גם לעיל פ' וארא עז, ד ובהערה *375."],["7710","688","<b>מי יעלה</b>: תהלים כד, ג."],["7711","689","<b>כחמי טברי' שמרפאים</b>: ראה גם לעיל פ' בשלח רטו, א. וש\"נ."],["7712","690","<b>שמתלבשים</b>: טזיז: שמתלבן."],["7713","691","<b>שהזיעה. . בבחי' פסולת</b>: ראה גם בענין הזיעה בפיסקא הבאה. וש\"נ. ביאוה\"ז קדושים קמ, ב. סידור שער חגה\"ש שט, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380353\" data-slug=\"likkutei-torah\" data-id=\"4001380353\">לקו\"ת במדבר יא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380476\" data-slug=\"likkutei-torah\" data-id=\"4001380476\">שלח מא, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381303\" data-slug=\"likkutei-torah\" data-id=\"4001381303\">שה\"ש מג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370146\" data-slug=\"torah-or\" data-id=\"3901370146\">תו\"א מקץ לא, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490266\" data-slug=\"or-hatorah-hb\" data-id=\"8316490266\">פיה\"מ פה, ג</a>. תו\"ח ח\"ש קכד, ד. מאמרי אדה\"א דברים ח\"ב ע' תקלז. נ\"ך ס\"ע קעו ואילך. וש\"נ. אוה\"ת תולדות כרך ד תתב, ב."],["7714","692","<b>נופל</b>: טזיז: ספל."],["7715","693","<b>לכלות. . ממש</b>: טז ליתא: וכנראה שנשמט מפני תיבות הדומות: ממש. . ממש."],["7716","694","<b>אם יהיו חטאיכם כשנים</b>: ישעי' א, יח."],["7717","695","<b>כל דבר אשר באש </b>[יבטזיז: שבאש]: מטות לא, כג [בדילוג]."]]],[2300550767,"תעבירו באש שזהו אש הגיהנם שמבער אש הבוער בכל חום תאו\"ר<sup data-n=\"7718\">696</sup> כמו בהגעלת כלי מתכות שתשמישן באש עצמו והגעלתו באש עצמו כו'. אך מים שבאש בתאוה הנמשך כמים (שנק' קלע\"פ<sup data-n=\"7719\">697</sup> בדביקות [ו]אהבה כו') מתלבנין בנה\"ד זה שהוא בחי' מים שבאש כמו מים<sup data-n=\"7720\">698</sup> רותחים כחמי טבריה וכה\"ג וד\"ל).\n<b>והנה</b> שרש ענין זיעתן של חיות הקדש בא מהתפעלות התלהבות האלקי שלהם כמ\"ש והחיות רצוא כו' שרץ לבם בתשוקה ברשפי אש התלהבות אלקי' ממש כמו להב היוצא מן החרסי'<sup data-n=\"7721\">699</sup> כו' כידוע בענין לפידי'<sup data-n=\"7722\">700</sup>, והיינו בקרבתם לאלקות ברוב התפעלות אהבה וקירוב בצאתם מכלי הגבלתם ליכלל באור אלקי המהווה אותם ממש. אך מיד שמגיעי' בקירוב ממש לפני ה' מתבטלים מכל מציאותם מגודל הפחד אלקי ונרתעים לאחוריהם שמחמת שנופל עליהם אימה ופחד וביטול מופלג יפלו ברתת וזיעה (כמו וינועו כו') שזהו בחי' השוב שלהם כנ\"ל. וכמו שרואים בחוש באדם שנופל בפחד ואימה גדולה ביותר עד שמתבטל מכל חושיו יפול בזיעה<sup data-n=\"7723\">701</sup> גדולה, כי הזיעה יוצא מן חום הדמים שנתבלבל<sup data-n=\"7724\">702</sup> ונתראו<sup data-n=\"7725\">703</sup> מצד הפחד ונדחק ויוצא כמים לחוץ והוא הזיעה שדוחק בנקבי העור כו' כזיעה בחום קשה דחולה או רתיחת דמים<sup data-n=\"7726\">704</sup> בחום התאוה כנ\"ל. וכך הוא באדם למטה שאחר קירוב והתלהבות ודביקות באהבה [ב]רשפי אש בתפלה מצד הקירוב עצמו שלא יכילנו במוח[ו] ולבו תפול עליו אימה ופחד אלקי וכמו שנרתע אחור ויפול מדביקות וקירוב באהבה, אדרבה ישאר בכלי גופו כדומם בלי ירגיש עצמו לשום דבר מה ויהי' בשפלות והכנעה יתירה (כמו מ\"ש הטבעי' למאוס בחיי הבלו ונפשו כעפר לכל כו'. וזהו כמו הזיעה שנופל באדם מפני הפחד, שהוא &lt;1226&gt; ּ היפך גמור לזיעה שנמשכת מן חום<sup data-n=\"7727\">705</sup> החימוד והתאות שנמשך לבו כמים כו', וכל פחד זה שנעשה בחי' שוב בשפלות והכנעה ומרירות זהו שמתקן ומוציא כל תאות שנמשך כמים, כידוע בנסיון שלא יועיל לביטול כל המשכות תאות היתר שבאה רק משרירות הלב ופר\"ע רק בשפלות והכנעת הלב מיראה ופחד אלקי' שהוא המרירות בבחי' שוב, כדמיון הזיעה דחיות הקדש שנשאר ויוצא מהתלהבות האלקי' מצד הביטול ופחד דוקא היפך הפר\"ע שגורם הוללו' והתמשכו' במים שבאש לכל תאוות כו' וד\"ל. וזהו שנה\"ד זה שיהי' תיקון לנשמות להפשיטם מגסות וחומריות דתאוות היתר ומ\"ז כנ\"ל שנמשכו אחר ההבל הוא שנעשה מזיעתן של חיות בחי' הפסולת דגבו' דקדושה בהתלהבות שלהם כשנסוגים אחור בבחי' שוב מצד פחד אלקי' זהו שנעשה זיעה כמים שבאש האלקי והוא נה\"ד זה שטובלי' בו הנשמות לעלות לגעה\"ת כנ\"ל",[["7718","696","<b>תאו\"ר</b>: טז: התאות רעות. יז: תאוה רעה."],["7719","697","<b>קלע\"פ</b>: ראה גם לעיל פ' וארא סח, א. וש\"נ."],["7720","698","<b>כמו מים</b>: יבטזיז: כמי."],["7721","699","<b>להב היוצא מן החרסי'</b>: ראה חגיגה יג, ב וברש\"י שם. מאמרי אדה\"א קונטרסים ס\"ע תלט ואילך."],["7722","700","<b>בענין לפידי'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלב. מאמרי אדה\"א במדבר ח\"ב ע' תתכו."],["7723","701","<b>בפחד. . בזיעה</b>: ראה גם מאמרי אדה\"ז כאן ע' שסד. תקע\"א ע' ט. תו\"א וישב ל, ד."],["7724","702","<b>שנתבלבל</b>: טז: שנתקלקל."],["7725","703","<b>ונתראו</b>: טז: ונתחמם. יז: ונרתע."],["7726","704","<b>דמים</b>: שם: המים."],["7727","705","<b>שנמשכת מן חום</b>: יז: שנחשבת לחום."]]],[2300550769,"וד\"ל. וכך הוא ג\"כ ענין הבכי' מן המרירות שבאה בדחיקת המוח ביותר עד שנ[ו]פל דמעות שנק' פסולת המוח<sup data-n=\"7728\">706</sup> והלב שניתקן עי\"ז כל חום שבתאוות היתר כמו המרירות בשפלות דפחד אלקי', וכענין מ\"ת בוכי' כו' שבוכים וצועקי' בקול מר מאד מאד על עוצם ריחוק[ם ואו'] אנן בעינן למהוי קדם מלכא כו' ומרירות דבכי' זו זהו [כ]זיעתן של חיות שנעשה מזה נה\"ד כנ\"ל וכמ\"ש בבכי יבואו<sup data-n=\"7729\">707</sup> כו' וד\"ל.\n[יד]<b> והנה</b> ע\"ד [כל] הנ\"ל בנה\"ד התחתון שעומד בין הגיהנם לגעה\"ת כנ\"ל, כך ממש יובן ברוחניות הרבה יותר בבחי' נה\"ד העליון שעומד בין געה\"ת לגעה\"ע כנ\"ל והוא כמ\"ש נה\"ד נגיד ונפיק כו', דהנה כמו שצריך להיות ביטול והעברה לשכוח חיזו ומראה דחומריות התאוה גופני' שהי' בהרגשה גשמי' (שזהו בחי' נוג\"ה דעשי' שמעורב טו\"ר אע\"פ שאינו רע גמור אלא טוב דנוגה שיכול לעלות [כ]קרבן בהמה בהקטר חו\"ד<sup data-n=\"7730\">708</sup> לריח ניחוח להוי' וכן או\"ש<sup data-n=\"7731\">709</sup> גשמי' [ש]מברך להוי' בבהמ\"ז ותאות המשגל שנולד נשמ' אלקי' וכה\"ג ביגיע כפיו בתאות השגת הון שעושה צדקה וכה\"ג) וכך מו\"ד שלא לה' המה יצורפו ויעלו מהן בחי' הטוב כו'). כך הוא גם לאחר שעלו הנשמות לגעה\"ת [ו]צריכים לעלות בעלי' גבוה מזו לגעה\"ע שאין ערך כלל ביניהן והוא ע\"י הטבילה שטובלים נשמות דגעה\"ת בנה\"ד העליון דנגיד ונפיק מקדמוהי ממש כו' שישכחו לגמרי על כל מה שקיבלו בגעה\"ת כו' (כמו שצריך לעלות ולבא השר לפני המלך שמתבטל ביטול פנימי הרבה יותר מביטול עבד לפני השר וכה\"ג). והענין הוא דודאי גם שכבר הופשט' הנשמה מכל גסות וחומריות בתכלית בנה\"ד התחתון קודם עלותה בגעה\"ת ומל'<sup data-n=\"7732\">710</sup> לא הי' ביכולתה לקבל אור אלקי כלל [ב]געה\"ת שמופשט שם מכל גשם וחומר רע בתכלית (כג\"ע הארץ שגם הצומח דשם מופשט מכל גסות וחומריות דד\"י דעוה\"ז כמו כל עץ נחמד<sup data-n=\"7733\">711</sup> כו' ואפי' קרקע הגן<sup data-n=\"7734\">712</sup> כידוע).\n<b>אך</b> הנה לפ\"ע זה יובן גם בעונג ואוי\"ר שכל והשגה האלקי' שבגעה\"ת שנמשך בנשמות זהו כמו התפעלות אהוי\"ר שכליי' להתענג על ה' בעונג מורגש במוח ולב בתפלה עכשיו, <span data-k=\"pg\">תריג</span> ּ שיש מי שמתפעל בהרגשת עצמו בזה לפי שהשגה זו באה בבחי' יש ודבר מה וההתפעלות הוא שניזוז מישות וגסות שהי' נפרד ונתבטל מיש לאין האלקי שאינו ביטול עצמי כו' ע\"כ מרגיש בנפשו ביטול, והתפעלות זו בבחי' יש ודבר מה עד שיטיב לבבו ויגביה לבו ורוחו בבחי' יש גדול ולגרמי' לבד שחפץ בהתגלות לבו למראה ולא מצד אלקות כלל, כמו הרגשה",[["7728","706","<b>דמעות שנק' פסולת המוח</b>: ראה גם תו\"ח ויצא קסט, ג. ובהערה 29. ש\"א פט, ב."],["7729","707","<b>בבכי יבואו</b>: ירמי' לא, ח."],["7730","708","<b>חו\"ד</b>: חלב ודם."],["7731","709","<b>או\"ש</b>: אכילה ושתי'."],["7732","710","<b>ומל'</b>: טזיז: וא\"ל ואם לאו."],["7733","711","<b>כג\"ע. . הארץ. . כל עץ נחמד</b>: בראשית ב, ט."],["7734","712","<b>כג\"ע הארץ. . דד\"י דעוה\"ז. . קרקע הגן</b>: ראה גם מאמרי אדה\"א תקע\"ז ע' עו. וש\"נ. לעיל פ' שמות ה, ד. לקמן תכח, ב."]]],[2300550771,"גשמית דתאוות היתר בגופו שמבלבל ומסתיר אור [ה]אלקי בנשמות בשכל ואוי\"ר כנ\"ל עד שצריך לעשות העברה וביטול הגסות לגמרי בלב נשבר ומרירות ובכי' [ב]שפלות והכנעת הלב ביותר כנ\"ל, כך לפ\"ע צריך לעשות ביטול וכלי ריקן להיות הפשטת הרגשה דישות וגסות ברוחני' בהתפעלות הנשמה בהשגה אלקי' שמתערב בזה פסולת דק יותר (שזהו בחי' נוג\"ה<sup data-n=\"7735\">713</sup> דבריאה שמיעוטו רע<sup data-n=\"7736\">714</sup> כו')<sup data-n=\"7737\">715</sup> שהוא הרגשת עצמו בבחי' יש ולגרמי' כנ\"ל<sup data-n=\"7738\">716</sup> כאילו [אינו] במציאות דבר מה כלל וכלל, ולשכוח על כל מה שמשיג ומתפעל בהשגת אלקות בגעה\"ת כי אין ערך כלל, לגבי זיו השכינה שבגעה\"ע ששם לא יוכל לבא כל בחי' יש ודבר מה במורגש כלל<sup data-n=\"7739\">717</sup> רק מי שהוא בבחי' אין ומ\"ה בעצם שבלתי מרגיש א\"ע כלל שנק' ביטול עצמי' ולא ביטול היש לאין ע\"י התפעלות בהשג[ת] דבר מה כענין מה פשפשת כו'. והיינו לפי שבגעה\"ע מאיר מבחי' עונג העצמי דמל' דאצי' שבחכמה בבחי' ראי' מקרוב שהוא כעומד לפני המלך שמתבטל ממציאותו לגמרי כמ\"ש להשתחוות לפני ה'<sup data-n=\"7740\">718</sup> כו' וכידוע, ולכך צריך להיות טבילה בנה\"ד העליון הזה שעושה בחי' ביטול ושכחה בנשמות שלא יהי' בהן בחי' הרגשה בעצמם בישות וגסות אף בעבודה והשגה אלקי' כלל כמו ויגבה לבו בדרכי ה'<sup data-n=\"7741\">719</sup> כו' ואף מה ש[מ]בטל מי\"ש לאי\"ן שלא ירגיש הביטול כו' כמו ופלגשו ושמה ראומ\"ה<sup data-n=\"7742\">720</sup> רא\"ו שאני מ\"ה כו') כדי שיוכל לבוא לבחי' אי\"ן ומ\"ה האמיתי כמשה שא' ונחנו מ\"ה<sup data-n=\"7743\">721</sup> כו' שהוא בחי' כלי לקבל עונג העצמי דאלקות שבלתי מורגש כלל שנק' עונג הנעלם שבעצמות א\"ס ב\"ה וד\"ל.\n<b>והנה</b> זהו ענין נה\"ד העליון הנ\"ל שזהו בחי' גבו' שבעונג העליון העצמי' דזיו השכינה כנ\"ל שיורד ונשפל ונמשך בהיפוכו בצער שמנגד לעונג העצמי' שהוא קו השני השמאל שבו במשקל שוה כו'<sup data-n=\"7744\">722</sup> כנ\"ל באורך. והיינו כמו ענין הצער ומרירות אלקי ממש דבחי' תש\"ע שהיא רוחני' ודקה הרבה יותר מצער ומרירות דתש\"ת בלב נשבר ובכי' ושפלות כזיעתן של חיות מצד [ה]פחד כו', כידוע דבתענוג האלקי' עצמו שלמעלה מן השכל וטעם כמו בשיר פשוט וניגון כמו בדברי אה\"ר בתענוגי' בין או\"נ<sup data-n=\"7745\">723</sup> בנפשותם) יש בחי' עוצב ומרירות כמו בקול ותנועה המורה שפלות ועוצב. והוא רק מצד עוצם הרצון והחפץ בעונג עצמי להתקרב לה' ולא יכול לאדבקא בי'<sup data-n=\"7746\">724</sup>, כמו",[["7735","713","<b>נוג\"ה</b>: יז: ק\"נ."],["7736","714","<b>נוג\"ה דבריאה שמיעוטו רע</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו. מאמרי אדה\"א בראשית ע' צז. וש\"נ."],["7737","715","<b>(שזהו. . כו')</b>: ניתוסף ע\"פ טז. וביביז נרשם זה בסמוך. ראה הערה הבאה."],["7738","716","<b>כנ\"ל</b>: יב: ניתוסף: החצע\"ג (שזהו. . כו') שנמצא לעיל בשו\"ה בהשגה. יז: ליתא. ובמקומו בא כאן החצע\"ג."],["7739","717","<b>ולשכוח. . כלל</b>: טז: ליתא. וכנראה נשמט מפני תיבות הדומות: וכלל. . כלל."],["7740","718","<b>להשתחוות לפני ה'</b>: ישעי' סו, כג."],["7741","719","<b>ויגבה לבו בדרכי ה'</b>: דהי\"ב יז, ו."],["7742","720","<b>ופלגשו ושמה ראומ\"ה</b>: וירא כב, כד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. שעה\"י קמא, א ובהערה 16."],["7743","721","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["7744","722","<b>כו'</b>: טזיז: ליתא."],["7745","723","<b>או\"נ</b>: אוהבים נאמנים."],["7746","724","<b>בי'</b>: טזיז: כו'."]]],[2300550773,"מה תשתוחחי כו' מתי אבא ואראה כו' וכמו נפשי אויתיך בלילה אף רוחי<sup data-n=\"7747\">725</sup> כו' וכן לבי ובשרי ירננו<sup data-n=\"7748\">726</sup> כו' כי צמאה נפשי בארץ ציה<sup data-n=\"7749\">727</sup> כו', שאין זה כמו מרירות ובכי' על הריחוק באמת [כ]טמטום הלב בתאוות היתר וכה\"ג שהוא ריחוק באמת, אלא רק מצד העדר הקירוב כבן שמצפה <span data-k=\"pg\">1228</span> ּ לראות אביו ואין מניחי' אותו שלבו דואג בקרבו שנגע בו עד הנפש וכה\"ג (ולא כמ\"ת בוכי' שזהו מצד הריחוק באמת כבע\"ת כו'), וזהו ענין תש\"ע כתשו' בע\"ת<sup data-n=\"7750\">728</sup> ממעמקים כו' לפי שקרוב והיינו כדי לעלות לפני ה' כו'<sup data-n=\"7751\">729</sup>. וזהו [ענין נה\"ד העליון] שנמשך לנשמות בגעה\"ת מאש ש\"מ דנגיד ונפיק מקדמוהי בקו השמאל בבחי' המנגד כמו עונג העצמי' שיבאו<sup data-n=\"7752\">730</sup> נשמות צדיקים ביסורים של אהבה (במיצוי הנפש בפרנסה ודוחק וכעמל תו\"מ בעול ויגיעה להפוך חושך לאור דוקא (כמשי\"ת) ענין נה\"ד העליון<sup data-n=\"7753\">731</sup>, [ש]בנה\"ד זה טובלים הנשמות דבריאה לעלות לגעה\"ע להיות בהפשטת עונג המורגש. והוא להיות בבחי' ביטול עצמי' דחכ' שטבילה אותיות ביטול שזהו בה\"א דבינה בשלהבת י\"ה כמ\"ש רשפיה רשפי אש כו' מצד המנגד לעונג העצמי' כחולת אהבה בגלות שבאה לחום ואש בוערת כו', וזהו נמשך משלהבת<sup data-n=\"7754\">732</sup> י\"ה דאש של מעלה דנגיד ונפיק אש יו\"ד נהורא חיורא<sup data-n=\"7755\">733</sup> שנק' אש ה[וי']<sup data-n=\"7756\">734</sup> כו' כמו אש שמדליק הנרות כו' וכמו קול ה' חוצב להבות אש<sup data-n=\"7757\">735</sup> כו' (וזהו בראשי\"ת ברי\"ת א\"ש<sup data-n=\"7758\">736</sup> דתורה שהוא אה\"ר כרשפי אש דמשפיע שמושך למקבל כמו אהרן כה\"ג שמעלה לנרות דנש\"י לעשות בחי' כלי קיבול לקבל כאש דקולות דמ\"ת, וכך עכשיו ד\"ת כאש לנשמות כב\"ע שהי' שונה ואש מלהטת סביב[י]ו<sup data-n=\"7759\">737</sup> כו' וכה\"ג וד\"ל (והיינו שבדוגמא זו יהי' לע\"ל אחר ימוהמ\"ש שיהי' תשלום הבירורי' דרפ\"ח כו' ויהי' קיבוץ גליות שזהו בגעה\"ת דעכשיו יעבור בנהר פרת לבא לא\"י שהוא ארץ החיים דעוה\"ב ששם בחי' עדן<sup data-n=\"7760\">*738</sup> געה\"ע<sup data-n=\"7761\">738</sup> עצמו כו').\n<b>ואחר</b> כל הנ\"ל יובן בתוס' ביאור מה שהקדים<sup data-n=\"7762\">739</sup> דוד עולה של תו\"מ כנ\"ל, דהנה מבואר למעלה בענין בחי' רו\"ש למעלה במל' שהוא מה שאם תאמר יש לה גנאי כו' יהי' בחי' רצוא למעלה כו' ואם לא תאמר יש לה צער שמזה יהי' בחי' שוב להשפיל א\"ע בעונג המלובש בהיפוכו כו' כנ\"ל. וכמ\"כ יש בנשמה פרטי ב' מדרגות בעונג, א' עונג [ה]עצמי הנבדל בערך מלבא למטה בהתפשטות אף בשכל ומדות כו' והיינו בחי' עונג",[["7747","725","<b>נפשי אויתיך בלילה אף רוחי</b>: ישעי' כו, ט."],["7748","726","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["7749","727","<b>צמאה נפשי בארץ ציה</b>: תהלים סג, ב [בדילוגים (וראה לעיל על יד הערה 59)]."],["7750","728","<b>בע\"ת</b>: יז: בעי\"ת. וראה הערה הבאה."],["7751","729","<b>כו'</b>: שם: ביו\"כ כו'. וראה הערה שלפנ\"ז."],["7752","730","<b>כמו. . שיבאו</b>: טז: כמו. יז: לעונג כמו שיבואו."],["7753","731","<b>ענין נה\"ד העליון</b>: שם ליתא. וראה לעיל בפנים שו\"ה ה'."],["7754","732","<b>משלהבת</b>: יז: מאש דשלהבת."],["7755","733","<b>נהורא חיורא</b>: ראה זהר בראשית נא, רע\"א."],["7756","734","<b>אש ה[וי']</b>: ראה גם לעיל פ' תצוה שמט, ג ואילך."],["7757","735","<b>קול ה' חוצב להבות אש</b>: תהלים כט, ז."],["7758","736","<b>בראשי\"ת ברי\"ת א\"ש</b>: ת\"ז רתכ\"ג."],["7759","737","<b>כב\"ע שהי' שונה ואש מלהטת סביב[י]ו</b>: ויק\"ר פט\"ז, ד. ראה גם לעיל פ' תצוה שמט, ד. לקמן תמ, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תטז."],["7760","*738","<b>ארץ החיים דעוה\"ב. . עדן</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["7761","738","<b>עדן געה\"ע</b>: טז: ג\"ע עצמו ומשם לעדן. יז: געה\"ע ומשם לעדן. ראה גם לעיל פ' בשלח רלט, ד וש\"נ."],["7762","739","<b>שהקדים</b>: טז: שהקים."]]],[2300550775,"העצמי' באלקו' ביחידה שבה שלמעלה מעונג המורכב בשכל והשג' והתפעלות אהבה כו' (כתפלה דשבת שמתענג על ה' כו' ונק' שי\"ר א\"ל<sup data-n=\"7763\">740</sup> כידוע). והב' עונג המלובש בהיפוכו בקו השמאל כמו במרירות וצער על הריחוק בין מצד הגוף ובין מצד הנשמה עצמה שנק' חולת אהבה וכה\"ג. והוא הגורם בחי' שפלות ונמיכת רוח בתכלית עד שנבזה בעיניו נמאס ומואס בחייו תמיד כו' ואינו מהות בריא' בפ\"ע ונפשו כעפר לכל כו', ומסיבת זה יבא לשפלות וענוה לומר נואש כו'<sup data-n=\"7764\">741</sup> הוא שיכול לגשת אל הקדש העליון בעבודה שבלב בהתלהבות ודביקות והשגות אלקות, ויאמר לנפשו השפלה באמת לאמיתו שאין דרך לפניו כ\"א לעסוק בתו\"מ בפו\"מ בלבד דהיינו להיות סומ\"ר וע\"ט בפו\"מ רק מצד עומ\"ש בכתף ישא כשור לעול בלבד כל היום, ולזה יהי' כל מגמתו וכל ישעו וכל חפצו וישמח בשמחה מתוך <span data-k=\"pg\">תריד</span> ּ ענוה ושפלות רק בשמחה של תו\"מ מצד המעשה. ואעפ\"י שאינו עושה רק בעול וכפי' ואין לו נח\"ר כלל בעבודתו שמח' באלקות<sup data-n=\"7765\">742</sup> מצד השפלות העצומה כעני שישמח במעט לחמו שתחי' נפשו לפי שבנפשו יביא לחמו<sup data-n=\"7766\">743</sup> בעול קשה ועבודה ויגיעה רבה עד מיצוי הנפש ממש, וכן בעמל תורה עד שממית עצמו עלי' כנ\"ל. וכל זה לא יבא בעובד באוי\"ר שכליי' בעונג מורגש בהתלהבות בתפלה שיוכל למלאות נפשו בזה עצמו במה שמרגיש חיות ויש ודבר לעצמו ויוכל להיות מזה עצמו בהוללות ופר\"ע אח\"ז בלי עסק תו\"מ כלל כנ\"ל, אך ע\"י בחי' שוב דוקא שבא מביטול בפחד אלקי' כזיעתן של חיות שנסוג אחור ויעמוד בריחוק מקום עד שיהי' בשפלות רוח ומרירות כנ\"ל מזה דוקא יהי' סיבת היגיעה ועבודה בעומ\"ש בכתף כנ\"ל וד\"ל.\n<b>וזהו</b> שהקים עולה דתו\"מ פי' הקים, כי צריכה קימה מצד שירד עומ\"ש ביגיעה ועבודה אלקי' שאין בה נח\"ר כלל ואדרבה זהו במרירות מצד שרחוק מעונג אלקי' כמו שהוא בקו השמאל שבו כנ\"ל וכמ\"ש למעלה בענין שמח נפש עבדך כו', ולזאת צריך להיות הקמה לעול זה שיהי' נהפך לעונג ושמחה אלקי' דוקא (וכמו בא יבוא ברינה<sup data-n=\"7767\">744</sup> כו' וכהתרת הספיקות כו' וכנ\"ל). אך במה הקים לעול זה הקשה מאחר שאינו מוצא שום נח\"ר לעצמו בעבודתו ביגיעה זו רק לצאת י\"ח מצד העול כו' ונפשו שפלה ומרוחקת מאור פני מלך ולבו דואג בקרבו מתי אבא כו' עד שמואס בחייו ממש כנ\"ל. הענין הוא דמתוך ענוה ושפלות זו דוקא יבא לכלל שמחה שישמח בחלקו בשפלות במה שעושה רצון קונו יהי' איך שיהי' והוא כמו מה<sup data-n=\"7768\">745</sup> שמוצא ריוח והצלחה אחר היגיעה דוקא במיצוי הנפש כנ\"ל, כך יהי' ערך העונג האלקי שיבא לנשמות הללו שעסקו בעול תו\"מ בגעה\"ע שמזה נעשה היפוך חושך העליון לאור כנ\"ל שבשביל זה ירד עונג העצמי' בהיפוכו כו' להיות מזה יתרון אור עונג הנעלם בג\"ע שבלתי מתיישב באו\"כ במורגש כלל, והוא כמו שכר",[["7763","740","<b>דשבת. . שי\"ר א\"ל</b>: ראה גם לעיל פ' תצוה שכב, ג. וש\"נ."],["7764","741","<b>כו'</b>: טזיז: מי."],["7765","742","<b>שמח' באלקות</b>: שם: ישמח בחלקו."],["7766","743","<b>שבנפשו יביא לחמו</b>: ע\"פ פיוט (לימים נוראים) כי כשמך."],["7767","744","<b>בא יבוא ברינה</b>: תהלים קכו, ו."],["7768","745","<b>מה</b>: יז: ליתא."]]],[2300550777,"הנשמות בגעה\"ע אחר שטבלו בנה\"ד שלפום צערא אגרא ולפ\"ע השכר יהי' הצער היפוכו כנ\"ל. וזהו הקים עולה דתו\"מ בפנימי' העונג העליון דמל' דאצי' שלמעלה מעונג העצמי מצד יתרון האור דעונג הבא מהיפוך חשך לאור כנ\"ל בענין עמל תורה (וכמ\"ש במ\"א בענין אדם לעמל יולד<sup data-n=\"7769\">746</sup> א\"י אם לעמל תורה כו' וד\"ל).\n<b>וזהו</b> סדר דברי הפ' הזאת בכלל מ\"ש ויקהל משה את כל עדת בנ\"י כו' ואח\"כ א' ויאמר משה כו' קחו מאתכם תרומה להוי' כו', ופי' תרומה ארמותא להוי' לרומם ולהגביה ולהעלות לשם הוי' וכמו ארוממך אלקי המלך כנ\"ל שזה פלא איך הי' ביכולת ב[ע]\"ג לרומם לבלתי בע\"ג כו', אך זהו שא' קחו מאתכם דוקא תרומה זו לרומם לשם הוי' שזהו בחי' זיו השכינה מקור כל עונג דג\"ע ועוה\"ב כנ\"ל להעלות אותו ביתרון אור עונג נעלה וגבוה הרבה יותר מעונג העצמי' שבתחלה, והוא אשר יבא דוקא מהיפוך חושך לאור ע\"י עול <span data-k=\"pg\">1230</span> ּ תו\"מ<sup data-n=\"7770\">747</sup> דוקא שזהו שהקים דוד דוקא למעלה גבוה דפנימי' עונג הנעלם<sup data-n=\"7771\">748</sup> כנ\"ל. וזהו שא' דוד שהוא הקים עולה דתו\"מ ארוממך אלקי המלך כו' דגם שהמלך סתם זהו עונג העצמי' במדת מל' כמו שהוא מלך מרומם לבדו כנ\"ל דנבדל בערך להיות מלך על עם נפרד מאין ליש כנ\"ל, מ\"מ ע\"י בחי' או\"ח דתענוג דמדת מל' שבהיפוך המנגד שיהפוך חשך לאור בעול תו\"מ הרי מגיע מזה יתרון אור רב בעונג העצמות<sup data-n=\"7772\">749</sup>, כנ\"ל במשל דבת מלך שהריחה צ\"ק תאמר יש לה גנאי לא תאמר יש לה צער כו' והביאו לה עבדי' בחשאי שז\"ש בשכמל\"ו בחשאי בעול וביטול חיצוני דמ\"ש [ב]צלותא בלחש בשפלות כו', ולע\"ל יתעלה עומ\"ש זה בבחי' פנימי' כתר עליון והוא שאמר ארוממך אלקי המלך למעלה משם הוי' דסוכ\"ע אע\"פ שאינו אלא מקיף בהתנשאות על העולמות, ואמנם ארומם לשם הוי' זה להיות עי\"ז תוס' אור גדול בפנימי' ההתנשאות שמצד עצמו בעונג הנעלם דשעשועי' העצמיי' בתוס' אור רב מטעם הנ\"ל דאו\"ח למעלה מאו\"י וד\"ל. וזהו שא' קחו מאתכם תרומה להוי' מאתכם דוקא בעולה דתו\"מ שיעלה וירומם לשם הוי' במל' דאצי' שנק' אלקי המלך למעלה יותר מטעם הנ\"ל. אך הנה איך יוכלו ליקח תרומה זו שהוא ארמותא להוי' מצד עול תו\"מ כנ\"ל מאחר שאינו מוצא שמחה ונח\"ר בעבודתו הפשוטה בעול לבד שמצד השפלות וענוה יתירה, והיינו מצד המרירות מעוצם הריחוק שלו מאחד לא<sup data-n=\"7773\">*750</sup> יוכל לנשאו' לבו ונפשו לגשת לקדש העליון לבא לידי העמקת הדעת והתבוננו' בהשגת יחו\"ע ויחו\"ת, כי מצד שפלותו יהי' גדולת ורוממות האלקות נפלאה ונשגבה ממנו מאד וכי [י]שפיל עצמו לומר לנפשו מי הוא שילך בגדולות ונפלאות מערכו השפל. ואע\"פ שכבר ידע והשיג במקצת בהשגות אלקות במוחו וערב לנפשו, מ\"מ מצד שפלותו העצומה לא יוכל ליקח הדברים לעבודתו בק\"ש אלא מרחוק ה'",[["7769","746","<b>אדם לעמל יולד</b>: איוב ה, ז. ראה סנהדרין צט, ב. מאמרי אדה\"א בראשית ע' קלה. וש\"נ. לעיל פ' שמות ד, ב. וש\"נ."],["7770","747","<b>עול תו\"מ</b>: טז: עמל תו'."],["7771","748","<b>עונג הנעלם</b>: יז: העונג העליון."],["7772","749","<b>העצמות</b>: טזיז: העצמי."],["7773","*750","<b>מאחד לא</b>: טז: מאחר שלא."]]],[2300550778,"נראה לו באמונה פשוטה לבד בלי דעת והשגה כלל כידוע, ולזאת איך יכול לרומם ולהעלות לשם הוי' ואלקי' דזהו יחו\"ע קוב\"ה ושכינתי' בא' הוי' אחד ולקבל מ\"ש בא' בשכמל\"ו בעול לבד אחר שאינו מעמיק דעתו והשגתו כלל ביחו\"ע ויחו\"ת דשמע ובשכמל\"ו<sup data-n=\"7774\">750</sup> כו', [ו]שמ\"ע ענין השגה והבנה<sup data-n=\"7775\">751</sup> כידוע.\n<b>אך</b> הנה לזה הקדים בפ' זאת קודם שציוה משה על תרומת הוי' הנ\"ל והוא מ\"ש ויקהל משה את כל עדת בנ\"י, פי' משה נק' רע\"מ<sup data-n=\"7776\">752</sup> וכמו ורעה אמונה<sup data-n=\"7777\">753</sup> שזן ומפרנס לאמונה הפשוטה דכנ\"י ע\"י בחי' הדעת, ששרש משה בבחי' הדעת [ה]עליון<sup data-n=\"7778\">754</sup> שהוא שרש ומקור למדות<sup data-n=\"7779\">755</sup> והוא מה שנמשך מד\"ע [ה]זה לד\"ת שהוא דעת המתפשט במדות להחיותם ונק' מפתחא דכליל שית<sup data-n=\"7780\">756</sup> כו'. כי יש ז' רועים<sup data-n=\"7781\">757</sup> [כ]אברהם רועה וזן לכנ\"י בהמשכת אה\"ר<sup data-n=\"7782\">758</sup> כו' ויצחק<sup data-n=\"7783\">759</sup> בפחד<sup data-n=\"7784\">760</sup> אלקי'<sup data-n=\"7785\">761</sup> כו' ומשה רועה ישראל בבחי' הדעת, והוא מה שממשיך דעת לנוק' שהן כנ\"י שיוכל כאו\"א לבוא לבחי' הדעת וההשגה והכרה בא[חד] במוח בינה להבין <span data-k=\"pg\">תרטו</span> ּ ולהשיג בשכל ליח[ו]\"ע דסובב וממלא בא' שמע ישראל כו', ומתפשט השגה זו במדות שהן נולדי' מן ההשגה דבינה שנק' בחי' אם הבנים<sup data-n=\"7786\">762</sup> בכלל והן ת\"ר אלף נשמות כללי'<sup data-n=\"7787\">763</sup> שהיו במ\"ת וכל א' קיבל ממשה בחי' הדעת שלו ובזה יש מזון וחיזוק לאמונה הפשוטה כמו ורעה אמונה כנ\"ל וד\"ל. וזהו ויקהל משה שהוא בחי' דעת העליון הכללי שהוא מקור<sup data-n=\"7788\">764</sup> לכל עד\"ת בנ\"י שנולדים ממדות<sup data-n=\"7789\">765</sup> דבינה עילאה כו', כי עד\"ת בהיפוך אותיות הוא דע\"ת<sup data-n=\"7790\">766</sup>, ומשה הקהיל לכל המוחי'<sup data-n=\"7791\">767</sup> דכל עדת בנ\"י, והוא לכל מוחי' שבמדות שהן באי' בהתחלקו' פרטי' מי' לי' עד ת\"ר אלף כו' לכך נק' בשם קהל ועדה דאין עדה פחותה מיו\"ד<sup data-n=\"7792\">768</sup> כו'. ומשה מ\"ה שמו שהוא החכ' והדע\"ת עליון שהוא מקור הראשון לכל הנולדי' מדעת שבמדות דבינה אם הבנים, הקהיל לכל עדת בנ\"י שהעלה והגביה אותם לבחי' ד\"ע דמשה שלמעלה מן המוחי' שבמדות בבחי' ד\"ת כו' ששם גם החכמה בבחי' אי\"ן והעלם למעלה מהיות אי\"ן ליש כו', שזהו ענין מצות השבת שא'<sup data-n=\"7793\">769</sup> בכללות שאמר אלה הדברים אשר כו' שהן ל\"ט מלאכות<sup data-n=\"7794\">770</sup> בבירורי' דרפ\"ח כו' בעולה דתו\"מ ו' ימים תעשה בכח עצמה (כמשי\"ת) וביום הז' שבת לה' בקדש דחכ' שנק' קדש",[["7774","750","<b>ביחו\"ע ויחו\"ת דשמע ובשכמל\"ו</b>: זהר בראשית יח, ב."],["7775","751","<b>[ו]שמ\"ע. . והבנה</b>: ראה זהר (אדרא רבא) נשא קלח, ב. מאמרי אדה\"א קונטרסים ע' תקצב. הנחות תקע\"ז ע' קמח ובהנסמן בהנ\"ל."],["7776","752","<b>משה נק' רע\"מ</b>: ראה זהר וירא קו, א. לעיל פ' וארא עז, ב. וש\"נ."],["7777","753","<b>ורעה אמונה</b>: תהלים לז, ג. ראה לעיל פ' תשא שפא, א ואילך ובהנסמן בריש המאמר שם."],["7778","754","<b>משה בבחי' הדעת [ה]עליון</b>: ראה זהר פקודי רכא, א. לעיל פ' בשלח קמז, ב. תד, ד."],["7779","755","<b>הדעת. . שרש ומקור למדות</b>: נסמן לעיל פ' יתרו ער, ד."],["7780","756","<b>דעת. . מפתחא דכליל שית</b>: נסמן לעיל פ' משפטים רצא, ד."],["7781","757","<b>ז' רועים</b>: ראה מיכה ה, ד. סוכה נב, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a> ובהנסמן במ\"מ לשם."],["7782","758","<b>ז' רועים [כ]אברהם. . אה\"ר</b>: ראה גם לעיל פ' תצוה שסד, א ובהערות 60. 61."],["7783","759","<b>ז' רועים. . ויצחק</b>: ראה תקונים לז\"ח קד, א. מאמרי אדה\"ז תקס\"ד ע' יג. תקע\"א ע' ל וע' מב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370155\" data-slug=\"torah-or\" data-id=\"3901370155\">תו\"א מקץ לג, ג</a> (ע\"פ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה כרך כ ע' 643</a>). לקו\"ת ואתחנן ט, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תצח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a>. (וראה גם לעיל פ' בשלח קנה, ד הערה 277)."],["7784","760","<b>ויצחק בפחד</b>: ראה ויצא לא, מב. רקאנטי שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח, מט, ד</a> ובהערה 45."],["7785","761","<b>בפחד אלקי'</b>: תהלים לו, ב. דהי\"ב כ, כט."],["7786","762","<b>דבינה. . אם הבנים</b>: נסמן לעיל פ' משפטים רצו, ב."],["7787","763","<b>ת\"ר אלף נשמות כללי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> פל\"ז. הנסמן לעיל פ' תרומה שיא, ד."],["7788","764","<b>שהוא מקור</b>: טז: ליתא."],["7789","765","<b>ממדות</b>: שם: ממוח."],["7790","766","<b>עד\"ת. . דע\"ת</b>: ראה גם מאמרי אדה\"ז תקס\"ב כאן ע' שסה. מאמרי אדה\"א שמות ח\"ב ע' תרנז. במדבר ח\"א ע' עד."],["7791","767","<b>לכל המוחי'</b>: טז: ליתא."],["7792","768","<b>דאין עדה פחותה מיו\"ד</b>: ראה מגילה כג, ב. שו\"ע אדה\"ז הל' ברכות השחר סנ\"ה, ס\"ב."],["7793","769","<b>שא'</b>: טזיז: ליתא."],["7794","770","<b>אלה הדברים. . ל\"ט מלאכות</b>: ראה מכילתא ויקהל (לה, ב). שבת צז, רע\"ב וברש\"י שם. וש\"נ. לקמן תיח, א. אוה\"ת ויקהל ע' ב'פה. וראה גם סה\"ש תשמ\"ט ח\"א ע' 318 בהערה."]]],[2300550779,"מלה בגרמי'<sup data-n=\"7795\">771</sup>. והיינו מה שא' אח\"כ ויאמר משה אל כל עדת כו' קחו מאתכם תרומה להוי' שאחר הבירורי' דרפ\"ח בעול תו\"מ בו' ימים ויעלה למעלה בשבת לבחי' אי\"ן דחכ' ע\"י ד\"ע דמשה כנ\"ל, יוכלו ליקח תרומה להוי' שהוא לרומם לש[ם] הוי' בפנימי' ועצמי' יותר מטעם הנ\"ל דאו\"ח עולה למעלה מאו\"י כשבא מן ההיפוך המנגד דוקא והוא מקבלת עמ\"ש נגד טבעו דוקא להפוך חושך לאור (וזהו קחו מאתכם בע[ול] מ\"ש תרומה להוי' למעלה מאו\"י דד\"ע דמשה, רק א\"א להיות כח בהעלא' דתרומה זו בלא דעת המתפשט במדות לקבל מ\"ש בדעת ורצון כ\"א ע\"י משה שהקהיל לכל עדת כו' וד\"ל).\n[טו]<b> אך</b> הנה עדיין י\"ל מאחר שעיקר ענין תרומה להו[י]' ארמותא כו' זהו בא ע\"י עומ\"ש דוקא שהוא רק באמונה פשוטה שלמעלה מן הדעת דוקא, וז\"ש קחו מאתכם כו', וא\"כ למה צריך להקדים לזה ענין ויקהל משה לעדת כו' שזהו להמשיך לבחי' הדעת והשגה דוקא באלקות שהוא היפוך האמונה בעומ\"ש, ואם לפי שא' ורע\"ה אמונ\"ה שמחזק לאמונה כנ\"ל איך יחזק לאמונה שלמעלה מן הדעת כו'. אך הנה יש להקדים הידוע שיש ב' מדרגות באמונה, א' בשם הוי' ואלקים בחי' סובב וממלא<sup data-n=\"7796\">772</sup> לבד כמו ויאמינו בהוי'<sup data-n=\"7797\">773</sup> והאמין בהוי'<sup data-n=\"7798\">774</sup> וכה\"ג שזהו בא ע\"י דעת והשגה דוקא כמ\"ש וידעת היום<sup data-n=\"7799\">775</sup> כו' כי ה' הוא האלקים וכן אתה הראת לדעת<sup data-n=\"7800\">776</sup> כו'. אבל מדרגה הב' באמונה זהו במהו\"ע ית' ממש שהוא אח\"פ בתכלית סדכ\"ס<sup data-n=\"7801\">777</sup> למת\"ב כלל<sup data-n=\"7802\">778</sup> בשום השגה והוא למעלה מסובב ומקיף הכללי, אלא כמו שהוא באמית[י]ת עצמותו שהי' הוא ושמו בלבד<sup data-n=\"7803\">779</sup> <span data-k=\"pg\">1232</span> ּ קודם צמצום הראשון שזהו פנימי' ועצמי' דאוא\"ס ממש. וע\"ז א' חדשים לבקרים רב\"ה אמונתי\"ך אמונה זו רבה באמצעות משה שנק' רע\"מ וכמ\"ש ורעה אמונה אחר שבטח בהוי' כו'. וזהו איהו אמת ואיהי אמונה<sup data-n=\"7804\">780</sup> להכיל ולקבל אמית[י]ת מהו\"ע בהכרה עצמי' שזהו בחי' ד\"ע דמשה שזן ומפרנס לאמונה רבה זו דוקא בכל חדשים לבקרים, ואח\"כ י[ו]כלו נש\"י לייחד בק\"ש יחוד האמיתי בהוי' אחד ע\"י דעת והשגה כמ\"ש שמע ישראל כו' שזהו משה שא' לישראל שמע בשמיעה דבינה בהשגה. אך ענין השגה בשכל לא שייך כלל במהו\"ע ית' דלמת\"ב כלל [כנ\"ל] אלא",[["7795","771","<b>דחכ' שנק' קדש מלה בגרמי'</b>: ראה זהר אמור צד, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a>. מאמרי אדה\"א דברים ח\"ג ע' תתקב."],["7796","772","<b>הוי' ואלקים בחי' סובב וממלא</b>: ראה גם לעיל פ' וארא עג, ב. וש\"נ."],["7797","773","<b>ויאמינו בהוי'</b>: בשלח יד, לא."],["7798","774","<b>והאמין בהוי'</b>: לך טו, ו."],["7799","775","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם לקמן תלה, א."],["7800","776","<b>אתה הראת לדעת</b>: שם ד, לה."],["7801","777","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["7802","778","<b>למת\"ב כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["7803","779","<b>שהי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."],["7804","780","<b>איהו אמת ואיהי אמונה</b>: נסמן לעיל פ' תצוה שעב, ד."]]],[2300550780,"בבחי' דעת והכרה שידיעה זו נק' הכרה במהות כמו שמכיר איש לרעהו וכידע שור קונהו שידיעה זו הכרה עצמי', וכמו לע\"ל שא' כולם ידעו אותי ממש שידיעה זו הכרת המהות ולא השג[ה] בשכל שאינו אלא השג' המציאות ולא במהות [כלל] כידוע, ובחי' הכרה למהו\"ע א\"ס ב\"ה כמו שהוא יחיד לבדו כו' קודם שיהי' מקיף ופנימי בכלל ובפרט שזהו הוי' ואלקי' בחי' או\"כ<sup data-n=\"7805\">781</sup> אין זה רק ע[\"י] משה שהוא בבחי' ד\"ע (שזהו כמו שהוא מיש האמיתי לאין שזהו הי' הוא ושמו בלבד כמ\"ש במ\"א ע\"פ כי אל דעות ה'<sup data-n=\"7806\">782</sup> כו') שממשיך לעדת בנ\"י בחי' ד\"ע זה להיות משיגים ומכירים למהו\"ע ית' כמו שהוא בעצמו, דהכרה זו א\"א להיות כ\"א ברצון שהוא למעלה מן ההשגה בשכל ואח\"כ מתפשט בשכל ודעת וכמ\"ש דע את אלקי<sup data-n=\"7807\">783</sup> כו' דדעת [זה] הוא הבחירה בדעת ורצון שבא מצד ההכרה דאע\"פ דלמת\"ב היינו מח' דחכ' ושכל אבל ברעו\"ד נתפס<sup data-n=\"7808\">784</sup> כידוע, וזהו ענין קבל' עומ\"ש ברצון ודעת דוקא כמו במ\"ת שמלכותו ית' ברצון קבלו עליהם שהוא ברצון ובחירה שהוא ע\"י הדעת דוקא (כמשי\"ת) וד\"ל.\n<b>וזהו</b> ארוממך אלקי המלך וכן ארוממך הוי' כי דליתני<sup data-n=\"7809\">785</sup> כו' שמרומם לשם הוי' דסובב וממלא גם להמלך העליון, שזהו תרומה להוי' לעלות למהו\"ע ית' ממש שא' אני ראשון ואני אחרון<sup data-n=\"7810\">786</sup> כו' ע\"י עומ\"ש מאתכם דוקא, דגם שאינו מצד השגה וטעם רק ברצון פשוט באמונה פשוטה דוקא. אבל הוא בבחי' הכרה וידיעה עצמי' במהו\"ע ית' ממש שהוא ע\"י קבלת עומ\"ש<sup data-n=\"7811\">787</sup> בדעת ורצון שנמשך ע\"י משה בחי' ד\"ע שז\"ש ויקהל משה כו' והתורה נצחי' היא<sup data-n=\"7812\">788</sup> כו' וד\"ל. והנה אחר שנמשך ע\"י בחי' ד\"ע דמשה הכרה ודעת עצמי קבלת עומ\"ש ברצון (כמו שהי' במ\"ת שא' כל אשר דיבר ה' נעשה<sup data-n=\"7813\">789</sup> ברצון כענין שום תשים עליך מלך<sup data-n=\"7814\">790</sup> (כמשי\"ת) ויכול לצוות עליהם ליקח תרומה להוי' ארמותא כו' לרומם לשם הוי' ואלקי' במהו\"ע ממש שיאיר ביתרון אור מאור העונג שבעצמות בתחלה מטעם הנ\"ל ע\"כ אמר כל נדיב לבו יביאה את תרומת הוי' זה כו', ולכאורה מיותר הוא אחר שא' קחו מאתכ\"ם דוקא שרצונו לומר ברצונכם בקבלת מ\"ש ברצון כנ\"ל למה א' עוד כל נדיב לבו דוקא יביאה כו'. ועוד יש להבין דלכאו' ענין נדיבות <span data-k=\"pg\">תרטז</span> ּ לב ברצון ובחירה מצד עצמו זהו היפך לענין עומ\"ש שהעול הוא בא מצד ההכרח ובע\"כ שלא ברצונו ונדיבות לבו כו', והלא מבואר למעלה דכל עיקר הטעם לרומם לשם הוי' או ארוממך אלקי כו' זהו בא רק מצד עומ\"ש דוקא כו'.",[["7805","781","<b>הוי' ואלקי' בחי' או\"כ</b>: ראה גם שער היחוד והאמונה פ\"ד ואילך. לעיל פ' בשלח רמא, ב. וש\"נ."],["7806","782","<b>כי אל דעות ה'</b>: נסמן לעיל פ' יתרו רסא, ד."],["7807","783","<b>דע את אלקי</b>: דהי\"א כח, ט."],["7808","784","<b>ברעו\"ד נתפס</b>: ראה זהר (אד\"ז) האזינו רפט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680128\" data-slug=\"torat-chaim\" data-id=\"2300680128\">תו\"ח וישב קצט, ג</a> ובהערה 56. שע\"ת קכה, א."],["7809","785","<b>ארוממך הוי' כי דליתני</b>: תהלים ל, ב."],["7810","786","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["7811","787","<b>עומ\"ש</b>: טזיז: מ\"ש."],["7812","788","<b>והתורה נצחי' היא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא</a> פי\"ז. לעיל פ' שמות א, א. וש\"נ."],["7813","789","<b>כל אשר דיבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ג."],["7814","790","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."]]],[2300550781,"<b>אך</b> הנה באמת כל עיקר ענין הרוממות והעלא' זו לשם הוי' שנק' תרומת הוי' כנ\"ל זהו רק בשביל הירידה והמשכ' מרוממות והעלא' זו עצמ[ה] להמשיך אורות בכלים דוקא, אך שירידה זו צריך להיות ממקום שעלה לשם דוקא והוא בבחי' רוממות העצמו' ופנימי' דאוא\"ס כמו שהוא מלך יחיד מרומם לבדו מאז כו' כמו נכון כסאך מאז מעולם הא\"ס עצמו כו', שזהו פנימי' כתר מל' דא\"ס בבחי' שעשועי המלך בעצמו בפנימי' חכמתו ופנימי' רצונו שבתו\"מ כמו שהן באור אמית[י]ת עצמותו (שנק' תוה\"ק ומדות הפנימי' דחכמתו העצמי') (כמ\"ש אז ראה ויספרה כו'). והוא כל ענין המשכן דמשה באו\"כ פנימי' כארון ושולחן ומנורה כו' ואו\"מ כיריעות תכלת וארגמן כו' וכל מה שנז' כאן בפ' זו קחו מאתכם כו' זהב וכסף ונחשת בחי' חג\"ת<sup data-n=\"7815\">791</sup> דאצי' ותכלת<sup data-n=\"7816\">792</sup> כו' מקיפי' ושמן למאו\"ר<sup data-n=\"7817\">793</sup> עד ואבני שוה\"ם<sup data-n=\"7818\">794</sup> כו', הכל הוא בבחי' או\"כ הפנימי' דוקא שהוא רק להיות מכון וכלי [פנימי' ועצמי'] להשראת עצמות אור א\"ס כמו שהוא בפנימי' דמל' דא\"ס כמו הארון בחכ'<sup data-n=\"7819\">795</sup> וכת\"ר<sup data-n=\"7820\">796</sup> ובמנורה ושולחן ומזבח הזהב בחו\"ג<sup data-n=\"7821\">797</sup> ות\"ת<sup data-n=\"7822\">798</sup> כו', וכן יריעות מקיפים העליונים כמו עוטה או\"ר כשלמ\"ה<sup data-n=\"7823\">799</sup> כו'. וכל ענין עבודת המשכן זהו הכל רק פנימי' כלים לאורות העצמיי' דא\"ס ב\"ה כמו שהוא באו\"כ הפנימי' דתו\"מ, וכ\"ז צריך להיות ע\"י העלאה לעורר לעצמו' הרוממות דא\"ס שיומשך באו\"כ דמשכן שזהו שנק' תרומת הוי' כלומר בשביל רוממות דש[ם] הוי' שיאיר בפנימי' באו\"כ פנימי' כמו שהוא למעלה במהו\"ע (וכמו שיהי' לע\"ל דכתיב מכון לשבתך פעלת הוי'<sup data-n=\"7824\">800</sup> כו'), ולפי שצ\"ל ירידה והמשכה אוב\"כ<sup data-n=\"7825\">801</sup> דמשכן ע\"כ צריך שיהי' ע\"פ רצון ובחירה דוקא וזהו שא' כל נדיב לבו דוקא יביאה כו' וד\"ל.\n<b>אך</b> לכאורה עדיין אין זה מובן מ\"ש כל נדיב לבו דוקא, דהלא עיקר ענין התרומה להוי' שהוא לרומם למעלה מסובב וממלא כו' במהו\"ע ית' ממש זהו אינו בא רק מצד עומ\"ש דוקא שהוא היפוך נדיבות הלב שזהו ברצון ובחירה כנ\"ל. אך הענין הוא דהכוונה בנדיב לבו זה היינו מי שנדבה לבו לעשות היפוך טבעו ורצונו המוגבל<sup data-n=\"7826\">802</sup> זהו שנק' נדיב לב, שהנדיבות ענינו ביתר מכפי המדה שלו דזה שעושה חסד וצדקה לפי טבעו לבד כמו שהוא בעצם בטבעי' לבבו אינו נק' נדיב אלא כשמפזר הון ביותר מכפי עצם טבעו דוקא נק' נדיב, כמו אברהם שנק' נדיב כמ\"ש בת נדיב בתו של אברהם<sup data-n=\"7827\">803</sup> כו' שהי' עושה חסד וצדקה<sup data-n=\"7828\">804</sup> עם הבריות בטובו'<sup data-n=\"7829\">805</sup> יתירה להתנדב מכל אשר לו שלא ישאר",[["7815","791","<b>זהב וכסף ונחשת בחי' חג\"ת</b>: ויקהל לה, ה. ראה זהר תרומה קמח, ב ובמקדש מלך שם. מאמרי אדה\"א שמות ח\"ב ע' שט. וש\"נ."],["7816","792","<b>ותכלת</b>: ויקהל לה, ו."],["7817","793","<b>ושמן למאו\"ר</b>: שם: לה, ח."],["7818","794","<b>ואבני שוה\"ם</b>: ויקהל שם, ט."],["7819","795","<b>הארון בחכ'</b>: ראה גם לעיל שפו, ד. וש\"נ."],["7820","796","<b>הארון. . וכת\"ר</b>: ראה גם לעיל פ' תרומה שז, ג. וש\"נ. ולקמן תכ, ג: והארון וכפורת. . הח\"ע וכתר."],["7821","797","<b>ובמנורה ושולחן. . בחו\"ג</b>: ראה גם לעיל שפו, ד. וש\"נ."],["7822","798","<b>ומזבח הזהב. . ות\"ת</b>: ראה גם לעיל שצ, ג. וש\"נ."],["7823","799","<b>עוטה או\"ר כשלמ\"ה</b>: תהלים קד, ב."],["7824","800","<b>מכון לשבתך פעלת הוי'</b>: בשלח טו, יז."],["7825","801","<b>אוב\"כ</b>: טזיז: אורות בכלים."],["7826","802","<b>המוגבל</b>: יז: המורגל."],["7827","803","<b>בת נדיב בתו של אברהם</b>: שה\"ש ז, ב. סוכה מט, ב."],["7828","804","<b>שהי' עושה חסד וצדקה</b>: טז: דעביד טיבו."],["7829","805","<b>בטובו'</b>: טזיז: בטיבו."]]],[2300550782,"לעצמו כלום<sup data-n=\"7830\">806</sup> כו'. וזהו שנדבה לבו לעשות יותר מכפי טבעו ולעמוד על נפשו בנדיבות <span data-k=\"pg\">1234</span> ּ הלב להשליך כל עצמו וטבעו דוקא זהו שנק' נדיב לב כו'. וכך הוא בענין קבלת עומ\"ש בעול אע\"פ שתכבד עליו העבודה ביותר והוא עול קשה עליו לעשות נגד טבעו ורגילותו בכל דבר שבקדושה האלקי' כנ\"ל, יעמוד על נפשו להתנדב לבו לקבל באהבה ורצון כל עבודה קשה וכמו שמקבלים עליהם עומ\"ש כמ\"ש שום תשים עליך מלך כו' שאע\"פ שאח\"כ תכבד עליו עול העבודה ביותר. אבל לאחר שקיבל [עליו] ה\"ז הי' בנדיבות הלב שנדבה רוחו ולבו לקבלה זו ע\"ע לקיים כל אשר יגזור אומר אף שיהי' נגד רצונו וטבעו לגמרי אז לא יכבד עליו כ\"כ, ואדרבה ימצא בזה הביטול שמבטל א\"ע נח\"ר ועונג ולא מצד עצם העבודה שבודאי קשה וכבידה לו, [אבל] מה שמבטל רצונו וטבעו נגד רצון המלך שזהו רק לפי שקיבל עליו בנדיבות לבו הרי הוא שנותן בו כח ועוז לבטל כל עצמותו וטבעו ולא יחשיב עצמו לכלום, עד שיקבל עונג ושמחה ונח\"ר<sup data-n=\"7831\">807</sup> במה שקיים רצון המלך אע\"פ שהוא נגד רצונו כי לזה כבר נתן נפשו ורצונו כו' (והוא שנק' רצון לרצון, כי יש לו<sup data-n=\"7832\">808</sup> לרצון מקור הנובע מכבר קודם שנתגלה הרכבה שלו בשכל ומדות וממקור זה יש שינוי [מ]רצון לרצון היפוכו, והוא מה שירצה בהיפוכו דוקא. ואף גם ברצון שבמדות טבעיות הרי גבר על הרצון שלו לשנות טבעו, והוא כמו שיכול לקבל עליו יסורים לעונג ממש ועונג ליסורים, וכך יכול לשנות הרצון הטבעי' בעול עבודה כשיהי' לו רצון לרצון זה בקבלת עול בתחלה שאז יעבוד הכל ברצון ובחירה אע\"פ שמנגד לרצון הטבעי כמו קבלת תענית או קבלת צדקה בכל אשר לו כו' או ללמוד ביגיעה מ\"ש<sup data-n=\"7833\">809</sup> א' כו', וראי' מגט המעושה<sup data-n=\"7834\">810</sup> שאינו רק כפי' שכופין אותו ואו' רוצה אני שחל בו הרצון באמת. וכן הוא ענין הווין<sup data-n=\"7835\">811</sup> דאמת ויציב<sup data-n=\"7836\">812</sup> [כמו] ומתוקן ומקובל כו' שנק' היכל הרצון<sup data-n=\"7837\">813</sup> שאינו רק שמקבל עליו למעשה שיהי' בו הרצון ממילא כו', והוא שנק' הסכם חזק שהוא במקור הרצון לחזק הרצון ולשנותו כו'). ולכך<sup data-n=\"7838\">814</sup> הי' במ\"ת שא' כל אשר דיבר ה' נעשה שקיבלו עליהם עומ\"ש זה בנדיבות הלב, והוא בחי' רצון לרצון שזה[ו] לבטל כל רצונם מפני רצון ה' בכל אשר יגזור אומר עליהם בקבלת עו\"מ<sup data-n=\"7839\">815</sup> שזהו נדיבות הלב לעשות יותר ולנגד טבע[ם] עד שלא תכבד עליהם אח\"כ עול מצות ה' כלל, אע\"פ שיהי' נגד הטבעי' יבטל רצונו ולא יחשיבנה לכלום וכלא ממש חשיב נגד רצון ה' שמלובש במצות ויכול לעשות העבודה האלקי' בסומ\"ר וע\"ט כל היום בלי מונע כלל וכלל מחמת רצונו הטבעי' מצד ההסכם החזק בקבלת עומ\"ש בק\"ש שהוא הבחירה ברצון לרצון לבטל כל רצונו נגד רצון ה' ולקיים רצונו בכל כו' עד שיקבל עונג ושמחה במה שמקיים רצון ה' ומבטל רצונו",[["7830","806","<b>שלא ישאר </b>[טז: ישאיר]<b> לעצמו כלום</b>: ראה גם שע\"ת פח, ג [ובהערה לשם צ\"ל] <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251080\" data-slug=\"likkutei-sichot\" data-id=\"1300251080\">לקו\"ש וירא כרך כה ע' 80</a> הערה 30."],["7831","807","<b>שיקבל עונג ושמחה ונח\"ר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261042\" data-slug=\"likkutei-sichot\" data-id=\"1300261042\">לקו\"ש</a> כ\"ד טבת כרך כו ע' 42 הערה 22."],["7832","808","<b>לו</b>: טזיז: ליתא."],["7833","809","<b>מ\"ש</b>: שם: מס'."],["7834","810","<b>מגט המעושה</b>: גיטין פח, ב. ראה גם לעיל פ' תצוה שעט, ג. מאמרי אדה\"ז תקע\"א ע' קעט ואילך."],["7835","811","<b>ענין הווין</b>: יז: הט\"ו ווין."],["7836","812","<b>הט\"ו ווין דאמת ויציב</b>: ראה גם הנסמן לעיל פ' תרומה שו, ב."],["7837","813","<b>דאמת ויציב. . היכל הרצון</b>: נסמן לעיל פ' תצוה שעט, ג."],["7838","814","<b>ולכך</b>: טזיז: וכך."],["7839","815","<b>עו\"מ</b>: יב: עול מלכות. טז: עומ\"ש."]]],[2300550783,"שבביטול זה דוקא יש שמחה ועונג כנ\"ל. והוא במה שמתבונן שהוא רצון ה' שקיבל עליו עומ\"ש ואע\"פ שהוא נגד רצונו הטבעי וכמ\"ש כל אשר דבר כו' וכמו שאו' ומלכותו ברצון קיבלו<sup data-n=\"7840\">816</sup> כו' אעפ\"י <span data-k=\"pg\">תריז</span> ּ שאח\"כ עובד בעומ\"ש מקבל ברצון ובאהבה עול זה דוקא וד\"ל.\n<b>והיינו</b> מ\"ש כל נדיב לבו דוקא יביאה לתרומת הוי' שהוא בחי' הרוממות לשם הוי' למעלה מכל עיקר ומקור ההשתל' דסובב כו', והיינו לפי שע\"י נדיבות לבו לעשות רצון לרצון היפוך טבעו דוקא ה\"ז מגיע למעלה ג\"כ במקור כל רצון העליון וח\"ע שהוא בעל הרצון<sup data-n=\"7841\">817</sup> עצמו, שזהו מהו\"ע א\"ס ב\"ה ממש כמו שה[ו]א קודם שיעלה ברצונו להאציל ולברוא כו' בכלל ובפרט שזהו קודם שעלה במח' דמל' דא\"ס בצמצום דקו\"ח כו'. וזהו עיקר קבלת עומ\"ש בנדיבות הלב באהבה וברצון מפני שמתקשר לבעל הרצון שכל אשר יגזור אומר יהי' בטל רצונו לנגד רצונו כמו שא' כל אשר דבר ה' נעשה, אע\"פ שעדיין לא שמעו מה רצונו שישמעו ויקבלו אותו אלא רק מה שעתיד לגזור ברצונו מקבלי' בקבלת עול מל' ברצון לרצון כנ\"ל, א\"כ זהו התקשרות באמית[י]ת עצמותו שלמעלה מכל רצון וחכ' שכל אשר יגזור אומר ברצונו וחכמתו בתו\"מ ממילא יקבלו ברצון והיינו בבחי' כת\"ר שבכת\"ר שלמעלה מכת\"ר שבחכ' דתו\"מ כידוע. ולכך קבלת עומ\"ש שבכל מעשה המצות שרשו למעלה מגוף הרצה\"ע שבמצות מטעם זה, ולכך קדמה פ' שמע לקבל [עליו] עומ\"ש דוקא בתחלה ואח\"כ יקבל עליו עומ\"צ<sup data-n=\"7842\">818</sup> שהוא לבטל רצונו מפני רצון ה' דהא בהא תליא, דבלא נדיבות הלב לקבל עליו עומ\"ש ברצון לרצון כנ\"ל לא יוכל להיות קבלת עול מצות באופן שלא תכבד עליו העול כלל כנ\"ל וד\"ל. ולפי שעיקר הכוונה בנדיבות לבו זה להתקשר בעצמות א\"ס ב\"ה ממש שנק' בעל הרצון ע\"כ מקבל עליו לעשות נגד רצון טבעו לזאת מלבד שלא תכבד [עליו] עול העבודה אע\"פ שנגד טבעו בתכלית אלא ימצא בביטול זה שמבטל א\"ע נגד רצון ה' עונג ונח\"ר ושמחה ש\"מ. ונמצא יש כאן שמחה ויראה כא' דמצד עומ\"ש ה\"ז רק מחמת היראה ופחד אלקי' דוקא שאין לו נח\"ר לעצמו כלל בזה כנ\"ל, ושמחה מצד הביטול [בעצמו] בנדיבות לבו דוקא בהסכם החזק ע\"ז שישמח בזה רק מצד עצמו' אלקות ממש בעל הרצון כנ\"ל שאליו הוא נושא את נפשו ונותן ומוסר כל עצמו וטבעו כנ\"ל וד\"ל.\n<b>וזהו</b> שאמר שמח נפש עבדך שמדבר בעובד אלקים רק בעומ\"ש בלבד כנ\"ל שצריך שישמחנו מלמעלה והוא מחמת נדיבות לבו לעשות היפוך טבעיות שלו ולזה א' שמח נפש",[["7840","816","<b>ומלכותו ברצון קיבלו</b>: ברכת אמת ואמונה."],["7841","817","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון שומר אמונים ויכוח שני סכ\"ג ואילך. (דרך מצותיך קלו, א). מאמרי אדה\"ז תק\"ע ע' קפג[א]. מאמרי אדה\"א נ\"ך ע' רסא. ע' שיד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670331\" data-slug=\"torat-chaim\" data-id=\"2300670331\">תו\"ח וירא קיג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550310\" data-slug=\"torat-chaim\" data-id=\"2300550310\">שער האמונה קב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550861\" data-slug=\"torat-chaim\" data-id=\"2300550861\">קג, א</a>. לעיל פ' תצוה שנח, א. לקמן תלב, ב."],["7842","818","<b>קדמה פ' שמע. . עליו עומ\"צ</b>: ברכות יג, א. ראה גם לקמן תלג, ב."]]],[2300550784,"עבדך כי אליך הוי'<sup data-n=\"7843\">819</sup> נפשי הטבעיות אשא להפוך אותה לרצון ה' (והוא רק מצד התקשרות הנפש בעצמות אלקות כמ\"ש כל אשר דבר ה' כו', וז\"ש כי אליך דוקא נפשי אשא דהא בהא תליא כנ\"ל וד\"ל. וזהו שאמרו עבדו את ה' ביראה וגילו ברעדה ולא<sup data-n=\"7844\">820</sup> במקום גילה שם תהא רעדה<sup data-n=\"7845\">821</sup> גילה מבחוץ והוא ענין שמחה ש\"מ כמ\"ש עבדו את ה' בשמחה, והיינו ענין של בחי' נדיבות הלב ברצון וחשק ושמחה לבטל כל עצמו וטבעו כמ\"ש כל אשר כו', והיראה ורעדה מבפנים מצד קבלת <span data-k=\"pg\">1236</span> ּ עומ\"ש ביראה שנק' עול ממש כעול העבד הפשוט מאימת האדון עליו שמחמת זה מתבטל מכל עצמו וטבעו בע\"כ להיות סומ\"ר וע\"ט כל היום בלי שינוי לעולם כנ\"ל וד\"ל.\n[טז]<b> והנה</b> עדיין י\"ל מ\"ש כל נדיב לבו יביאה כו' דמלשון יביאה משמע שזהו בחי' המשכה וירידה להביא ולהמשיך כל תרומת ה' כזהב וכסף כו' למלאכת המשכן, ולפי הנ\"ל בעיקר ענין נדיבות הלב זהו להעלות נפשו ברצון לרצון לעשות נגד טבעו שבזה מעלה לשם הוי' למעלה במהו\"ע ית' שלמעלה מן הרצון וח\"ס<sup data-n=\"7846\">822</sup> דהשתלשלו' כנ\"ל, ואיך א' יביאה לתרומת ה' בהבאה ולא בהעלאה. אך הנה מבואר למעלה דכל עיקר ענין העלאה דתרומה להוי' זהו רק כדי להמשיך האורות העליונים פנימי' ומקיפי' בכלים מכלים שונים בכלי המשכן שהן בחי' הכלים דתו\"מ ממש בחכ' ומדות כנ\"ל, והיינו ג\"כ עיקר הכוונה בקבלת עומ\"ש ברצון בנדיבת הלב שמקבל העול ברצון והסכם חזק מאד כנ\"ל הוא ג\"כ רק להמשיך גילוי רצונו ית' בכלי לבחי' מעשה דוקא, כמו בעול מצות שהוא בקיום המעשה דוקא שלזה נושא נפשו לעשות היפוך טבעו [ו]ישמח בביטול רצונו נגד רצון ה' שיבא בכלי דוקא, וא\"כ גם עומ\"ש שקיבל בתחלה אינו רק לעשות רצונו בכל אשר יגזור אומר למעשה דוקא ובלתי זה אין זה קבלת עומ\"ש כלל כידוע בקבלת גזירת המלך כו'. וכך גם כאן מ\"ש כל נדיב לבו דוקא בקבלת עומ\"ש ברצון לרצון כנ\"ל יביאה לתרומת הוי' במעשה דוקא להיות האור בכלי [כמו] במלאכת המשכן וז\"ש יביא\"ה דוקא וד\"ל.\n<b>אך</b> עדיין אין זה מובן דא\"כ זהו דבר והיפוכו כא' דיביאה משמע להביא ולהמשיך האור בכלי מלמעלה למטה וכנ\"ל, ותרומת הוי' הוא ארמותא לרומם ולהעלות לשם הוי' למעלה דוקא, ואיך א' יביאה את תרומת הוי' דמשמע שתרומה זו שהוא ארמותא דשם הוי' כענין ארוממך הוי' כו' יביאה להמשיך בכלי דוקא והוא כמו לעשות מבחי' או\"ח דגבורות להיות בחי' או\"י דחסד כו'. ואמנם הענין הוא דזה[ו] שאמר הקים ע[ו]ל עולה דתו\"מ שיש בפי' הקים ב' ענינים הפכי' הנ\"ל, א' ענין העלאה",[["7843","819","<b>הוי'</b>: יב: כבפנים. טזיז: ה'. וראה לעיל הערה 148."],["7844","820","<b>ולא</b>: שם: וא'."],["7845","821","<b>במקום גילה שם תהא רעדה</b>: ברכות ל, ב. ראה גם שע\"ת לה, א ובנסמן במ\"מ לשם. לעיל פ' תצוה שכב, ד. שנב, ד."],["7846","822","<b>וח\"ס</b>: טזיז: וחכמה"]]],[2300550785,"והגבהה למעלה והוא להרים ולהעלות משפלות להגבהה כמו מקים מעפר<sup data-n=\"7847\">823</sup> כו'. והב' ענין הקמה ובנין כמו הקמ\"ת המשכן<sup data-n=\"7848\">824</sup> וכן להקים את דברי<sup data-n=\"7849\">825</sup> כו' [הקימותי את דבר ה'<sup data-n=\"7850\">826</sup> כו'] שזהו ענין קיום והעמדה<sup data-n=\"7851\">827</sup> לקיים ולחזק ולהעמיד דבר כמו אישה יקימנ\"ו<sup data-n=\"7852\">828</sup> כו', וזהו ענין ירידה והמשכה בכלי דוקא כהקמת בנין (וכהקמת הנופל שיעמידנו על רגל[י]ו) כמו ויקם משה את המשכן<sup data-n=\"7853\">829</sup> כו'. וזהו ג\"כ ענין מה שאמר שהקים ע[ו]ל עולה של תו\"מ שהגביה והעלה לעול זה למעלה מעלה וגם הקימו בקיום ובנין חזק באו\"כ דוקא ואין זה ב' הפכים כלל דאדרבה הא בהא תליא כו', והיינו ג\"כ פי' יביאה את תרומת הוי' דהבאה זו כמו הקים ע[ו]ל כו' דהקים והביא להעלא' זו למטה כו' וד\"ל.\n<b>וביאור</b> הענין הנה מבואר למעלה בענין נדיב לבו כו' דנדיבות זו היא המביאה לחזק <span data-k=\"pg\">תריח</span> ּ ולקיים העול של העבודה לעשות היפוך טבעו דוקא עד אשר יקבל עונג ושמחה בעול זה שיכול לבטל א\"ע נגד רצון ה' כו', ובאמת עדיין אין זה מובן דמ\"מ מהיכן יבא לו<sup data-n=\"7854\">830</sup> השמחה ועונג במה שהוא נגד טבעו ורצונו בתכלית ואם לפי שנדבה לבו ורוחו בזה לעשות היפוך טבעו<sup data-n=\"7855\">831</sup> כנ\"ל, מהיכן יש בלבו נדיבות זו שגוברת ומושלת על הטבעי' שלו לעשות רצון לרצון בהיפוך טבעו כו'. אך בהכרח לומר שנדיבות הלב כזה אינו בא רק מצד שהשליך נפשו מנגד בהפקירות כל טבעו ועצמו<sup data-n=\"7856\">832</sup> כמו שמתנדב בנפשו לצאת למלחמה או במקום סכנה כו', וכמו אאע\"ה שנק' נדיב לפי שהשליך נפשו מנגד ונדבה לבו ורוחו לעשות רצון קונו באהבה ורצון וחשק לשחוט לבנו יחידו<sup data-n=\"7857\">833</sup> וכה\"ג שזהו שמצא את לבבו נאמן לפניו כו' במה שיוכל להפקיר עצמו בחשק ורצון לעשות נגד טבעו כו', והיינו לפי שהי' נשמת אברהם דבוק וקשור בחבלי עבותות אה\"ר ונפלאה במהו\"ע ית' כמו אליך ה' נפשי אשא במס\"נ אליך ממש לבטל כל עצמו נגד רצונו כו'. וכך הוא במ\"ש בדוד שהקים עולה של תו\"מ, דפי' הקים זה היינו שהעלה והגביה לעומ\"ש שעושה נגד טבעו כמו בע\"כ והוא לפי שהי' נדיב לב שנדבה לבו בהפקירות נפשו לה' לבדו לעשות רצונו אף בדבר שנגד הטבע וכמ\"ש למעלה בפי' נדיב לבו יביאה כו', שנדיבות זו מביאה לעומ\"ש שתתחזק ותתקיים ביותר כו' היינו מה שעי\"ז בא גילוי רצה\"ע במעשה המצות שהיא בחי' כלי להכיל האור למטה דוקא ה\"ז בחי' ירידה והמשכה בכלי היפוך ההעלאה והסתלקות למעלה, אבל באמת אין זה ב' הפכים כנ\"ל דודאי לזאת דוקא נשא את נפשו בנדיבות לבו בהפקירות כל עצמו לה' רק לעשות רצונו שזהו לעשות הרצון ולהביאו בכלי במעשה דוקא כנ\"ל, והיינו הך דעלי' זו היא רק בשביל הירידה לעשות רצונו בכלים. וזהו כל נדיב לבו דוקא יביאה את",[["7847","823","<b>מקים מעפר </b>[טז ניתוסף: דל]: שמו\"א ב, ח."],["7848","824","<b>הקמ\"ת המשכן</b>: לשון במדב\"ר פי\"ב יב. יל\"ש שה\"ש א, יב (רמז תתקפג)."],["7849","825","<b>להקים את דברי</b>: מל\"ב כג, ג."],["7850","826","<b>הקימותי את דבר ה'</b>: שמו\"א טו, יג."],["7851","827","<b>קיום והעמדה</b>: טז: ליתא."],["7852","828","<b>אישה יקימנ\"ו</b>: מטות ל, יד."],["7853","829","<b>ויקם משה את המשכן</b>: פקודי מ, יח."],["7854","830","<b>יבא לו. . מהיכן</b>: טז ליתא. וכנראה נשמט מפני תיבות הדומות: מהיכן. . מהיכן."],["7855","831","<b>טבעו</b>: בתו\"ח כאן באים עוה\"פ התיבות: דוקא עד אשר. . טבעו."],["7856","832","<b>טבעו ועצמו</b>: טזיז: עצמו[תו] וטבעו."],["7857","833","<b>אאע\"ה. . לשחוט לבנו יחידו</b>: ראה וירא פכ\"ב."]]],[2300550786,"תרומת ה' בכלי דוקא כנ\"ל, וזהו ג\"כ פי' הקי\"ם ע[ו]ל דהקמה זו הוא ענין העלאה בהיות שמעלה ומגביה לעול זה באמצעות ההפקירות בבחי' נדיבות הלב, ואמנם עיקר העליי' הזאת אינו רק בשביל הירידה להביא ולהמשיך לרצה\"ע לבחי' הכלים שזהו שנק' הקמה כמקיים ומעמיד הדבר שהוא<sup data-n=\"7858\">834</sup> דוקא כשבא לקיום במעשה כמו הקימותי את דבר כו' להקים את דברו כו', וכן הוא ענין הקמת בנין [כ]הקמת המשכן שזהו שמעמידו ומקים [אותו בכלי'] שלו כארון ושולחן כו' ויריעות להמשיך האורות בכלים דוקא וזהו הקי\"ם עו\"ל וד\"ל.\n<b>אך</b> הנה עדיין לא יובן מהיכן יבא ענין השמחה ועונג האלקי במעשה המצוה בעול עבודה קשה שנגד טבעו בתכלית שאם מצד הנדיבות שבלב כנ\"ל ה\"ז רק ענין הפקירות לבד כנ\"ל <span data-k=\"pg\">1238</span> ּ ולא שמחה ועונג ואיך יוכל להיות שמחה ש\"מ שזהו עיקר המביא וממשיך האור בכלי דוקא כידוע בענין ברכות המצות בא\"י אשר קדשנו כו' עובר לעשייתו<sup data-n=\"7859\">835</sup> דוקא (וכמבואר בשמחה ועונג דמצות באשרי תמימי<sup data-n=\"7860\">836</sup> כו'). והנה שרש הענין הוא לפי שדוד הי' מרכבה לבחי' מל'<sup data-n=\"7861\">837</sup> דאצי' כמו שהיא בשרש הראשון דמל' דא\"ס דהיינו בבחי' הפנימי' ועצמי' דעונג שבכת\"ר מל' דא\"ס כמ\"ש אני ראשון ואני אחרון<sup data-n=\"7862\">838</sup> כו', וע\"כ משם דוקא יוכל להיות המשכה והארת אור להיות בחי' עונג ושמחה האלקי' גם בעובד אלקי' בעומ\"ש שתשמח הניצוץ האלקי במעשה המצוה בקיומו לרצה\"ע בביטול עצמות רצונו הטבעי' אע\"פ שקשה עליו העבודה ביותר [כו']. וזהו שהקים דוד [ל]עול מצות שהעלה והקימה משפלותה למעלה מעלה והוא [ב]מה שהמשיך בעול זה מבחי' פנימי' העונג שברוממו' העצמו' דמל' דא\"ס דוקא. וז\"ש ארוממ\"ך אלקי המלך בעול תו\"מ דוקא, וזהו דוקא בעול תו\"מ ולא בסתם קבלת עומ\"ש כמלאכים שמקבלים ג\"כ עליהם עומ\"ש, שאין זה מגיע רק בהתפשטו' דחיצוני' המל' בנבראים להיות מלך על עם כו' משא\"כ קבלת עול תו\"מ שמגיע בפנימי' העונג דמל' דא\"ס כמו שהוא בעצמותו ממש, לפי שלזה דוקא הוא שעלה במח' הפנימי' דכת\"ר מל' דא\"ס (שנק' שעשועי המלך בעצמו ממש כנ\"ל) וכנ\"ל במ\"ש ויקהל משה לעד\"ת כו' שהעלה אותם לבחי' ד\"ע, שזהו כמו שמעצמות א\"ס בא בגילוי אור פנימי' ועצמו' ממש כמו שהי' הוא ושמו העצמי בלבד כנ\"ל (שנק' מי\"ש לאי\"ן כו'). וכאשר יומשך בנשמות מבחי' מהו\"ע דגילוי אוא\"ס ב\"ה כמו שהוא מלך מרומם לבדו מאז, כידוע שזהו כמו שהע\"ס דאצי' גנוזות<sup data-n=\"7863\">839</sup> בהעלם העצמו' דא\"ס ממש טרם שבאו בגילוי רצון וחכמה ומדות כמו חכים ולא בחכ' ידיעא כו' עד ולאו מכא\"מ כלל<sup data-n=\"7864\">840</sup> ונק' ע\"ס בלי מ\"ה<sup data-n=\"7865\">841</sup>, כידוע שהוא קודם שיהי' בנין האורות בכלים כו', אזי משם דוקא יומשך בנשמות (ע\"י שיתבוננו ויחשקו ליכלל ברוממות העצמ[ו]'",[["7858","834","<b>שהוא</b>: טזיז: שזהו."],["7859","835","<b>ברכות המצות. . עובר לעשייתו</b>: ראה לעיל פ' תצוה שלא, א. וש\"נ."],["7860","836","<b>באשרי תמימי</b>: תהלים קאפיטול קיט."],["7861","837","<b>שדוד הי' מרכבה לבחי' מל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["7862","838","<b>מל' דאצי'. . דמל' דא\"ס. . אני. . אחרון</b>: ראה גם לעיל פ' וארא סא, ב ובהערה 71."],["7863","839","<b>שהע\"ס. . גנוזות</b>: נסמן לעיל פ' יתרו רסה, ג הערה 116."],["7864","840","<b>חכים ולא בחכ'. . מכא\"מ כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["7865","841","<b>ע\"ס בלי מ\"ה</b>: ס\"י פ\"א, מ\"ב."]]],[2300550787,"דהוי') בחי' עונג ושמחה במעשה העבודה האלקי' בתו\"מ להמשיך אור בכלי דוקא בבחי' שוב דוקא, כי אחרי בחי' ההעלאה ברוממות העצמו' דהוי' כמו רוממות אל בגרונם<sup data-n=\"7866\">842</sup> כו' יומשך משם לנשמות העונג ושמחה בבחי' ירידה והמשכה דוקא שהוא להמשיך ולגנוז האורות בכלים דוקא וד\"ל.\n<b>וטעם</b> ושרש הדבר יובן עפ\"י המבואר למעלה בענין [ה]ב\"מ שהריחה צ\"ק תאמר כו' שזהו מחמת ענין דרו\"ש [שבמלכ\"ו'] בכלל ובפרט דע\"י בחי' הרוממות וההתנשאו' מצד העצמ[ו]' בתענוג השעשועי' עצמי' כו' מצד זה יהי' בחי' הרצוא למעלה בעצמותו, וזהו מפני הגנאי להשפיל א\"ע להיות ראש ומקור למטה כו', אך מצד שירד העונג העצמי בהיפוכו דוקא להיות יתרון האור מן החושך למטה בבירורי' דרפ\"ח כו' שהוא ע\"י ביטול היש לאין בקבלת עול דתו\"מ דוקא כנ\"ל, עי\"ז יהי' סיבת בחי' השוב למטה שיהי' מתצמצם בעצמות הרוממות להיות בבחי' התפשטות המל' למטה דוקא כו' כנ\"ל. וכך הוא ברוממות דעצמות מל' דא\"ס קודם צמצום הראשון כמ\"ש אני ראשון ואני <span data-k=\"pg\">תריט</span> ּ אחרון כנ\"ל, עד שבחי' השו\"ב בירידת העונג בהיפוכו דוקא כשעולה למעלה באו\"ח גדול יותר מתענוג העצמי דאו\"י דהיינו מה שנמשך מפנימי' ועצמות התענוג בזה יותר להיות רבוי האורות בכלים לאין שיעור כלל, משום דלזה הי' עיקר התענוג ורצון ומח' בפנימי' דמל' דא\"ס כנ\"ל וד\"ל.\n<b>וכך</b> יובן ממש בנש\"י<sup data-n=\"7867\">*843</sup> האלקי' בדרך פרט שדומה הנפעל לפועל האלקי שהוא ג\"כ בבחי' רו\"ש כמו והחיות רו\"ש דמלאכים כו', דבחי' הרצוא זהו מה שתכסוף הנפש וגם כלתה ליכלל ולידבק למעלה במקור חוצבה באלקי' חיים ולצאת מכלי הגבלתה באה\"ר ונפלאה (שזהו בחי' עבד נאמן להוי' בהתקשרות אה\"ר פנימי' וכן בחי' ב\"ן כמשה ואברהם וכה\"ג כנ\"ל). [ו]כמו למעלה במל' שנק' עולת תמיד כו' דקארי [תדיר] לנה\"ע כו' וכן במל' דא\"ס כנ\"ל), והיינו כמ\"ש למעלה בהגלות נגלות אור ה' כמו שהוא למעלה בעונג העצמי דמל' דא\"ס שנק' מלך מרומם לבדו כו' בהשגות [ב]נשמות שממילא אז יומשך גם בנשמות בחי' רצוא בהתפעלות אה\"ר ודביקות ליכלל למעלה דוקא. ואמנם אחרי בחי' רצוא זה ממקום שעלו שם משם דוקא יומשך בירידה והמשכה דבחי' שוב למטה כמו שלמעלה נמשך ירידת העונג דעצמות בהיפוכו דוקא להיות ראש ומקור למטה להמשיך אור בכלי דוקא כו'. וכך הוא בנשמות שיחפוץ האדם במעשה עול העבודה האלקי' להיות המשכת אלקות בכלים מכלים שונים דוקא בתו\"מ וצדקה וכה\"ג שעי\"ז נמשך גם למעלה אורות בכלים דוקא כנ\"ל, והוא העונג ושמחה שנמצא בעול עבודה זו במה שמבטל רצונו מפני רצון ה' שהוא להמשיך",[["7866","842","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["7867","*843","<b>בנש\"י</b>: יז: בנשמה."]]],[2300550788,"ולגנוז האור האלקי בכלים למעשה דוקא להיות גילוי אלקות בארץ [ו]להפוך גם חושך לאור ורע לטוב כו', בזה דוקא יהי' עיקר התענוג ורצון היפוך התשוקה והתענוג לעלות למעלה בבחי' רצוא, מטעם הנ\"ל דסוף מעשה הוא שעבמ\"ת<sup data-n=\"7868\">843</sup> וקודם לעונג שבמל' בעצמו[תו] כו' וע\"כ מזה נמשך ריבוי האורות בכלים דוקא היפוך ההסתלקו' דבחי' רצוא למעלה כו' וד\"ל (וכמ\"ש במ\"א בענין בע\"כ אתה חי<sup data-n=\"7869\">844</sup> שגם אם תגבר התשוקה האלקי' בנשמות לעלות וליכלל למעלה במקור חוצבה עד כלותה ממש, הנה בע\"כ ונגד רצון ותשוקה זו יבא לרצון היפוכו ממש שהוא לעבוד בעומ\"ש להמשיך אורות בכלים דוקא. וזהו בע\"כ של הנשמה שחפצה למות בכליו\"ן הנפש בתשוקה אתה חי בבחי' שוב להשיב רוחו אליו במה שיומשך גילוי אלקות בנפשו ורוחו כמו שהוא למטה, לזאת תהי' נחמתו ויעשה בשמחה וטוב לבב כל עבודה זו. וזהו ואתם בנ\"י לא כליתם במס\"נ כו'. וזהו ואתה משמר\"ה בקרבי שכח זה דבחי' שוב אתה משמרה בקרבי לבלתי תצא מקרבי במס\"נ (דבחי' רצוא כענין בע\"כ אתה חי, וזהו כד עייל ונפיק<sup data-n=\"7870\">845</sup> דנשמות הגבוהות שבבחי' התיקון דש[ם] מ\"ה כו' (כמו ב\"ע הציץ ומת<sup data-n=\"7871\">846</sup> כו'<sup data-n=\"7872\">847</sup> שנסתלק[ו באד\"ר]<sup data-n=\"7873\">848</sup> ור\"ע יצא בשלום<sup data-n=\"7874\">849</sup> בבחי' התיקון דתו\"מ כנ\"ל).\n<b>ובכ\"ז</b> יובן בתוס' ביאור מ\"ש כאן כל נדיב לבו דוקא יביאה את כל<sup data-n=\"7875\">850</sup> תרומת ה' כו' <span data-k=\"pg\">1240</span> ּ דנדיב לב זה היינו מי שנדבה לבו ורוחו להמשיך אור האלקי בכלים דתו\"מ בבחי' שוב דוקא היפך טבע הנשמה לצאת מן הכלי, שזהו מחמת בחי' שוב העליון שיורד מעונג העצמי' בהיפוכו דוקא בצער שמנגד לעונג והוא בקבלת עול תומ\"צ שהקים דוד והעלה למעלה כנ\"ל להיות משם ירידה והמשכה בהקמת בנין או\"כ. וזהו שנדיב לב זה הוא העושה היפוך טבעי' לבבו בעול העבודה האלקי' להיות לו עונג ושמחה מביטול רצון זה דוקא לרצון ה' אע\"פ שמנגד לטבע גופו, וע\"כ נדיב לב זה הוא המביא לכל תרומת הוי' שעולה למעלה באו\"ח להיות בירידה והמשכה למטה דוקא באו\"י דחסדים בבחי' שוב בכלים דמעשה המצות כמו שא' הקים עולה של תו\"מ בהקמת המשכן בבנין להביא אורות בכלים דוקא. וכן<sup data-n=\"7876\">851</sup> כל נדיב לבו יביאה לתרומת הוי' זהב וכסף כו' אוי\"ר<sup data-n=\"7877\">852</sup> או\"פ ואו\"מ דיריעות להיות בכלים דוקא וד\"ל.\n[יז<sup data-n=\"7878\">853</sup> ] ומעתה י\"ל במ\"ש בראש פ' זו במצות השבת והוא מ\"ש ויקהל משה את כל עדת כו' ויאמר אליהם אלה הדברים אשר צוה ה' לעשות אותם ששת ימים תעשה מלאכה וביום הז' יהי' לכם קדש שבת שבתון להוי' כו' עד לא",[["7868","843","<b>דסוף מעשה הוא שעבמ\"ת</b>: ע\"פ פיוט לכה דודי."],["7869","844","<b>בע\"כ אתה חי</b>: ראה גם לעיל שפט, ד. וש\"נ."],["7870","845","<b>כד עייל ונפיק</b>: ראה זהר בראשית כו, ב. מאמרי אדה\"ז תקע\"א ע' קפא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680362\" data-slug=\"torat-chaim\" data-id=\"2300680362\">תו\"ח וישלח קצד, ב</a> ובהערה 31."],["7871","846","<b>ב\"ע הציץ ומת</b>: חגיגה יד, ב. ראה גם לעיל פ' בא קב, ב. וש\"נ."],["7872","847","<b>כו'</b>: יביז: ובסבות."],["7873","848","<b>ובסבות שנסתלק[ו באד\"ר]</b>: זהר (אד\"ר) נשא קמד, א-ב. וראה גם לעיל פ' שמות לג, ב הערה 303."],["7874","849","<b>ור\"ע יצא בשלום</b>: חגיגה שם."],["7875","850","<b>כל</b>: יז: ליתא."],["7876","851","<b>וכן</b>: יביז: וכך."],["7877","852","<b>זהב וכסף. . אוי\"ר</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370126\" data-slug=\"torah-or\" data-id=\"3901370126\">תו\"א וישב כו, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680096\" data-slug=\"torat-chaim\" data-id=\"2300680096\">תו\"ח וישב קצט, א</a>."],["7878","853","<b>יז</b>: יב: יא."]]],[2300550789,"תבערו אש<sup data-n=\"7879\">854</sup> כו', דלכאורה אין זה סמיכות וחיבור ענין לענין הציווי שאח\"ז במצות מלאכת המשכן שא' קחו מאתכם תרומה ולמה צריך להקדים מצות השבת למצות מלאכת המשכן, ומה שיצוה אותם בעת ושעה אחת שהוא בהקהלה זו שהקהיל כל עדת בנ\"י וא' להם מצות השבת ואח\"ז ויאמר משה זה הדבר כו' קחו מאתכם כו' דמובן מזה שענין א' הוא ממש כו'. ועוד י\"ל מ\"ש אלה הדברים ל' רבים ואח\"כ אומר רק דבר א' לבד והוא מ\"ש ו' ימים תעשה כו'. ועוד מהו לשון תעשה בקמץ תחת העי\"ן וצירי תחת התי\"ו דמשמע תיעשה מאליה וממילא כו'. אך הנה ידוע שכל ל\"ט מלאכות שנאסרו בשבת<sup data-n=\"7880\">855</sup> נלמדו כולם [רק] ממלאכת המשכן ולכך אמר אלה הדברים ל' רבים שהן ל\"ט מלאכות שציוה ה' לעשות אותם במשכן והן שנאסרו בשבת, וז\"ש אלה הדברים שהן ל\"ט מלאכות בו' ימים תיעשה כו' אבל ביום<sup data-n=\"7881\">856</sup> הז' כו'. ובזה מתורץ מ\"ש אלה הדברים שהן רבים שהן ל\"ט מלאכות בל[שון] מ\"ע אשר ציוה ה' לעשות אותם דקאי במלאכות שנאסרו בשבת ונעשים בו' ימים כו', וא\"כ מלאכת המשכן דומה לימות החול שנעשה בהן הל\"ט מלאכות והרי המשכן נק' קדש כמ\"ש ומקדשי תיראו כו' שתלוי באת שבתותי תשמרו<sup data-n=\"7882\">857</sup> כו'. אך באמת מ\"ש אלה הדברים אשר צוה ה' בל' רבים הן רמ\"ח מ\"ע<sup data-n=\"7883\">858</sup> שכלולים בו' מדות שהן ו' ימי המעשה לברר בירורי' בל\"ט מלאכות ברפ\"ח ניצוצות לברר בין טו\"ר ולהפוך [חשך] לאור כו', ולכך א' ו' ימים תיעשה כו' וביום הז' כו' קדש יהי' לכם כו' שהוא קדש מלה בגרמי' בפנימי' דחכ' למעלה מבחי' הבירורי' כידוע וד\"ל.\n<b>והנה</b> תחלה י\"ל מ\"ש <span data-k=\"pg\">תרכ</span> ּ ו' ימים תעשה מלאכה ממילא ומאליו כו', דענין זה שייך למצוה שאח\"ז בתרומת המשכן שא' קחו מאתכם כו' כל נדיב לבו כו' שזהו בקבלת עול בלבד שהקים עולה דתו\"מ כדי להיות הקמת המשכן באו\"כ דוקא. וכך הוא ענין הבירורים דרפ\"ח כו' בסומ\"ר וע\"ט במ\"ע ול\"ת שצריך להיות בעומ\"ש ביגיעה ועמל בעבודה כמו יגיעה ועמל מלאכה בו' ימי המעשה שזהו שא' ו' ימים תעשה מלאכה שתיעשה מעצמה ולא תעשה בכח עצמך כו', שהכוונה בזה ע\"ד הפשוט ענין יגיעה ועמל בכל עסקיו שעושה שאינו ברצון ומדות שבלב כלל שנק' יגיע כפיו בלבד שהיגיעה והעמל הזה אינו רק בכפי[ו] שהוא בפעולת ידיו והילוך רגליו בעסק המעשה בלבד, וכמו וברכך ה' בכל אשר תעשה<sup data-n=\"7884\">859</sup> שאינו צריך רק להכין הכלי שהוא בחי' המעשה שעושה ביגיע כפיו לבד מבלי שישים בזה בחי' פנימי' שכל ופנימי' לבו ודעתו בעומק העיון [ב]תחבולות שונות, שאם ישים בעבודה הזאת פנימי' שכלו ולבו בעומק הרצון ומדות ומח'",[["7879","854","<b>לא תבערו אש</b>: ויקהל לה, ג."],["7880","855","<b>ל\"ט מלאכות שנאסרו בשבת</b>: ראה שבת עג, א."],["7881","856","<b>אבל ביום. . כו'</b>: יז: ליתא. וכנראה נשמט מפני תיבות הדומות כו'. . כו'."],["7882","857","<b>ומקדשי תיראו. . באת שבתותי תשמרו</b>: קדושים יט, ל. בהר כו, ב."],["7883","858","<b>רמ\"ע מ\"ע</b>: מכות כג, סע\"ב."],["7884","859","<b>וברכך ה' בכל אשר תעשה</b>: פ' ראה טו, יח [ושם ה\"א]. ראה גם לעיל פ' שמות לח, ג. וש\"נ."]]],[2300550790,"לא נק' עבודה ביגיעה ועמל כלל כי נעשה הכל בחשק וזריזות בלתי מרגיש כלל [ל]יגיעה ועמל ולא תקצר רוחו בעבודה זו כלל וכלל, כידוע בעוסקי[ם] בפרנסה בחשק ותאוות לבם שמשימי' כל פנימי' השכל והרצון ומדות שבלב ולא ירגיש בכל טורח ועמל בזה וגם מה שלא תעלה יפה כפי רצונו ישים נפשו בכפו לתקן המקולקל בכל כח ועוז כו' (וכדוגמא שהי' בדור הפלגה בעבודתם בחומר ולבנים<sup data-n=\"7885\">860</sup> בעבודה קשה ולא הרגישו עמל ויגיעה כלל היפוך העבודה בחו\"ל שעבדו ישראל במצרים<sup data-n=\"7886\">861</sup> שקצרו רוחם [ב]עול קשה וכבידה שבזה תיקנו לדור ההפלגה<sup data-n=\"7887\">862</sup> כו'. וכך גם עכשיו בטרדת הפרנסה בעבודה ויגיעה עד מיצוי הנפש ממש עד שבנפשו יביא לחמו זהו תיקון [ל]עון ע\"ז שהי' בב\"ר בישראל לכו\"מ להשפיע להם בדרך הטבע בהצלחה שהוא נפרד מאלקות כו', וכמ\"ש אותי עזבו מקור כו' לחצוב להם בורות<sup data-n=\"7888\">863</sup> נשברים כו' שאין מזל לישראל<sup data-n=\"7889\">864</sup> כידוע, ולכך ישראל שבח\"ל דוקא נק' עובדי ע\"ז בטהרה<sup data-n=\"7890\">865</sup> בעוסקי' ורודפי' בחשק נמרץ בפרנסה בכל לונ\"ח<sup data-n=\"7891\">866</sup> לקבל השפע בהצלחת הטבע כו' כנ\"ל). וכ\"ז לא נק' עבודה ועמל ביגיעה כלל, רק כשלא ישים לבו ודעתו כלל בעבודת[ו ו]עסקיו כי ישליך על ה' יהבו שהוא מכלכל חיים בחסד וישלח ברכה ביגיע כפיו ומעשה ידיו ולא יועיל כלל כל חכמה ותחבולה כו', אזי נק' עבודה בעמל ויגיעה כי אין עושה בנח\"ר וחשק ורצון רק להיות כלי להכיל ברכה מאת ה' כו'. וגם זה שמצד שמבלבלו מעבודת ה' בתו\"מ ותפלה יתמרמר בנפשו על שמכלה ימי חיי הבלו בעסק ועבודת פרנסה, ולא עוד אלא שאינו מוצא הצלחה ביגיע כפיו רק אחר היגיעה ועמל בנפשו בטורח קשה ביותר עד מיצוי הנפש שתקצר רוחו בעמלו ביותר כו'.\n<b>וזהו</b> מצד חטא אדה\"ר בעה\"ד<sup data-n=\"7892\">867</sup> טו\"ר שנתערב רע בטוב גם בארץ דמפקא מזון<sup data-n=\"7893\">868</sup> ומחי' לאדם ולכך נתקלל אדם רק באדמה שא' ארורה האדמה בעבורך<sup data-n=\"7894\">869</sup> בעצבון תאכלנה כו' עד בזיעת אפיך תאכל לחם<sup data-n=\"7895\">870</sup>, לפי שצריך לעבוד את האדמה לתקנה מקלקולה<sup data-n=\"7896\">871</sup> שנתקלקלה<sup data-n=\"7897\">*872</sup> בתערובות רע וע\"י עבודת האדמה בחרישה וזריעה כו' <span data-k=\"pg\">1242</span> ּ ול\"ט מלאכות יתקן לברר הטוב מן הרע עד שיוציא לחם טוב למזון מן הארץ. ועבודה הזאת באה לאדם באדמתו ביגיעה רבה ועצומה, לכך א' בזיעת אפך תאכל לחם שזהו ג\"כ מן הקללות שנתקלל שיאכל לחמו בזיעת אפו דוקא, כמו הזיעה באדם באפו שיוצא מתוך כבידות עול",[["7885","860","<b>בדור הפלגה בעבודתם בחומר ולבנים</b>: נח יא, ב."],["7886","861","<b>בחו\"ל שעבדו ישראל במצרים</b>: שמות א, יד."],["7887","862","<b>ישראל במצרים. . תיקנו לדור ההפלגה</b>: ראה גם לעיל פ' שמות ב, ג. וש\"נ."],["7888","863","<b>אותי עזבו. . בורות</b>: ירמי' ב, יג [ושם: בארות בארת]."],["7889","864","<b>שאין מזל לישראל</b>: שבת קנו, א. ראה גם לעיל פ' שמות ב, א. וש\"נ."],["7890","865","<b>ישראל שבח\"ל. . עובדי ע\"ז בטהרה</b>: ע\"ז ח, א. ראה גם לעיל לח, א. וש\"נ."],["7891","866","<b>לונ\"ח</b>: לב ונפש חפיצה. יז: לו\"נ."],["7892","867","<b>וזהו מצד חטא אדה\"ר בעה\"ד</b>: מכאן ועד לקמן וטוב לך בעוה\"ב (שעל יד הערה 900) ראה המשך תרס\"ו ע' שלג עד ריש ע' שלו. בשינויים והוספות."],["7893","868","<b>בארץ דמפקא מזון</b>: ברכות מט, א."],["7894","869","<b>ארורה האדמה בעבורך</b>: בראשית ג, יז."],["7895","870","<b>בזיעת אפיך תאכל לחם</b>: בראשית שם, יט."],["7896","871","<b>לעבוד את האדמה לתקנה מקלקולה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670154\" data-slug=\"torat-chaim\" data-id=\"2300670154\">תו\"ח בראשית לב, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670061\" data-slug=\"torat-chaim\" data-id=\"2300670061\">נח נט, ב</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשח ואילך."],["7897","*872","<b>שנתקלקלה</b>: יבטז: שנתקללה."]]],[2300550791,"העבודה ביותר כידוע. ובאמת לכאורה מה זו קללה לאדם הלא כל מה שיעבוד אדמתו יותר בתיקוני' ובירורי' שלה ודאי ימצא בה מזונו ומחייתו הרבה יותר כמ\"ש עוב\"ד אדמת\"ו דוקא ישבע לחם<sup data-n=\"7898\">872</sup> כדי שביעה לרוב כו', ואם אינו עובד אדמתו ביגיעה רבה כפי הצריך לא ישבע לחם כלל וכלל כו' (וכך הוא בעסק עמל פרנסה בכל אשר יעשה אם אינו עובד בה בכל מה שצריך ביגיעה רבה לא ימצא ולא ישבע לחם כלל כו').\n<b>אך</b> הענין הוא דשני הפסוקי' הנ\"ל אמת ואינם סותרים זא\"ז כלל דהנה אנו רואים בגוף ענין שפע דפרנסה ב' מדרגות, א' השפע וברכה האלקי' שהולך ויורד מלמעלה למטה ביושר שזהו בקו החסדים דאו\"י שה' זן ומפרנס בטובו הגדול בחן וחסד לכל הברואים כמו שאו' בברכת הזן כו' (שמשה ת[י]קנה<sup data-n=\"7899\">873</sup> כשירד המן לישראל שנק' לחם מן השמים<sup data-n=\"7900\">874</sup> דוקא), שזהו בחי' החסדי' הטובים ועצמיי' שהולך תמיד מלמעלה למטה בכל יום ויום כמארז\"ל יב\"ש הוי היום<sup data-n=\"7901\">875</sup> כו' ג\"ש יושב וזן את כל העולם כו', וזהו מחסד אל כל היום<sup data-n=\"7902\">876</sup> שנמשך<sup data-n=\"7903\">877</sup> ונמשך מר\"ה שנמשך שפע כללי' למזונותיו של אדם כל השנה ומתחלק החסד הכללי לימים כו'. אך עכ\"ז הרי א' אדם נידון בכל יום<sup data-n=\"7904\">878</sup> בפרנסתו כמ\"ש לרגעים תבחננו<sup data-n=\"7905\">879</sup> כו', ולכך או' בברכת הארץ דוקא ועל אכילת מזון כו' בכל יום ובכל עת ושעה<sup data-n=\"7906\">880</sup> כו' משום דזה[ו] מדרגה הב' בפרנסה שמתחדשת בכל עת ושעה מאין ליש ממש, והיינו במזון ולחם שמן הארץ דוקא שנק' ארץ דמפקא מזון ונק' לחם מן הארץ שעולה מלמטה למעלה בבחי' או\"ח דוקא (וזהו בברכת הארץ שתיקן יהושע<sup data-n=\"7907\">881</sup> בכניסתו לארץ ששם ציוה ה' את הברכה בארץ דוקא שנק' ברכה בסוף ע\"י עבודת הארץ בחרישה וזריעה כו', שנק' עמ\"ל מלאכ\"ה ביגיעה רבה ועצומה עד מיצוי הנפש שבנפשו יביא לחמו לתקן החטא דעה\"ד טו\"ר לברר הטוב מן הרע ולהוציא הרע ופסולת בזריעה וקצירה ודישה, וכל שיעבו\"ד אדמת\"ו יותר יותר יחודש מאין ממש ליש שיצמח בריבוי יותר שזהו עיבור<sup data-n=\"7908\">883</sup> התיקון לתערובות טו\"ר שבארץ שעי\"ז דוקא יהי' יתרון שפע וברכה יותר מעצם הברכה שבראש<sup data-n=\"7909\">882</sup> שהולך מלמעלה למטה מצד עצם החסד וטוב שזן את העולם בחן ובחסד כו', וזהו שמסיים על הארץ ועל המזון ארץ דמפקא מזון מלמטה למעלה כו'. וכך הוא בעסק הפרנסה שאדם נידון בכל עת ורגע כו' זהו בברכה כמו<sup data-n=\"7910\">884</sup> בעסקיו ויגיע כפיו",[["7898","872","<b>עוב\"ד אדמת\"ו. . ישבע לחם</b>: משלי יב, יא. כח, יט."],["7899","873","<b>בברכת הזן. . שמשה ת[י]קנה</b>: ברכות מח, ב."],["7900","874","<b>המן. . שנק' לחם מן השמים</b>: בשלח טז, ד. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתיז."],["7901","875","<b>יב\"ש הוי היום</b>: ראה ע\"ז ג, ב."],["7902","876","<b>מחסד אל כל היום</b>: תהלים נב, ג."],["7903","877","<b>שנמשך</b>: טזיז: שבא."],["7904","878","<b>אדם נידון בכל יום</b>: ר\"ה טז, א."],["7905","879","<b>לרגעים תבחננו</b>: איוב ז, יח."],["7906","880","<b>ושעה</b>: טז: ובכל שעה. וכ\"ה בסמוך בפנים (תטו, א שו\"ה לחם כנ\"ל)."],["7907","881","<b>בברכת הארץ שתיקן יהושע</b>: ברכות מח, ב."],["7908","883","<b>עיבור</b>: טזיז: עיקר."],["7909","882","<b>ברכה בסוף. . הברכה שבראש</b>: ראה גם לעיל פ' בשלח ריז, א. וש\"נ."],["7910","884","<b>כמו</b>: טזיז: ליתא."]]],[2300550792,"שיחודש מאי\"ן לי\"ש שא\"א להיות כ\"א ע\"י ביטול הי\"ש לאי\"ן בתכלית כרקבון הזריעה כו' וכעוצב ומורת רוח ביגיעתו בעבודת האדמה לתקנה עד שתקצר רוחו בעמלו בשדה כל היום, וכל שיהי' בעוצב ויאוש בעמלו אחר שאינו רואה הצלחה ביגיעתו אדרבה מזה הביטול מי\"ש לאין יצמח אור ושפע בהצלחה רבה להוסיף ברכה בלי שיעור כו' כדי שהלוך<sup data-n=\"7911\">885</sup> <span data-k=\"pg\">תרכא</span> ּ ילך ובכה<sup data-n=\"7912\">886</sup> כו' בא יבא כו', לפי שזהו עיקר התיקון של הקללה שא' לאדם בזיעת אפך תאכל לחם דזיעת אפו זהו מצד שתקצר רוחו בעמלו ועבודתו עד מיצוי הנפש ואו' נואש כו' שאז יהי' מלאכתו בזיעת אפו [כמו] בעול עבודה קשה שלא לנחת ורצון כנ\"ל, ואמנם עי\"ז דוקא תאכל לחם מן הארץ ברוב שפע וברכה כמ\"ש עובד אדמת\"ו ביגיעה ועמל יותר ישבע לחם לרוב יותר כנ\"ל.\n<b>ונמצא</b> דב' הפסוקי' הללו שניהם ענין א', דקללה זו דבזיע\"ת אפ\"ך דוקא תאכל לחם זהו הסיבה לברכה ושפע רב ביותר לפי שזהו עיקר התיקון לחטא עה\"ד להיות ביטול הי\"ש לאי\"ן בעמל רב ביגיע כפיו כו', וזהו שעובד אדמתו דוקא ישבע לחם מן הארץ (דאד\"ם גימ' מ\"ה<sup data-n=\"7913\">887</sup> מברר לב\"ן<sup data-n=\"7914\">888</sup> שהוא הארץ<sup data-n=\"7915\">889</sup> ע\"כ נק' אד\"ם ע\"ש האדמ\"ה<sup data-n=\"7916\">890</sup> שלוקח ממנה, ולכך אדם שעובד אדמתו ביותר בתיקונה ביגיעה ועמל מלאכה דוקא ישבע ממנה לחם כנ\"ל וד\"ל). וזהו שבברכת הארץ דוקא או' ובכל עת ובכל שעה לפי שברכה זו דארץ דמפקא מזון מתחדש מאין ליש בכל רגע כו' (משא\"כ בשפע ברכה בראש שנמשך מלמעלה בר\"ה ומתחלק לזמנים בימים זהו בלתי חידוש מאין ליש אלא כמו שנמשך למעלה ברוחניות החסד כן זן ומפרנס כו', ובהגיע למטה תלוי בעיתים וזמנים דחו\"ג ויוכל להשתנות, וגם באמצעית העדר הכלי דלית ברכתא דשריא באתר ריקניא<sup data-n=\"7917\">891</sup> כו'. אבל הכל<sup data-n=\"7918\">892</sup> מלמטה למעלה ביגיעה ועמל מלאכה בארץ, וכן בפיזור נפשו ומאודו במסחור יש כלי שיתחדש בזה מאין ליש ממש למעלה מן המדה הקצובה לו בר\"ה, ע\"כ או' בכל עת כו' שנידון בכל רגע כנ\"ל וד\"ל). ולכך אמר הרוצה להתעשר ירבה בסחורה<sup data-n=\"7919\">893</sup> הכוונה בכמה מיני מסחור בכמה זמנים שיחדש מחדש עסקים אחרים ולא רק בעסק א' שנמשך לזמן רב כו', כי בכל החלק מן המין שעושה בו מסחור בארץ יש בו חידוש השפע מאין ממש למעלה מן הטבע כו'). והנה עכ\"פ מובן מכ\"ז במ\"ש בזיעת אפך תאכל לחם דאע\"פ שנאמר לאדם בדרך קללה כנ\"ל, אבל בזאת דוקא תהי' הברכה בארץ כשיעבוד אדמתו ביגיעה ועמל עד שיזיע אפו מעול הכבד כו' לפי שבזאת דוקא יבא השפע וברכה בארץ מלמטה למעלה בבחי' [או\"ח] שהוא",[["7911","885","<b>כדי שהלוך</b>: שם: כמו הלוך."],["7912","886","<b>שהלוך ילך ובכה</b>: תהלים קכו, ו."],["7913","887","<b>דאד\"ם גימ' מ\"ה</b>: נסמן לעיל בפ' משפטים רפא, ד."],["7914","888","<b>מ\"ה מברר לב\"ן</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["7915","889","<b>לב\"ן שהוא הארץ</b>: ראה גם לעיל פ' בשלח קעה, ב. וש\"נ."],["7916","890","<b>אד\"ם ע\"ש האדמ\"ה</b>: ב\"ר פי\"ז, ד."],["7917","891","<b>דלית ברכתא דשריא באתר ריקניא</b>: ראה זהר לך פח, א. יתרו פז, ב. ראה גם שע\"ת סה, ג ואילך ובהערה 25."],["7918","892","<b>הכל</b>: טזיז: בתיקון הכלי."],["7919","893","<b>הרוצה להתעשר ירבה בסחורה</b>: ראה נדה ע, ב. יל\"ש משלי ב, ו (רמז תתקלב). ראה גם ד\"ח בהקדמה ב, ב."]]],[2300550793,"בחידוש יש מאין דוקא. וא\"כ יובן שענין הטרדא בעסק הפרנסה בחשק הלב מאד ובתחבולות שונות שאינו נק' יגיעה ועמל כלל כנ\"ל הרי לא בזה ישכון האור ושפע וברכה במעשה ידיו בכל עסקיו וכמ\"ש כי לא לחכמים לחם<sup data-n=\"7920\">894</sup> דקאי בלחם מן הארץ שעובד אדמתו דוקא בעבודה ויגיעה בכפ[י]ו לבד שלא בפנימי' השכל ומדות כלל וכלל כנ\"ל וד\"ל (ומ\"ש והחכ' תחי' בעליה היינו בכלי אומנות ביגיעה ועמל מלאכה שהיא החכ' שתחי' בעליה דחכמה בחידוש יש מאין שלא הי' מגיע לזה בעצם החכמה שבו כנ\"ל במשל הבן החכם ושלם ששלחו אביו ללמוד אומנות כו').\n<b>והנה</b> עד\"ז ממש יובן במלאכה ועבודה האלקי' הרוחניות כמו במעשה המצות ובצדקה ובעבודה שבלב <span data-k=\"pg\">1244</span> ּ ומוח בתפלה [ב]כל ימי החול שצריך להיות ביגיעה רבה ועמל הנפש ביותר כמו עובד במלאכה, שזהו רק עפ\"י עמ\"ש בלבד שמקבל עליו לעשות רצון קונו אף שתכבד עליו העבודה הזאת להיות שאין בה נח\"ר ועונג לעצמו כלל רק מחמת עומ\"ש ביראה ופחד אלקי' להיות סומ\"ר וע\"ט כל היום, מ\"מ בזה דוקא ישכון אור הברכה הרוחני' בתוס' אור רב בש' הוי' ואלקי' והן כל היח\"ע שנעשי' באו\"כ באצי' ע\"י הבירורי' של מעשה המצות בעומ\"ש שזהו לברר בעה\"ד טו\"ר בין טו\"ט, ובפרט בעבודה שבלב בתפלה לבער הרע שבקרבו בתשו' בלב נשבר וע\"י יגיעה במוח ולב בק\"ש בשמע ישראל ואהבת בכל לבבך בשני יצריך<sup data-n=\"7921\">895</sup>. וגם כל היום בטרדתו בפרנסתו יהי' נושא ונותן באמונה ויבטח על ה' שישלח ברכה בעסקיו ולא יבטח בהתאמצות כחו ועוצם ידו בתחבולות בדרך הטבע כנ\"ל כי לה' הארץ ומלואה<sup data-n=\"7922\">896</sup> כו', ומה גם בהפרשה מכל יגיעו לצדקה לעניים להחיות רוח שפלים<sup data-n=\"7923\">897</sup> ביותר מכפי טבעו ורגילותו דוקא רק מצד עומ\"ש שנדבה לבו לעשות רצון קונו כו' כנ\"ל. וכ\"ז נק' בירורים דרפ\"ח כו' לברר בין טו\"ר ולהפוך חשך לאור ומרע לטוב בתו\"מ ותפלה ותשובה וצדקה הכל בעמל ויגיעה בעומ\"ש לבד שנק' עובד אלקי' כנ\"ל, וע\"ז אמר יגיע כפיך<sup data-n=\"7924\">898</sup> כי תאכל אשריך וטוב לב אשריך בעוה\"ז וטוב לך<sup data-n=\"7925\">899</sup> לעוה\"ב<sup data-n=\"7926\">900</sup> בין ביגיע כפיו בפרנסתו שאינו רק ביגיעה בלא פנימי' השכל ומדות<sup data-n=\"7927\">901</sup> כנ\"ל ובין ברוחניות בעבודה האלקי' בתומ\"צ בעומ\"ש שנק' יגיעה ועמל כנ\"ל שאוכל פירותיהן בעוה\"ז והקרן כו' וד\"ל.\n[יח]<b> והנה</b> בכ\"ז יובן מ\"ש ו' ימים תעשה מלאכה תיעשה מעצמה ומאליה כו' כנ\"ל, שזהו ענין היגיעה",[["7920","894","<b>כי לא לחכמים לחם</b>: קהלת ט, יא [בדילוג — ראה הנסמן לעיל פ' שמות ב, א]."],["7921","895","<b>ואהבת בכל לבבך בשני יצריך</b>: נסמן לעיל פ' יתרו רנד, ב."],["7922","896","<b>לה' הארץ ומלואה</b>: תהלים כד, א."],["7923","897","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["7924","898","<b>יגיע כפיך כי תאכל</b>: תהלים קכח, ב."],["7925","899","<b>אשריך בעוה\"ז וטוב לך לעוה\"ב </b>[טז: בעוה\"ב]: אבות פ\"ד, מ\"א [ובשנויי נוסחאות שם]. ראה גם לעיל פ' שמות ב, א. וש\"נ."],["7926","900","<b>בעוה\"ב</b>: ע\"כ נמצא בתרס\"ו — ראה לעיל הערה 867."],["7927","901","<b>ומדות</b>: יז: ומדו\"מ."]]],[2300550794,"הגשמי' בפרנסה מבלי ישים בזה פנימי' שכלו ומדותיו כלל שכל מלאכה הנעשית בלי רצון ודעת תכבד עבודה זו ונק' עמל נפש וקשה מאד לגוף. וז\"ש בזיעת אפך כו' כנ\"ל [ש]הוא רק ביגיע כפיו לבד בלא פנימי' הרצון ומדות כלל והיינו כאלו המלאכה נעשית מעצמה ומאליה מאחר שאין פנימי' רצונו ושכלו ומדותיו בה כלל ואז ישכון בזה דוקא אור ושפע האלקי' כנ\"ל, וגם מה שיעלה בחי' הטוב מכל יגיעה ועמל שלו למעלה בכל אשר יעשה צדקה וגמ\"ח כו' וכה\"ג. וכמ\"כ מה שיהי' מזה מעלה נפשו הטבעיות בעבודה שבלב ומוח בתפלה וק\"ש כנ\"ל, וכמו\"כ בעבודה אלקי' ביגיעת הנפש בעומ\"ש כל היום בסומ\"ר וע\"ט יעלה למעלה ביתרון אור מצד היפוך החושך לאור שיש מזה עונג גדול יותר למעלה כנ\"ל. וז\"ש ו' ימים שהן ו' ימי המעשה שהוא זמן העבודה בעמל ויגיע כפיו בגשמיות וברוחניות תיעשה מלאכה מעצמה מאליו<sup data-n=\"7928\">902</sup> כו' וכנ\"ל וד\"ל, אבל ביום הז' [קודש] יהי' לכם כו' דהנה כל העלאות מבירורים דימות החול עולי' בשבת שנק' קד\"ש כנ\"ל. וזהו גם ע\"ד הפשוט שכאשר לא ישים עומק לבו ודעתו במו\"מ ועבודה בחול רק ביגיע כפיו לבד וישל[י]ך על ה' יהבו באמונה ובטחון כנ\"ל, אזי ודאי שכלו ומדותיו ומחשבתו פנויי' מן הטרדא <span data-k=\"pg\">תרכב</span> ּ ויכול לקבל קדושת השבת בעונג ושמחה בשכל ומדות פנויי' במנוחה שלימה כמו שבחי' שבת הוא למעלה שנק' קד\"ש מלה בגרמי'<sup data-n=\"7929\">903</sup> שהוא קדוש ומובדל מן העולמות כו' ונק' קדוש הוי' מכובד<sup data-n=\"7930\">904</sup> כו', משא\"כ מי שטרוד בכל עומק רצונו ולבו ושכלו במו\"מ כל ימי החול לא יוכל לקבל בחי' קד\"ש דשבת במנוחה שלימה להתענג על ה' בתפלה דשבת כו'. ומה גם כי לא יעלה למעלה כלל מכל אשר נשא נפשו בחשק נמרץ לתאוותו להשיג הון כו' שלא יבורר בעבודתו בחי' הטוב מן הרע כלל, ואם אין העלא' ובירור בחול אין עונג ומנוחה בקדש דשבת כי הא בהא תליא כידוע כמו מי שטרח בע\"ש<sup data-n=\"7931\">905</sup> כו', ולכך תיעשה מלאכה מעצמה כו'.\n<b>וכך</b> הוא גם בכל יום ויום בעבודתו בעסקיו שיעלה מכל עבודתו למעלה בכל ק\"ש ותפלה שבכל יום, כידוע דבכל יום בק\"ש<sup data-n=\"7932\">*906</sup> ותפלה יש מעין הארת אור דקדש דשבת<sup data-n=\"7933\">906</sup> וכל היחו\"ע דק\"ש והעלאת מ\"ן דתפלה דחול עולים בשבת<sup data-n=\"7934\">907</sup> בבחי' בירור אחר בירור כו', לפי שכמו שכל ו' ימי המעשה הן הכנה לשבת שאם אין מלאכה ויגיעה בוי\"מ החול אין מנוחה וקדושה בשבת דהא בהא תליא, וא\"כ גם בכל יום ויום בפרט יש בו מבחי' מנוחה וקדושה דשבת בשביתה ומנוחה מאותו יום שיהי' עולה",[["7928","902","<b>מאליו</b>: טזיז: ומאלי'."],["7929","903","<b>שבת. . קד\"ש מלה בגרמי'</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ."],["7930","904","<b>קדוש הוי' מכובד</b>: ראה ישעי' נח, יג. לעיל פ' בשלח קסא, ד. וש\"נ."],["7931","905","<b>מי שטרח בע\"ש</b>: ע\"ז ג, א."],["7932","*906","<b>דבכל יום בק\"ש. . הארת. . דקדש דשבת</b>: ראה לקמן תלו, ד."],["7933","906","<b>דבכל יום. . ותפלה. . הארת. . דשבת</b>: ראה מאמרי אדה\"ז תקס\"ב כאן ע' שסו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670204\" data-slug=\"torat-chaim\" data-id=\"2300670204\">תו\"ח נח סא, ג</a> ובהערה 29. לקמן ד\"ה ונמצא מובן."],["7934","907","<b>דתפלה דחול עולים בשבת</b>: ראה גם פרדס (שער אבי\"ע) שט\"ז, פ\"ה. לקמן תלז, ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370041\" data-slug=\"torah-or\" data-id=\"3901370041\">תו\"א נח י, א</a>. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ."]]],[2300550795,"בשבת. והיינו ענין הק\"ש והתפלה דכל יום שבהן עולה כל מה שעשה ועבד כל היום בעמל ויגיעה ופיזור הנפש ומה שיעלה מזה בחי' הטוב בכח העבודה שבלב ומוח בק\"ש כנ\"ל, וגם בלב נשבר קודם התפלה מן טרדת הפרנסה שתקצר רוחו ונפשו האלקי' כו' כ\"ז עולה מלמטה למעלה בבחי' או\"ח כח<sup data-n=\"7935\">908</sup> המנוחה דשבת מימות החול שזהו מנוחה פרטיות, ויכול לקבל קדש פרטי בק\"ש ותפלה כמו בעונג בקדש העליון דשבת ממש וכל העלאות דק\"ש ותפלות דכל יום מימות החול עולי' בקדושה דשבת כנ\"ל. וזהו שגם בחיצוני' נראה בעמדו בתפלה כמו שהוא בבחי' קדש דשבת כאלו הוא למעלה מובדל מכל מלאכה ועסק, והוא מה שהוא עטוף בטו\"ת כל שעת התפלה, ואסור להפסיק בדבור<sup data-n=\"7936\">909</sup> מב\"ש עד אחר התפלה<sup data-n=\"7937\">910</sup> כאלו הוא קדוש ומובדל מכל עניני עולם ולא יכול להשפיל א\"ע לדבר דברי חול להיות[ו] מוגבה ונעלה למעלה מעלה בעולם הנשמות, כמו עלי' העולמות והנשמות בכל שבת<sup data-n=\"7938\">911</sup> מהיכל להיכל העליון (כמ\"ש בפע\"ח בשער התפלה וק\"ש<sup data-n=\"7939\">912</sup> ). וגם שמחמת טרדתו ביום שעבר בכל עסקיו שתכבד עליו העבודה בעומ\"ש בסומ\"ר להיות נקי כפים במו\"מ וע\"ט ביתר ממדותיו וטבעו בעמדו להתפלל יכאב לו<sup data-n=\"7940\">913</sup> ויהי' בכובד ראש קודם התפלה כנ\"ל, מ\"מ בזאת תתנחם נפשו במעט קרבת אלקי' בפסוד\"ז עד ק\"ש במה שיתבונן ביחו\"ע בשמע ישראל רק<sup data-n=\"7941\">914</sup> הוי' אחד והיינו בפנימי' ההשגה בעומק בינה שבלב ומוח ובאהבה ורצון פנימי' בעומק הלב בפסוק ואהבת כו', שזהו כמו תפלה דשבת וקדושה דשבת כי שובת הוא במנוחה בכל שעת התפלה ועטוף בטו\"ת בלי דיבור דחול וכמו שהוא בחיצוני' כך הוא גם בפנימי' בק\"ש שמכוין לבו לה' אחד בפנימי' השכל והלב להתענג בענג העליון העצמי' כמו בשבת ממש מטעם הנ\"ל <span data-k=\"pg\">1246</span> ּ וד\"ל.\n<b>ונמצא</b> מובן דאע\"פ שמהות העבודה דחול הוא ביגיעה ועמל בעול כו' היפוך עבודת הקדש כמו בתפלה דשבת וסעודו' השבת, אבל בתפלה דחול אע\"פ שא' בזהר שנק' שעת קרבא<sup data-n=\"7942\">916</sup> לבא ביגיעה למלחמה לבער הרע שבקרבו כנ\"ל מ\"מ בבחי' הפנימי' העולה מזה היינו כמו בתפלה דשבת<sup data-n=\"7943\">915</sup> שהוא להתענג באה\"ר בקדש העליון בסוכ\"ע כו' בכל נפשו כנ\"ל, לפי שבכ[ל] י[ום] בתפלה יש מהארת השבת כו' (וגם במצות ת\"ת יש הפרש בין חול לשבת לפי טעם הנ\"ל בענין הבירורי' דרפ\"ח כו' שנק' עמל, זהו עמל תורה שלומד בפלפול ועיון ביגיעת המוח והגיון הלב בתשבע\"פ במשנה ותלמוד [לברר] וללבן הלכתא כו' עד מיצוי הנפש<sup data-n=\"7944\">917</sup> כמו שממית עצמו עלי'<sup data-n=\"7945\">918</sup> כו' עד שידע דין",[["7935","908","<b>כח</b>: טזיז: כמו."],["7936","909","<b>בדבור</b>: טז: ליתא. יז: בתפלה בדבור."],["7937","910","<b>ואסור להפסיק. . מב\"ש עד אחר התפלה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"א, ס\"ד."],["7938","911","<b>עלי' העולמות. . שבת</b>: ראה גם לעיל פ' בא קכז, א הערה 667."],["7939","912","<b>כמ\"ש בפע\"ח בשער התפלה וק\"ש</b>: ראה גם מאמרי אדה\"ז תקס\"ב כאן ע' שסו."],["7940","913","<b>יכאב לו</b>: טזיז: מכאב לבו."],["7941","914","<b>רק</b>: שם: כו'."],["7942","916","<b>בתפלה דחול. . בזהר. . שעת קרבא</b>: ראה זהר (רע\"מ) פינחס רמג, א. ויחי רמ, ב. ת\"ז תי\"ג (כט, ב). מאמרי אדה\"א ויקרא ח\"א ע' תכח. וש\"נ. שמות ח\"א ע' קפ. וש\"נ."],["7943","915","<b>וסעודו' השבת. . דשבת</b>: טז: ליתא. וכנראה נשמט מפני תיבות הדומות: בתפלה דשבת. . בתפלה דשבת."],["7944","917","<b>עד מיצוי הנפש</b>: לשון הספרי ואתחנן ו, ה. ראה גם מ\"מ הגהות והע\"ק לסש\"ב פ\"ל."],["7945","918","<b>שממית עצמו עלי'</b>: שבת פג, סע\"ב."]]],[2300550796,"אמת לאמיתו ברור מכל סיג כו', ויש בזה חידוש מי\"ש לאי\"ן ממש עד אין שיעור כלל כנ\"ל, וזהו שא' [אשרי מי שעמלו] בתורה<sup data-n=\"7946\">919</sup> עמל [תורה] דוקא. וגם אמרו דכל תורה שאין עמה מלאכה<sup data-n=\"7947\">920</sup> דוקא שהוא טורח היגיעה ועמל מלאכה בד\"א ומו\"מ סופה בטילה, ואמר טוב תורה עם ד\"א<sup data-n=\"7948\">921</sup> לפי שיגיעת שניהם דוקא משכחת עון [וחטא כו' וע\"כ] צריך לחבר ולשתף יגיעה ועמל דד\"א בעסק טרדת פרנסה שבנפשו ויגיעו יביא לחמו עם יגיעה דעמל תורה דוקא שבצירוף שניהם יגיעות יחד<sup data-n=\"7949\">922</sup> דוקא משכחת עון, לפי שענין א'<sup data-n=\"7950\">923</sup> הוא ממש שהוא ענין הבירורי' דרפ\"ח כו' לברר הטוב מן הרע בתכלית ולהוציא ולבער כל הרע מן הטוב בתכלית וכמו החרישה וזריעה וכל עבודה בשדה לתקנה שנק' עוב\"ד אדמתו שישבע לחם כו'. אך בחכמה דתשבע\"פ מתברר ועולה הטוב מן הרע ביגיעה ועמל דתורה דוקא באמרו זה כשר וזה פסול (כמשי\"ת), וביגיעה ועמל דמלאכה במו\"מ נברר ונתעלה כל בחי' הטוב מרע כנ\"ל, ולכך א' דכל תורה שאין עמה מלאכה בד\"א סופה בטילה לפי שאין תורה זו מבררת כלום בפ\"מ בבחי' פיזור נפשו בק\"נ, אך עם מלאכה וד\"א נתברר [בכי טוב וזהו] שיגיעת שניהם [דוקא] משכחת עון כו' (כמשי\"ת) (אבל בשבת הרי בורר אסור<sup data-n=\"7951\">924</sup>, ולכך גם ברוחני' בשבת שזהו במוגבה ונעלה למעלה בעולם הנשמות בג\"ע וכה\"ג שאין שם בירור בטו\"ר כשר פסול כו' רק סודות התורה לומדים בשבת<sup data-n=\"7952\">925</sup> כמו בזהר ובס' הקבלה כו' ולא ביגיעה ועמל בפלפול ולכך ה[יו] דורשים בשבתא בהלכות פשוטות<sup data-n=\"7953\">926</sup> כו' כמו שאין ד\"א ועובדין דחול בשבת אפי' בדבור כמ\"ש ממצוא חפצך ודבר דבר<sup data-n=\"7954\">927</sup> כידוע כמו שתפלה וסעודת השבת בבחי' קד\"ש העליון כנ\"ל).\n<b>והנה</b> מעתה יתורץ כל הנ\"ל במ\"ש אלה הדברים אשר צוה ה' בל' רבים ואח\"כ א' דבר א' שהוא ו' ימים תעשה כו' שזהו מצות השבת דהכוונה הוא בל\"ט מלאכות בעבודה בעול שהוא במ\"ע ול\"ת בסומ\"ר וע\"ט ביגיעה ועמל שציוה ה' לעשות בכל מצוה בקבלת עומ\"ש, הנה נכללו כולם במצוה א' שזהו מצות השבת והוא מ\"ש ו' ימים תיעשה מעצמה כל מלאכה בעבודה האלקי' במצות מעשיות שזהו רק ע\"י קבלת עומ\"ש לבד ולא מכח עצמו מצד איזה כוונה וטעם וסוד, דמצות א\"צ כוונה<sup data-n=\"7955\">928</sup> וטעם <span data-k=\"pg\">תרכג</span> ּ כ\"א לשמוע בקול ה' לעשות רצונו [ב]גזירת המלך לבד כמ\"ש החפץ לה' בעו\"ז<sup data-n=\"7956\">929</sup> כו'<sup data-n=\"7957\">930</sup> כ\"א שמוע מזבח טוב<sup data-n=\"7958\">931</sup> כו'. וזהו אלה הדברים רמ\"ח מ\"ע והיינו בירורי' דרפ\"ח כו' בהבדלה בין",[["7946","919","<b>[אשרי מי שעמלו] בתורה</b>: ראה ברכות יז, א."],["7947","920","<b>דכל תורה שאין עמה מלאכה</b>: אבות פ\"ב, מ\"ב. ראה גם לעיל פ' שמות ד, ב. וש\"נ."],["7948","921","<b>טוב תורה עם ד\"א</b>: ראה אבות שם [ושם — יפה תלמוד תורה — נסמן לעיל פ' שמות ד, ב הערה 184]."],["7949","922","<b>שבצירוף שניהם יגיעות יחד</b>: טז: שבצירוף שני היגיעות יחד. יז: שביגיעת שניהם."],["7950","923","<b>שענין א'</b>: ניתוסף ע\"פ יד."],["7951","924","<b>בשבת הרי בורר אסור</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ט."],["7952","925","<b>סודות התורה לומדים בשבת</b>: ראה גם לעיל פ' בשלח רטו, ד. וש\"נ."],["7953","926","<b>דורשים בשבתא בהלכות פשוטות</b>: ראה גם לעיל פ' בשלח רטז, ד. וש\"נ."],["7954","927","<b>ממצוא חפצך ודבר דבר</b>: ראה גם לעיל פ' יתרו רסו, א. וש\"נ."],["7955","928","<b>דמצות א\"צ כונה</b>: ראה גם לעיל פ' תצוה שלח, ג. וש\"נ."],["7956","929","<b>החפץ לה' בעו\"ז</b>: שמו\"א טו, כב."],["7957","930","<b>כו'</b>: טז: ליתא. יביז: כבפנים."],["7958","931","<b>כ\"א שמוע מזבח טוב</b>: נסמן לעיל פ' בשלח קנו, ד הערה 350. טזיז: כ\"א לשמוע — ראה מאמרי אדה\"א דברים ח\"ג ע' תתקל. יב: כבפנים."]]],[2300550797,"טו\"ר ביגיעה שעולה הבירורי' מכל המצות במצוה דשבת שביום הז' קדש יהי' לכם שלמעלה מבחי' הבירורים דרפ\"ח כו' דבורר אסור בשבת רק מה שהוברר ונתעלה בימות החול הוא שעולה בשבת, והיינו מה שעיקר מצות השבת זהו רק בשב ואל תעשה<sup data-n=\"7959\">932</sup> לבד כו' בבחי' קדש העליון כו' שזהו ביום שכולו שבת ומנוחה לחה\"ע<sup data-n=\"7960\">933</sup> בעוה\"ב שנק' שבת שבתון<sup data-n=\"7961\">934</sup> כו' וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ ענין סמיכת המצוה דשבת למצות מלאכת המשכן שא' קחו מאתכם תרומה לה' כו', דהנה לאחר שצוה על השבת שבו' ימים תעשה מלאכה בקבלת עומ\"ש ובשבת יהי' ההעלא' בקדש העליון הרי עיקר ההעלא' הזאת הוא בשביל הירידה וההמשכה לאורות בכלים בתוס' אור גדול מעונג העליון העצמי' מטעם המבואר למעלה דכל עיקר העלי' בשביל הירידה שזהו שעבמ\"ת בפנימי' כו'. וזהו וקראת לשבת ענג<sup data-n=\"7962\">935</sup> העליון כו' והוא שא' שבת שבתון כו' כל העושה [בו] מלאכה<sup data-n=\"7963\">936</sup> כו' וכנ\"ל [ב]מ\"ש הקים ע\"ל עולה של תו\"מ הקים כמו בהקמת בנין באו\"כ דוקא. וזהו ענין הקמת המשכן שמצוה אח\"ז קחו מאתכם כו' כל נדיב לבו יביאה כו', שנדיבות הלב הזה הוא להביא כל העלאות דבירורי' בכל עבודה קשה [ב]עול כו' להיות בזה עונג ושמחה דוקא בבחי' שו\"ב כו', והוא במה שמקי[י]ם דבר ה' ועושה רצונו בפו\"מ בביטול רצון הטבעי' כו' להמשיך אור בכלי דוקא. וזהו הקים עו\"ל שזהו עיקר הקמת עול העבודה האלקי' ביגיעה ועמל נגד הטבע רק במה שמתבונן בעצמו שזהו נח\"ר ליוצרו וכמ\"ש ולכבודי כו' בגין דישתמודעי' לי' למטה דוקא על [ידי] קבלת עומ\"ש למעשה<sup data-n=\"7964\">*937</sup> דוקא שזהו שעלה במח\"ת כנ\"ל. ע\"כ זאת נחמתו בעניו כמ\"ש זאת נחמת\"י בעניי<sup data-n=\"7965\">937</sup> פי' בזאת תתנחם נפשי בעניי והוא בבחי' מל' שמים דלעילא שנק' זאת<sup data-n=\"7966\">938</sup> כמ\"ש בזהר עמ\"ש בזאת יבא אהרן<sup data-n=\"7967\">939</sup> כו' שהוא בקבלת עומ\"ש לעשות נח\"ר ליוצרו לבד, והיינו כאשר מתבונן במדת מלכותו ית' הפנימי' ועצמות דמל' דא\"ס עצמו כמו שהוא מלך מרומם<sup data-n=\"7968\">940</sup> יחיד לבדו מאז כו' מתנשא בערך ממל[ך] על עולמות, רק במה שיש לו נח\"ר ועונג במדת מלכותו זאת בתו\"מ שיקבלו עליהם עול תו\"מ כנ\"ל שלזה ירד כל העונג הפנימי' ועצמיות שבפנימי' המל'. וכשמתבונן בעצמו שזאת העבודה האלקי' הנעשי' בעומ\"ש בלבד כנ\"ל נח\"ר לפניו דוקא מטעם הנ\"ל אז תתנחם נפשו בזאת אעפ\"י שתכבד עליו עול העבודה והיגיעה, דהיינו שתבא בלבו שמחה ועונג גדול ונחמה בעצמו מכל יגיעתו ועבודתו במה שיתבונן בבחי' זא\"ת דהיינו בחי'",[["7959","932","<b>מצות השבת. . בשב ואל תעשה</b>: ראה שע\"ת צז, א ובהנסמן לשם."],["7960","933","<b>ביום שכולו שבת ומנוחה לחה\"ע</b>: סוף תמיד."],["7961","934","<b>בעוה\"ב שנק' שבת שבתון</b>: ראה גם עט\"ר ע' טו."],["7962","935","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["7963","936","<b>שבת שבתון. מלאכה</b>: ויקהל לה, ב."],["7964","*937","<b>למעשה</b>: יביז: למעלה."],["7965","937","<b>זאת נחמת\"י בעניי</b>: תהלים קיט, נ."],["7966","938","<b>מל'. . שנק' זאת</b>: ראה גם שה\"א לה, א ובהערה 10."],["7967","939","<b>מל'. . בזאת יבא אהרן</b>: ראה גם לעיל פ' בא צא, ב. וש\"נ."],["7968","940","<b>דמל' דא\"ס. . מלך מרומם</b>: ע\"פ ברכת יוצר. ראה גם לעיל פ' בא צ, א. וש\"נ."]]],[2300550798,"פנימי' המל'. והיינו דוקא בעני[י] כאשר הוא בעוני מן הדעת<sup data-n=\"7969\">941</sup> זו<sup data-n=\"7970\">942</sup> שאין לו במעשה העבודה טעם ודעת רק המעשה לבד לצאת י\"ח ולעשות נח\"ר ליוצרו שזהו שנק' לחם עוני הבא ביגיעה בזיעת אפו וביגיע כפיו לבד, שבנפשו יביא לחמ\"ו שהוא לחם דתו\"מ להחיות נפשו <span data-k=\"pg\">1248</span> ּ לבד כעני שמסתפק בלחם צר רק להחיות נפשו שבא ע\"י עמל ויגיעה כנ\"ל, וז\"ש כי אמרת\"ך חייתנ\"י אמרת\"ך דתו'<sup data-n=\"7971\">943</sup> חייתני כלחם עני ממש וד\"ל.\n<b>אך</b> הנה עדיין י\"ל מ\"ש זאת נחמתי כו' שהוא בחי' קבלת מ\"ש ב[עול דוקא להיות מזה דוקא ה]עונג ורצון ונח\"ר ליוצרו כנ\"ל ואח\"כ א' כי אמרת\"ך חייתני שזהו ע\"י אותיות התורה שנק' אמרתך והוא שנק' לחם עני כנ\"ל, אך גם התו' נק' זא\"ת והוא תושבע\"פ<sup data-n=\"7972\">944</sup> שא' עלי' זאת הפעם עצם כו' לזאת יקרא אשה כי מאיש לוקחה זאת<sup data-n=\"7973\">945</sup> דהיינו תושב\"כ<sup data-n=\"7974\">946</sup> כו' דתשבע\"פ מל' קרינן לה<sup data-n=\"7975\">947</sup>, וז\"ש כי אמרתך חייתני כו', והוא מ\"ש כאן אלה הדברים כו' אל\"ה ל' רבים שהן ששה מדות שבמל' תושבע\"פ כלולי' כל א' מששה עולה מספר ל\"ו<sup data-n=\"7976\">948</sup> שהוא אל\"ה והן שס\"מ<sup data-n=\"7977\">949</sup> דוקא וכשנחלקים כל א' ליו\"ד הן ס' מלכות ס' מסכתות<sup data-n=\"7978\">950</sup> כידוע. ובתחלה או' ויקהל משה את כל עדת בנ\"י שזהו במקור ושרש דס\"ר נש\"י שכלולי' באותיות דתושב\"כ<sup data-n=\"7979\">951</sup> שנק' חכ' בראש כידוע ומשה הוא בחי' הד\"ע<sup data-n=\"7980\">952</sup> [כ]נ\"ל שהקהיל לכל עדת כו' בשרשם בח\"ע דתשב\"כ, ואח\"כ א' אלה הדברים אשר צוה ה' בתשבע\"פ בחכ' שבדבור בע\"פ דוקא כמ\"ש תורה צוה לנו משה כו' שזהו לעשות אותם בפ\"מ דוקא כדבר מלך שלטון<sup data-n=\"7981\">953</sup> שבא לקיום מיד במעשה בכל פרט כו'. וגם פי' לעשות אות\"ם לתקן אותם כמ\"ש אשר ברא אלקי' לעשות לתקן<sup data-n=\"7982\">954</sup> כו' ד[ב]חכ' תתאה דתשבע\"פ דוקא אתברירו לתקן רפ\"ח כו' שיהי' מזה הקמת הבנין באו\"כ לבלי יקרב זר לקבל שפע חיצוני' (כמשי\"ת). וזהו זא\"ת נחמתי זאת דתשבע\"פ דוקא נחמתי בעניי בלחם עוני בעמל תורה ויגיעה לברר ולהבדיל בין טו\"ר בפו\"מ כי אמרת\"ך חייתני כמו מזון דלחם עני להחיות נפשו ביגיע כפיו שלזאת נשא את נפשו כנ\"ל וד\"ל.",[["7969","941","<b>בעוני מן הדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["7970","942","<b>זו</b>: טזיז: ליתא."],["7971","943","<b>כי אמרת\"ך. . דתו'</b>: המשך הכתוב זאת נחמתי. ראה גם לעיל פ' בשלח רלז, ב. לקמן תמ, ד. מאמרי אדה\"א שמות ח\"א ע' קעא. וש\"נ. הנחות תקע\"ז ע' קפו. ע' רטז. ע' רנב. ע' שכא."],["7972","944","<b>התו' נק' זא\"ת והוא תושבע\"פ</b>: ראה ס' ערכי הכנויים — לבעל סדר הדורות — מערכת זאת ערך תורה בשם מגלה עמוקות אופן פט, ומערכת זה ערך תורה בשם הנ\"ל אופן כט. ולפנינו לא נמצא בשניהם."],["7973","945","<b>תושבע\"פ. . זאת הפעם. . לוקחה זאת</b>: בראשית ב, כג. ראה גם לעיל פ' בא צו, ג. מאמרי אדה\"א במדבר ח\"ג ע' תתקעה."],["7974","946","<b>מאיש. . תושב\"כ</b>: ראה גם ס' עה\"כ — לבעל סדר הדורות — מערכת איש ערך תורה."],["7975","947","<b>דתשבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["7976","948","<b>אל\"ה. . ששה מדות. . מספר ל\"ו</b>: ראה לקמן בפ' פקודי תמח, ג. הנסמן לעיל בפ' משפטים רצא, ד הערה 268."],["7977","949","<b>שס\"מ</b>: טזיז: ששה סדרי משנה. — ראה לעיל שצ, א הערה 185."],["7978","950","<b>ס' מלכות ס' מסכתות</b>: שה\"ש ו, ח. ראה גם לעיל פ' שמות ג, א הערה 118."],["7979","951","<b>דס\"ר נש\"י. . דתושב\"כ</b>: ראה גם של\"ה מס' פסחים מצה עשירה קסג, ב. קסה, ב. לעיל פ' שמות ב, ד ובהערה 113."],["7980","952","<b>הד\"ע</b>: טזיז: הדעת."],["7981","953","<b>כדבר מלך שלטון</b>: ע\"פ קהלת ח, ד."],["7982","954","<b>אשר ברא אלקי' לעשות לתקן</b>: נסמן לעיל פ' יתרו רסו, ג."]]],[2300550799,"<b>וביאור</b> הענין בדרך כלל הנה ידוע ההפרש בכלל בין תושב\"כ לתשבע\"פ<sup data-n=\"7983\">955</sup> שא' בהן לכו לחמ\"ו בלחמ\"י<sup data-n=\"7984\">956</sup> כו' שהן ב' מיני לחם דתשב\"כ נק' לחם מן השמים<sup data-n=\"7985\">957</sup> כמו שניתנה מן השמים במ\"ת וכמ\"ש האזינו השמים ואדברה<sup data-n=\"7986\">958</sup> כו'. והוא מה שיורד אור הח\"ע העצמו' דא\"ס בחכ' דתשב\"כ בצירופי אותיות עצמיי' כמו שא' דקורא בתורה כקורא בשמותיו ממש, ולכך האותיות דתשב\"כ בדקדוק קרי וכתיב כו' וכמו ואתא מרבבות קדש העליון מבחי' אותיות דתוה\"ק שהיתה אצלו שעשועי' כו' וכמ\"ש אז ראה ויספר\"ה הכינה וגם חקרה באותיות כ[מו] משה שהי' מחוקק וסופר כו' כידוע, וזהו שנק' לחם העליון שיורד מן השמים כמו שהוא בלא תיקון ובלא יגיעה ועמל כלל כמו שירד המן מן השמים קודם המשכת אור דתורה הנק' לחם מן השמים כמ\"ש הנני ממטיר לחם מן השמים<sup data-n=\"7987\">959</sup> כו' למען אנסנו הילך כו'<sup data-n=\"7988\">960</sup> ונק' מזונא דחכמתא<sup data-n=\"7989\">961</sup> כמ\"ש בזהר והיינו מזונא דח\"ע דתוה\"ק כו', וכמו לחם הפנים שהי' במקדש שכולו בחי' פנימי'<sup data-n=\"7990\">962</sup> בלי שום חיצוני' ואחוריי' כלל (וכמו שהמן נבלע ברמ\"ח אברי'<sup data-n=\"7991\">963</sup> בלי פסולת כלל). וזהו שא' גבי מן שהוא מזון העליון הרוחני שלמעלה מעה\"ד טו\"ר כו' ויענך וירעיבך<sup data-n=\"7992\">964</sup> ויאכילך כו' כי לא על הלחם לבדו יחי' האדם כי על כל <span data-k=\"pg\">תרכד</span> ּ מוצא פי הוי' דוקא יחי' האדם שזהו אותיות דתשב\"כ שבקריאה בכתב שנק' מוצא פי הוי' דוקא וד\"ל. אך לחם הב' דחכ' דתורה זהו חכ' דתושבע\"פ במשנה ותלמוד שנק' לחם מן הארץ<sup data-n=\"7993\">965</sup> כמו הלחם שמוציא מן הארץ שבא ע\"י תיקון מלאכה ועבודה רבה בחרישה וזריעה כו' עד שנעשה לחם אפוי למאכל אדם [להחיותו]. וז\"ש כי אמרתך חייתנ\"י חיות דלחם דתושבע\"פ שבא אחר כמה בירורי' בל\"ט מלאכות כו' ביגיעה ועמל תורה עד שנעשה חידוש דין והלכה למעשה בדרך פרט, וצריך לברר וללבן היטב בגירסא בל\"ב<sup data-n=\"7994\">966</sup> שיניים<sup data-n=\"7995\">967</sup> טוחנות<sup data-n=\"7996\">968</sup> כו' כידוע עד שנעשה מזון לנשמה ממש וכמ\"ש ותורת\"ך בתוך מעי<sup data-n=\"7997\">969</sup> ממש. וע\"ז א' בזיעת אפ\"ך תאכל לחם דתשבע\"פ<sup data-n=\"7998\">970</sup>, משא\"כ לחם מן השמים דתשב\"כ שבא מלמעלה בלי עמל ויגיעה כלל כנ\"ל וד\"ל.",[["7983","955","<b>ההפרש. . לתשבע\"פ</b>: מכאן ועד לקמן תיז, א (על יד ציון 225) הועתק בשינויים והוספות בהמשך תרס\"ו ע' שפד ואילך."],["7984","956","<b>תושב\"כ לתשבע\"פ. . לכו לחמ\"ו בלחמ\"י</b>: משלי ט, ה. ראה השמטות לזח\"א רס, א."],["7985","957","<b>דתשב\"כ נק' לחם מן השמים</b>: ראה גם לעיל פ' שמות ב, ד. וש\"נ."],["7986","958","<b>וכמ\"ש האזינו השמים ואדברה</b>: האזינו לב, א. ראה גם מאמרי אדה\"א במדבר ח\"ב ר\"ע תקצח — בהמשך תרס\"ו כאן לא הועתק."],["7987","959","<b>הנני ממטיר </b>[טז ניתוסף: לכם]<b> לחם מן השמים </b>[יז: ב' תיבות האחרונות ליתא]: בשלח טז, ד."],["7988","960","<b>כו'</b>: טז: בתורתי."],["7989","961","<b>מזונא דחכמתא</b>: ראה זהר בשלח סב, א לעיל פ' בשלח רי, ג."],["7990","962","<b>לחם הפנים. . שכולו בחי' פנימי'</b>: ראה מנחות צו, א. לעיל פ' בא קכז, ב הערה 679."],["7991","963","<b>שהמן נבלע ברמ\"ח אברי'</b>: יומא עה, ב. ראה גם לעיל פ' בשלח רטז, ג."],["7992","964","<b>ויענך וירעיבך</b>: עקב ח, ג."],["7993","965","<b>דתושבע\"פ. . לחם מן הארץ</b>: ראה גם לעיל פ' שמות ב, ד ובהערה 108."],["7994","966","<b>לברר וללבן היטב. . טוחנות</b>: ראה גם מאמרי אדה\"א בראשית ס\"ע תפד ואילך. וש\"נ. שמות ח\"א ע' קמה, לעיל פ' בא קכה, א. לקמן תיט, ג. תלד, א. תמ, ד."],["7995","967","<b>בל\"ב שיניים</b>: ראה גם לעיל פ' שמות טו, ג ובהערה 665."],["7996","968","<b>שיניים טוחנות</b>: ראה זהר (רע\"מ) נשא קכא, ב. שבת קנב, א."],["7997","969","<b>ותורת\"ך בתוך מעי</b>: תהלים מ, ט."],["7998","970","<b>בזיעת אפ\"ך תאכל לחם דתשבע\"פ</b>: ראה גם לעיל פ' שמות ד, ב."]]],[2300550800,"[יט]<b> ולהבין</b> ביאור כ\"ז בדרך פרט, ומהו ההפרש בין מזון העליון דח\"ע דתשב\"כ למזון דתשבע\"פ שהרי שניהם נק' לחם כמ\"ש לכו לחמ\"ו בלחמ\"י כו' שהוא מזון לנשמה בכלל כלחם לבב אנוש<sup data-n=\"7999\">971</sup> כו'. אך הנה ארז\"ל ע\"פ כ\"א בתורת הוי' חפצו<sup data-n=\"8000\">973</sup> כו' מעיקרא עביד אינש אדעתא דנפשי'<sup data-n=\"8001\">974</sup> כמו שא' ר\"ש חדאי נפשאי<sup data-n=\"8002\">975</sup> לך קראי כו' ואח\"כ ובתורתו יהגה נק' ע\"ש<sup data-n=\"8003\">976</sup> ובתורתו<sup data-n=\"8004\">972</sup> שממשיך אוא\"ס בתורה להוסיף שלימות האמיתי בחכ' דתורה, וזהו שנק' עוסק בתורה לשמ\"ה דוקא לשם התורה<sup data-n=\"8005\">977</sup> ולא לשם עצמו כו'. וזהו ההפרש בין ת[ו]שב\"כ שנק' תורת הוי' דוקא שחפצו בתורת הוי' אדעתא דנפשי' כדי להאיר אור הוי' בנשמתו לתקנה ולהעלותה במקור שרשה למעלה שזהו באותיות דתוה\"ק כמ\"ש אז ראה ויספרה כו', דנש\"י עבמ\"ח<sup data-n=\"8006\">978</sup> ג\"כ באותיות דתוה\"ק דג' קשרים הן ישראל מתקשרא[ן] באורייתא למעלה בבחי' סתים<sup data-n=\"8007\">979</sup> כו' (כמשי\"ת<sup data-n=\"8008\">980</sup> ). וזהו<sup data-n=\"8009\">981</sup> חדאי נפשאי שתשמח הנפש בעסק זה שקורא בתורה כקורא בשמותיו כו', לכך<sup data-n=\"8010\">982</sup> קראי בשבילך להאיר ולהחיות אותה כי הם סייג<sup data-n=\"8011\">983</sup> ממש כו' לכך נשמח בד\"ת וכמ\"ש לא ימ[ו]ש<sup data-n=\"8012\">984</sup> כו' כי היא חייך<sup data-n=\"8013\">985</sup> כו' וכמ\"ש בכמה מקומות. והוא כמו מזון הרוחני העליון שנמשך מעה\"ח שכולו חיים וטוב (כלחם הפנים וכלחם פנג<sup data-n=\"8014\">986</sup> כו'), שנעשה אור וחיות אלקי ממש לנשמות למעלה וגם למטה בקריא' האותיות דתשב\"כ הנגלות לנו כו'. וא\"צ לבא בבחי' בירור ותיקון כלל כי חכ' זו דת[ו]שב\"כ כבר הובררה בעצמו' דח\"ע הקדומה שנק' תוה\"ק או משל הקדמוני<sup data-n=\"8015\">987</sup> כו', שאז ראה ויספרה שסיפר[ה] וברר אותה והכינה [ו]גם חקרה כו' עד שאין בה נטי' כלל וכלל לימין לחסד בשפע [ביותר] מכפי המדה ולא לדין בקו השמאל יותר מכפי המדה כו', אלא בקו היושר לאמתתו כמו שהוא בעצמו' פנימי' הרצון והחכ' ממש וכמ\"ש כל אמר\"ת אלו\"ה צרופה<sup data-n=\"8016\">988</sup> כו' שנק' חכ' ברור\"ה מכבר, וכמו עד\"מ חכם גדול שמברר לחכמה עמוקה ביותר שיהי' [ל]תכלית האמת והיושר בלי נטיה [ל]צד כלל שבירור הזה הוא בכח עצמו' ופנימי' דחכ' שלו דוקא<sup data-n=\"8017\">989</sup> שז\"ש אז ראה ויספר\"ה כו', וזהו ח\"ע דתוה\"ק כנ\"ל. וזהו שנק' לחם מן השמים שכבר הוברר בח\"ע העצמי' ולזאת נק' מזונא דח\"ע לנשמות בשרשם כמו במ\"ת שהאיר ה' פנימי' ח\"ע דתוה\"ק בא' אנכי<sup data-n=\"8018\">990</sup> כו' ועכ\"ד פרחה נשמתן כו' לפי שס\"ר נש\"י הללו <span data-k=\"pg\">1250</span> ּ מקושרים בהן למעלה כנ\"ל.",[["7999","971","<b>כלחם לבב אנוש</b>: ע\"פ תהלים קד, טו."],["8000","973","<b>כ\"א בתורת הוי' חפצו</b>: תהלים א, ב. בהמשך תרס\"ו כאן ניתוסף: ובתורתו יהגה כו' דמתחלה נק' תורת ה' ואח\"כ נק' תורתו כו' והענין הוא ע\"פ משארז\"ל בפסחים. ראה גם לעיל פ' בשלח רלז, א. וש\"נ. יתרו רנו, ג. משפטים רצ, ד. סה\"מ מלוקט ח\"ו ע' קה ובהנסמן שם."],["8001","974","<b>מעיקרא עביד אינש אדעתא דנפשי'</b>: ראה פסחים סח, ב. (בהערה שלפנ\"ז)."],["8002","975","<b>כמו שא' ר\"ש </b>[טז: רב ששת]<b> חדאי נפשאי</b>: ראה פסחים שם."],["8003","976","<b>ע\"ש</b>: טז: על שמו."],["8004","972","<b>בתורת הוי'. . ואח\"כ ובתורתו יהגה. . ובתורתו</b>: ראה ע\"ז יט, א."],["8005","977","<b>עוסק בתורה לשמ\"ה דוקא לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. לעיל פ' וארא פ, ד. וש\"נ."],["8006","978","<b>עבמ\"ח</b>: טזיז: עלו במח\"ת."],["8007","979","<b>ישראל מתקשרא[ן] באורייתא. . סתים</b>: ראה גם לעיל פ' משפטים רצ, ג ובהערה 183."],["8008","980","<b>כמשי\"ת</b>: יביז: כמ\"ש במ\"א."],["8009","981","<b>וזהו</b>: מכאן (עד לקמן על יד הערה 989) הועתק בהמשך תרס\"ו ע' שפח."],["8010","982","<b>לכך</b>: טזיז: לך. בהמשך תרס\"ו: ולך."],["8011","983","<b>סייג</b>: שם: חיינו."],["8012","984","<b>לא ימ[ו]ש</b>: יהושע א, ח."],["8013","985","<b>כי היא חייך</b>: משלי ד, יג."],["8014","986","<b>וכלחם פנג</b>: ראה זהר ויחי רלה, ב. רמו, א. לעיל פ' שמות כג, ב הערה 956."],["8015","987","<b>משל הקדמוני</b>: נסמן לעיל פ' יתרו רנט, ד."],["8016","988","<b>כל אמר\"ת אלו\"ה צרופה</b>: משלי ל, ה. ראה גם לעיל פ' בשלח קעג, ב. וש\"נ."],["8017","989","<b>דוקא</b>: ע\"כ בתרס\"ו. ראה לעיל הערה 981."],["8018","990","<b>במ\"ת. . אנכי</b>: יתרו כ, ב."]]],[2300550801,"<b>והנה</b> ודאי כדי לברר [ל]עצם הח\"ע דתוה\"ק הנ\"ל צריך להיות בכל כח גדלות החכמה ודעת ותבונה בעומק גדול בעצמו' כח חכמתו ית' דלתבונתו אין מספר<sup data-n=\"8019\">991</sup> ונק' חכים ולא בחכמה ידיעא כו', שזהו מ\"ש אז ראה בראי' עין החכ' שבעמקות עצמות חכמתו ויספרה ויבררה כו' הכינה וחקרה היטב כמו ששוקל אדם בפלס במאזני שכלו בעמקות באיזה דבר חכ' ושכל עד שמעמיד אותו על קו היושר והבירור לתכליתו. ואמנם זה אינו צריך ליגיעה ועמל כלל אלא רק מצד עצם הכח של החכ' שישכיל ע\"ז<sup data-n=\"8020\">992</sup> ויוצ[י]א לאור מן ההעלם לגילוי במשקל טוב כמו שמודד האומן החכם בקו המדה בלי נטי' לימין ושמאל וכמ\"ש מי מדד בשעלו<sup data-n=\"8021\">993</sup> כו' עפ\"י תכלית בירור החכמה כו', וז\"ש ואהי' אצלו אמון אומנא כו'. ולזאת גם אחר שירד האור דחכמה הברורה מכבר להשתלשלות דקו\"ח כו' נק' בשם קו המדה שמודד כל או\"כ פנימי' ומקיפי' דתה\"ו ותיקו\"ן עד חיצוני' הכלים דאצי' כו' הכל במדה ושיעור בפנימי' וחיצוני' לא יוסיף ולא יגרע, והוא שנק' ס' היש\"ר<sup data-n=\"8022\">994</sup> וכמו כי ישרים דרכי הו\"י'<sup data-n=\"8023\">995</sup> שבתורה כמו בשם הוי' דתו' דאצי' שנמדד בחכמה שבה כל או\"כ ואיך וכמה יבא באו\"פ ואו\"מ כו' (וכמ\"ש בפ' לך לך<sup data-n=\"8024\">996</sup> שכל הענין דמצות בס' שמות וס' האחרי' הוא להוסיף אור באצי' מן ההעלם דעצמות המאציל עפ\"י חכ' דתוה\"ק ביתר מכפי הצמצום הראשון שהי' ע\"י האבות כו' שנק' ס' הישר, אך גם זה שנוסף האור בדרכי התו\"מ בא במדה דוקא והן שיעורי' וגבולי' דמ\"ע ול\"ת כו' שיובדל הפנימי' מן החיצוני' ולא כחסד דאברהם שיצא ממנו ישמעאל<sup data-n=\"8025\">997</sup> כו' ויצחק יצא<sup data-n=\"8026\">998</sup> כו' שהן מותרות השפע דחו\"ג<sup data-n=\"8027\">999</sup> דאצי' וכה\"ג. וע\"ז נמשך אור דחכמה דתוה\"ק בקו המדה להבדיל הפנימי' מן החיצוני' כמו במצות צדקה כדין נמשך בחי' פנימי' דאור החסד בדרועא ימינא<sup data-n=\"8028\">1000</sup> כו' ויובדל החיצוני' שלא יומשך רק בחיצוני' הכלי דחסד זה וגם זה במדה כו', וכן בגבו' דיצחק בכלי [ה]גבו' להבדיל בין [ה]פנימי' לחיצוני' בגבו' כו' שלא יומשך גבו' דקדושה בקו השמאל לק\"נ רק כפי הצריך כו' (וזהו ושמי הוי' לא נודעתי להם<sup data-n=\"8029\">1001</sup> כמ\"ש במ\"א).\n<b>וזהו</b> ג\"כ ענין בראשית בחכמה דתוה\"ק שנק' ראשית [כמ\"ש ה' קנני ראשית] דרכו<sup data-n=\"8030\">1002</sup> והוא מ\"ש ואהי' אצלו אמון אומנא",[["8019","991","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["8020","992","<b>ע\"ז</b>: טזיז: ע\"ד."],["8021","993","<b>מי מדד בשעלו</b>: ישעי' מ, יב."],["8022","994","<b>ס' היש\"ר</b>: ראה הערה 239."],["8023","995","<b>כי ישרים דרכי הו\"י'</b>: הושע יד, י."],["8024","996","<b>בפ' לך לך</b>: ראה תו\"ח שם פד, ד ואילך."],["8025","997","<b>דאברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. לעיל פ' בא קיז, ג. וש\"נ."],["8026","998","<b>ויצחק יצא</b>: נסמן בהערה שלפנ\"ז."],["8027","999","<b>דאברהם. . ויצחק. . דחו\"ג</b>: נסמן לעיל פ' משפטים רעח, ב."],["8028","1000","<b>צדקה. . החסד בדרועא ימינא</b>: ת\"ז בהקדמה (יז, א). ראה גם מאמרי אדה\"א שמות ח\"א ע' צט. וש\"נ."],["8029","1001","<b>ושמי הוי' לא נודעתי להם</b>: נסמן לעיל פ' יתרו רנא, א ובהערה 16."],["8030","1002","<b>דתוה\"ק. . ראשית] דרכו</b>: משלי ח, כב."]]],[2300550802,"כאומן שבונה עפ\"י החכמה שכבר הוברר כך מודד באמת הבנין שבידו לעמוד כל דבר ודבר על מכונו וציורו כפי הצריך להיות עפ\"י החכמה הברורה דתוה\"ק, כמו בחכ' יבנה בית<sup data-n=\"8031\">1003</sup> בחכ' שבתורה דוקא יבנה בנין העולמות וכמ\"ש כולם בחכמה עשית<sup data-n=\"8032\">1004</sup>. וכמו מאמר יהי אור שנברא מהות האור בציורו לפי אופן העולה בחכמה דתורה דוקא וכן יהי רקי\"ע וכה\"ג יהי מאורות<sup data-n=\"8033\">1005</sup> ותדשא הארץ<sup data-n=\"8034\">1006</sup> ותוצא הארץ<sup data-n=\"8035\">1007</sup> שתוציא הארץ<sup data-n=\"8036\">1008</sup> כל נפש ח\"י' בציורן ציוה ונבראו חק נתן ולא יעבור הכל עפ\"י קו המדה דתורה כו'. וידוע דו' ימי בראשית הן ו' אלפי' שנה<sup data-n=\"8037\">1009</sup> דהוי עלמא כי אלף שנה כיום אתמול<sup data-n=\"8038\">1010</sup> כו' ומא' יהי אור מקור לכל אלף שנה הראשוני' דבחי' החסד<sup data-n=\"8039\">1011</sup>, ודאי כל מה שנמשך מאין ליש בבחי' חסד זה שהוא בקו הימין<sup data-n=\"8040\">1012</sup> בפרטי פרטיות הכל נמשך מחסד דחכמה דתורה ונבדל ג\"כ &lt;תרכה&gt; ּ החיצוני' מן הפנימי' דהיינו גם מה שנמשך מותרות השפע מחסדים דקו הימין (כמו אברהם כו' כנ\"ל). וכמו\"כ בקו השמאל בבחי' הגבו' דאלף שנה השנ[י]י' במא' יהי רקיע<sup data-n=\"8041\">1013</sup> כו' נמשך הכל מבחי' גבורות דחכ' דתורה באופן מיוחד דוקא, וגם מבדיל בין פנימי' השפע לפנימי' הכלי' לחיצוני' ומותרות השפע לחיצונית הכלים. וכך הוא בכל ו' ימי בראשית עד אלף הששי שהוא ביום הוי\"ו [ב]מא' נעשה אדם<sup data-n=\"8042\">1014</sup> שצריך להיות בו הבדלה האמיתי' בין טו\"ר בעה\"ד טו\"ר (והוא ימוהמ\"ש ותחה\"מ שלפני אלף הז' שהוא העוה\"ב<sup data-n=\"8043\">1015</sup> ). וזהו שאמר אשר ברא אלקי' לעשות לתקן שברא באופן שצריך תיקון להשלים החסרון שנעשה ע\"י חטא עה\"ד (אע\"פ שהי' אח\"כ בבריאת האדם ביום הוא\"ו והרי א' וירא אלקים כו' והנה טוב מאד<sup data-n=\"8044\">1016</sup> כו' מבואר במ\"א), ועיקר התיקון לעה\"ד טו\"ר היינו ע\"י החכ' שבתורה. וז\"ש בראשית בשביל התורה כו' משום דבחכמה דוקא אתברירו שהוא בכללות הבירור בוימ\"ב שהן מקוריי' לכל ו\"א שנים למטה להבדיל בין טו\"ר כנ\"ל, וכך הוא הבירור גם למעלה במדות דאצי' כמו בחסד דרועא ימינא כו' שיובדל הפנימי' מן החיצוני' כנ\"ל. וזהו כל ענין החכ' בראש שנתלבשה וירדה למטה לברר לעה\"ד בין טו\"ר אעפ\"י שעצמות החכמה דתורה היא מעה\"ח שלמעלה מעה\"ד אבל ירדה בחכמה שבה לתקן ולברר החסרון שנעשה באו\"כ מצד השבירה דכלים דתהו כו', וזהו שתנאי הי'<sup data-n=\"8045\">1017</sup> כו' שהעיקר דתיקון זה בחכמה דתורה הי' במ\"ת שהאיר ה' בחכ' דתורה למטה ממש בא' אנכי ולא כו' שהן חו\"ג דמ\"ע ול\"ת<sup data-n=\"8046\">1018</sup> בכלל",[["8031","1003","<b>בחכ' יבנה בית</b>: משלי כד, ג. ראה גם תו\"ח בראשית ז, א."],["8032","1004","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["8033","1005","<b>יהי מאורות</b>: בראשית א, יד."],["8034","1006","<b>ותדשא הארץ</b>: בראשית א, יא."],["8035","1007","<b>ותוצא הארץ</b>: בראשית א, כד."],["8036","1008","<b>הארץ</b>: טזיז: ליתא."],["8037","1009","<b>דו' ימי בראשית הן ו' אלפי' שנה</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["8038","1010","<b>כי אלף שנה </b>[טז: ליתא]<b> כיום אתמול</b>: נסמן לעיל שצא, ב."],["8039","1011","<b>יהי אור. . החסד</b>: ראה גם לעיל פ' בשלח ריח, א. וש\"נ."],["8040","1012","<b>חסד. . בקו הימין</b>: נסמן לעיל פ' יתרו רסט, ג הערה 19."],["8041","1013","<b>הגבו'. . במא' יהי רקיע</b>: ראה גם לעיל פ' בשלח ריח, א."],["8042","1014","<b>נעשה אדם</b>: בראשית א, כו."],["8043","1015","<b>אלף הז' שהוא העוה\"ב</b>: ראה גם לעיל פ' בשלח רכא, ב ואילך. וש\"נ."],["8044","1016","<b>וירא אלקים. . טוב מאד</b>: בראשית א, לא. ראה גם שע\"ת סה, ג. תו\"ח ח\"ש קלג, סע\"ד ואילך. מאמרי אדה\"א שמות ח\"א ע' רלט."],["8045","1017","<b>שתנאי הי'</b>: ראה שבת פח, א."],["8046","1018","<b>אנכי ולא. . דמ\"ע ול\"ת</b>: נסמן לעיל פ' יתרו רנב, א הערה 80."]]],[2300550803,"ונעשה בירור והבדלה בכלל ובפרט בעה\"ד טו\"ר בכל המצות מ\"ע ול\"ת הכתובי' באותיות דתשב\"כ, וזהו שא' להורות ולהבדיל בין טמא לטהור<sup data-n=\"8047\">1019</sup> כו' ונבדל עי\"ז גם למטה המותרות והחיצוני' מבחי' הפנימי' וכמ\"ש וזרח משעיר למו<sup data-n=\"8048\">1020</sup> כו' וד\"ל.\n<b>ואמנם</b> הנה כ\"ז הוא שנק' בירור דחכ' באוי\"ר<sup data-n=\"8049\">1021</sup> ההולך מלמעלה למטה ביושר ואמת כנ\"ל בלי נטי' לימין ושמאל בחיצוני' דחיצוני' דחו\"ג, וכמו שכבר הוברר במקור החכמה דתוש\"מ בגדלות החכ' והדעת כמו שהוא בעמקות תבונתו כנ\"ל עד שנק' חכ' ברורה כנ\"ל, ועפ\"ז מדד כל אופן ההשתל' ובהבדלה באו\"כ כנ\"ל עד גם למטה לברר בין טו\"ר במ\"ע ול\"ת באור המבהיק ביותר שמאיר למטה מטה ביותר לברר פסולת מתוך אוכל כו' (והוא שנעשה מזון מבורר לנשמות כמו מזון המן שאין בו מותרות בחיצוני' כלל כנ\"ל שנק' לחם מן השמים שעי\"ז נעשה הזדככות הצורה ביותר כמ\"ש ויענך כו' לבער הרע מן הטוב בתכלית כידוע). ובזה יתפרש ג\"כ מ\"ש כאן ויקהל משה את כל עדת כו' ויאמר אליהם אלה הדברים כו', דהנה ידוע בשרש משה דמן המים משיתיהו<sup data-n=\"8050\">1022</sup> וטוב הוא בטי\"ת רבת\"י מעה\"ח שכולו טוב ופנימי' [ב]לי חיצוני' כלל. וזהו מ\"ה שמו כו' מ\"ה דחכמה הקדומה דתוש\"מ כנ\"ל שכבר הוברר ומ\"ה שם בנו זהו נש\"י<sup data-n=\"8051\">1023</sup> שעלה במחה\"ק כנ\"ל וכל מי שהוא בעצמו מתוקן ומבורר יש ביכולתו לתקן<sup data-n=\"8052\">1024</sup> ולברר למי שצריך תיקון <span data-k=\"pg\">1252</span> ּ להשלים חסרונו, כמו בוימ\"ב בחיצוני' וכמדות<sup data-n=\"8053\">1025</sup> דתהו שנפלו למטה בעה\"ד טו\"ר לברר הפנימי' מן החיצוני' בהבדלה דתורה. וזהו שנא' במשה בכל ביתי נאמן הוא לתקן ולברר בעה\"ד עפ\"י עצמות כח החכמה שבתו\"מ ש\"מ<sup data-n=\"8054\">1026</sup> שנק' הון ביתו כו' גם בנובלות דחש\"מ<sup data-n=\"8055\">1027</sup> שהיא התורה הנגלית לנו ע\"י משה שנק' מחוקק וסופ\"ר כו' (וזהו כמו ענין המשל הנ\"ל בבן חכם מופלג ומושלם שהצליח בנכסי אביו בחכמה שקנה מאביו ומדות הישרים לברר ולתקן כו', וכך הוא התו' ונש\"י שקדמו במח' ונברר על ידם בזמן מ\"ת בגילוי מן ההעלם ע\"י משה שנק' נאמן ביתו כו' כנ\"ל).\n<b>וזהו</b> ויקהל משה שהוא מ\"ה דחכמה דתו' שרש נש\"י שנק' עדת וכמ\"ש ת\"ר אלף רגלי העם אשר אנכי בקרבו<sup data-n=\"8056\">1028</sup> שכולל כולם כנ\"ל, ויאמר אליהם אלה הדברים אשר צוה הוי'",[["8047","1019","<b>להורות ולהבדיל בין טמא לטהור</b>: שמיני י, י. יא [ושם: ולהבדיל בין. . הטמא ובין הטהור. . ולהורות — ראה גם מאמרי אדה\"א בראשית ע' נב]."],["8048","1020","<b>וזרח משעיר למו</b>: ברכה לג, ב."],["8049","1021","<b>באוי\"ר</b>: טזיז: באו\"י באור ישר."],["8050","1022","<b>דמן המים </b>[שם: המ\"ע]<b> משיתיהו</b>: שמות ב, י. ראה לעיל פ' שמות מג, א. וש\"נ."],["8051","1023","<b>מ\"ה שמו. . דחכמה הקדומה. . ומ\"ה שם בנו זהו נש\"י</b>: ראה גם מאמרי אדה\"א בראשית ע' כו."],["8052","1024","<b>וכל. . בעצמו מתוקן. . ביכולתו לתקן</b>: ראה לעיל פ' בשלח ריא, ב. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תריט ואילך (ב' הנוסחאות) בשם הע\"ח־ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380594\" data-slug=\"likkutei-torah\" data-id=\"4001380594\">לקו\"ת בלק סט, א</a>־ מאמרי אדה\"א במדבר ח\"ד ע' א'תק ואילך בשם הע\"ח ובהנסמן בהנ\"ל. בראשית ע' קלט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680459\" data-slug=\"torat-chaim\" data-id=\"2300680459\">תו\"ח מקץ רכח, א</a>. שע\"ת פ, ב."],["8053","1025","<b>וכמדות</b>: טזיז: ובמדות."],["8054","1026","<b>שבתו\"מ ש\"מ</b>: שם: שבתושמ\"ע. אבל לעיל שצז, ב: בתו\"מ העליוני'."],["8055","1027","<b>בנובלות דחש\"מ</b>: ב\"ר פי\"ז ה. פמ\"ד, יז."],["8056","1028","<b>ת\"ר אלף. . אנכי בקרבו</b>: בהעלותך יא, כא."]]],[2300550804,"דוקא שזהו ענין הבירור שציוה הוי' דחכמה דתורה לברר במדות שבתורה הקדומה שירדה למטה בעה\"ד טו\"ר כנ\"ל, שהן ו' מדות וכל א' כלול מו' הרי ל\"ו גימ' אלה שהן פנימי' ומקור למדות דוימ\"ב כנ\"ל וגם הן ל\"ט מלאכות שנעש[י'] בו' ימי המעשה כו' (כמו שדרש ר[בי] אל\"ה ל\"ו [דברים] הדברים ג' גימ' ט\"ל כו'), וכ\"ז מדבר במצות הבירורי' דרפ\"ח כו' ע\"י החכמה ומדות דתורה שניתן לישראל דוקא ותנאי הי' לוימ\"ב כו'. וזהו בראשית בשביל התורה [כו'] ובשביל ישראל כו' שזהו מ\"ה שמו ומ\"ה שם בנ\"ו כנ\"ל שירדו למטה לברר בעה\"ד טו\"ר משום דבחכ' דתוש\"מ שירדה למטה נברר הפנימי' מן החיצוני' וניתקן כל חסרון ופגם כמ\"ש לעשות לתקן דוקא כנ\"ל, וא\"א שיתקן כ\"א מי שכבר מתוקן בעצמו (כענין קשוט עצמך<sup data-n=\"8057\">1029</sup> כו'). והוא ע\"י משה וישראל שירדו מבחי' הח\"ס<sup data-n=\"8058\">1030</sup> דתוש\"מ שכבר הוא בבחי' התיקון כנ\"ל שנק' חכמה ברורה מכבר כמ\"ש כל אמרת ה'<sup data-n=\"8059\">1031</sup> צרופה כו', וכתיב אז ראה ויספר\"ה בספר<sup data-n=\"8060\">1032</sup> כו'. וזהו אלה הדברים (די' הדברות בכלל ובפרט בכל אותיות דתשב\"כ) בל\"ט מלאכות דו' ימי המעשה בבירורי' דרפ\"ח ע\"י המדות דתוש\"מ, אשר צוה ה' לעשות אותם פי' לעשות לתקן אות[ם] כמו להבדיל המותרות והחיצוני' שלא ילך ביותר מכפי המדה הצריך כי ע\"י חכ' דתורה מתברר גם בחי' המותרות כמו בסומ\"ר כו', וכמו בחסד דרועא כו' שלא יקבלו מצפרני'<sup data-n=\"8061\">1033</sup> כחסד דישמעאל כנ\"ל. וזהו ג\"כ פי' ו' ימים שהן ו' מדות דוימ\"ב תיעשה מלאכה מעצמה כנ\"ל כי ע\"י החכ' דתורה ממילא מתברר גם בין טמא לטהור וכמו שמבררי' פסולת מאוכל לפי שחכמה זו איך לברר בל\"ט מלאכות כבר הוברר בכח החכ' ש\"מ כנ\"ל וד\"ל.\n<b>אך</b> הנה כ\"ז הוא בבחי' בירור דאו\"י דח\"ע שיורד מלמעלה למטה כנ\"ל דאעפ\"י ששרש הבירור הזה נמשך מחכ' הקדומה שכבר<sup data-n=\"8062\">1034</sup> הוברר בעצמות כח החכ' כנ\"ל, מ\"מ אין זה בירור שלם עדיין מאחר <span data-k=\"pg\">תרכו</span> ּ שלא הובא עדיין לידי מעשה בנסיון בפו\"מ כמו שאין חכם מברר חכמתו כ\"א בנסיון דוקא, וכאומן החכם שגם שכבר נברר לו אופן החכ' שבבנין אינו ברור עדיין כ\"א כשבונה בפ\"מ שאז מייגע עצמו בכל עומק עיונו איך ומה לעשות אופן הבנין בכל פרטיו. וכך הוא בענין הבירורי' דרפ\"ח כו' וכמו בל\"ט מלאכות בוימ\"ב כנ\"ל שעיקר שלימות הבירור הוא בחכ' שבדבור בת[ו]שבע\"פ דוקא שהוא בעיון ועומק החכ' בעמל ויגיעה רבה באופן המעשה לברר בין טו\"ר בפרטי פרטי' כמו בכל ו' סדרי משנה בבירור ההלכות ודיני' בפרט[י]ות באופן המ\"ע ול\"ת כך וכך דוקא, כמו זה כשר וזה פסול בפרטו' וזה אסור וזה מותר וכן טו\"ט חייב זכאי כו'. דאע\"פ שכבר הוברר בח\"ע הקדומה אופן הבירור גם בעה\"ד ע\"י אור תושב\"כ להבדיל הפנימי' מן החיצוני', זהו כמו שהי' כבר<sup data-n=\"8063\">1035</sup> בהעלם",[["8057","1029","<b>קשוט עצמך</b>: ב\"מ קז, סע\"ב. ראה גם לעיל פ' שמות מד, ב ובהערה 69."],["8058","1030","<b>הח\"ס</b>: טזיז: החכ[מ]'."],["8059","1031","<b>ה'</b>: טזיז: כו'. יט: אלוקה."],["8060","1032","<b>אז ראה ויספר\"ה בספר</b>: ראה גם לעיל פ' תרומה שיג, א."],["8061","1033","<b>שלא יקבלו מצפרני'</b>: ראה גם לעיל פ' בשלח קעד, ב ובהערה 480."],["8062","1034","<b>שכבר</b>: מכאן ועד לקמן ד\"ה וכך על יד הערה 1039 (באשה ת[ו]שבע\"פ) נמצא בהמשך תרס\"ו ע' שצ-צב בשינויים והוספות."],["8063","1035","<b>כבר</b>: יב: ליתא יז: בכח."]]],[2300550805,"דחכ' [ש]בראש כמו<sup data-n=\"8064\">1036</sup> שמאי\"ן ליש תמצ\"א מצד עצם כח החכ' שהוא נמשך מכח החכ' העצמי' בלי יגיעה ועמל כלל כנ\"ל, אבל עיקר [ה]שלימות הבירור הזה הוא דוקא כשמביא לידי נסיון במעשה בפרט שאז צריך להתיישב [ו]להעמיק דעתו בעיון ביגיעה רבה לברר בפרטות כל דבר עד שיבורר כל דין והלכה מכל סיג ופסולת שזהו תכלית שלימות ההבדלה בעה\"ד טו\"ר (שנק' הזדככות החומר להוציא כל טוב מן הרע כל מה שיוכל להתברר כמ\"ש במ\"א). וזהו שנק' לחם מן הארץ, כמו שצריך לעבוד האדמה בחרישה וזריעה כו' עד שיוצא המובחר והברור להיות מאכל לחם שזהו עיקר ענין ל\"ט מלאכות בסידורא דפת (כמשי\"ת) עד שאופה ומבש\"ל ויהי' בו טעם למאכל אדם, דודאי גם מלאכה זו באפי' ובישול יש כמה אופנים שונים עפ\"י הדעת בעיון ויגיעה רבה איך להוציא הטעם המובחר ואיך להסיר תחלה הפסולת באופן שיהי' בו טעם טוב ויהי' מתעכל בכי טוב לחיות ומזון ממש והפסולת יודחה לחוץ, שלא יוכל לעשות זה גם החכם הגדול מצד עצם חכמתו שלמד וידע באופן המלאכה בבישול ואפי' וכן זריעה וקצירה, כ\"א בנסיון בפ\"מ שמייגע עצמו בכל כחו איך ומה לעשות התיקון באופן שיהי' ראוי, כמו בלימוד בכלי אומנות לעשות כלים נאים דגם שיודע בחכ' כל אופן המעשה וברור לו הכל בשכלו [ב]כל הנצרך איך ומה הוא לעשות באופן ציור הכלי מ\"מ א\"א להביא לפועל ממש כ\"א שמייגע עצמו זמן רב בנסיון בפועל בכלי אומנות כמה פעמים עד שילמוד מעשה האומנות בכי טוב אצל רבו כו' וד\"ל (וכנ\"ל במשל הבן שהי' שלם בכל חכמה והלך ללמוד אומנות שנעשה עבד ימים רבים עד שהרגילו בנסיון המעשה להיות אומן בידו לעשות הכלים כרבו כו' שזהו עיקר השלימות בלימוד החכ' שתחי' בעליה דחכמה כנ\"ל).\n<b>וכך</b> יובן בבחי' הבירור דחכ' בת[ו]שבע\"פ בש\"ס משנה שמבררים בפ\"מ כמו אומן הבונה בפו\"מ וכמ\"ש בוני\"ך אלו ת\"ח<sup data-n=\"8065\">1037</sup> שהן הבונים בפ\"מ דוקא<sup data-n=\"8066\">1038</sup> כו' ביגיעה ועמל תורה שמ[ת]חדשים מאין ליש ממש בבחי' או\"ח שלמעלה מבירור הראשון <span data-k=\"pg\">1254</span> ּ דח\"ע דאו\"י שאינו אלא יש מיש כו' כנ\"ל, וזהו דבינה יתירה ניתנה באשה<sup data-n=\"8067\">1039</sup> ת[ו]שבע\"פ. וזהו זא\"ת דוקא נחמתי בתושבע\"פ שנק' מזון ממש להיות תורתך בתוך מעי ממש ע\"י ל\"ט מלאכות עד בישול ואפי' שנעשה לחם ממש כו', וזהו ובתורת\"ו יהגה בתושבע\"פ שנק' תו\"א ככלי אומנות לחדש יש מאין כו' שעי\"ז ממשיך אוא\"ס בתורה שנקרא עוסק בתורה לשמ\"ה לשם התו' מטעם הנ\"ל וד\"ל. וזהו אלה הדברים ל\"ט מלאכות שמתבררים בש\"ס משנה שהן ו' ימים תיעשה מעצמה ביגיע' [ב]כפיו בלבד והוא בדבור שאו' כשר ופסול כו' כעבד בעול שעוסק בכלי אומנות בפ\"מ בלבד. וזהו לעשו\"ת אות\"ם",[["8064","1036","<b>כמו</b>: טזיז: ליתא. יב: כבפנים."],["8065","1037","<b>בוני\"ך אלו ת\"ח</b>: נסמן לעיל פ' תצוה שמב, א הערה 812."],["8066","1038","<b>דוקא</b>: טזיז: ליתא."],["8067","1039","<b>דבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. לעיל פ' שמות י, ב. וש\"נ."]]],[2300550806,"לתקן בפ\"מ [וז\"ש בפ' ואלה כו' ב]עבד עברי שא' שש שנים יעבוד<sup data-n=\"8068\">1040</sup> שהן ש\"ס משנה<sup data-n=\"8069\">1041</sup> בשש שנים<sup data-n=\"8070\">1042</sup> באו\"ח בעומ\"ש וביום הז' בעוה\"ב כו' וד\"ל.\n[כ]<b> ומעתה</b> י\"ל מ\"ש אלה הדברים אשר צוה הוי' לעשות אותם שהן ל\"ט מלאכות שנעשו במשכן שציוה ה' לעשות אותם כמבואר בפ' תרומה תצוה ועל אלה הדברים א' כאן ו' ימים תעשה מלאכה שלא הותרו לעשות רק בו' ימי המעשה ולא בשבת (וכך פי' הרמב\"ן בחומש<sup data-n=\"8071\">1043</sup> ע\"ש), ולכך נסמכה פ' שבת לפ' המשכן<sup data-n=\"8072\">1044</sup> ללמוד ממשכן כל ל\"ט מלאכות שהיו במשכן שאסורים בשבת כמובן במס' שבת<sup data-n=\"8073\">1045</sup> ומבואר שם דילפינן ל\"ט מלאכות האסורים בשבת מאלה הדברים כו' (דאל\"ה אותיות אה\"ל<sup data-n=\"8074\">1046</sup> כו'), ובאמת י\"ל למה תלוי איסור מלאכות הללו בשבת מפני שהיו במשכן דוקא [ו]באותן מלאכות שהיו במשכן ולא מלאכות אחרים זולתם. והנה יש להקדים ענין א' והוא מ\"ש בזהר פ' ויקהל דקוב\"ה אתענג<sup data-n=\"8075\">1047</sup> מעינוגי' דישראל בשבתא כו' (והוא לפי שבע[ו]נג זה דסעוד' השבת שורה מבחי' ע[ו]נג העליון דעצמו' המאציל שנק' עתיקא קדישא ולכך או' דא היא סעודתא דע\"י<sup data-n=\"8076\">1048</sup> כו') וכמ\"ש וקראת לשבת ענג ע[ו]נג העליון ממש ובמה מענגו<sup data-n=\"8077\">1049</sup> כו' וזהו פלא גדול לכאורה האיך יתענג ה' מעינוגי' גשמיי' דישראל בשבת כו'. ואדרבה לכאורה יש לומר עפ\"י הטעם באיסור ל\"ט מלאכות בשבת שגם האכילה אסור בשבת דוקא, לפי שכמו שהל\"ט מלאכות כחורש וזורע כו' הן ענין הבירורי' שמברר ומבדיל בין טו\"ר להפריד הרע מן הטוב ולהוציא הטוב מן הרע בגשמיות וברוחניות כידוע, כך הוא גם ענין האכילה של אדם שאוכל המאכל בשינוי<sup data-n=\"8078\">1050</sup> שמפרר<sup data-n=\"8079\">1051</sup> ומברר במאכל להוציא הטוב ו[ה]חיות שבו ומתברר בקיבה היטב ונבחר הפנימי' לחיות [ו]מזון והפסולת נדחה לחוץ שזהו בירור גמור בין טו\"ר בגשמיות. וכך הוא ברוחניות שהרי המזונות כולן מעורבי' טו\"ר מצד גידולם בארץ שמעורבת טו\"ר גשמיי' וטו\"ר רוחני', ואע\"פ שנברר הרע מן הטוב בזריעה וקצירה וכל המלאכות עד אפי' ובישול זהו בגשמיות אבל ברוחניות יש במאכל הלחם בחי' רע מן הגסות וההגשמה<sup data-n=\"8080\">1052</sup> ביותר להביאו לחום קשה לתאוות זרות וגסות",[["8068","1040","<b>שש שנים יעבוד</b>: משפטים כא, ב."],["8069","1041","<b>שש שנים. . שהן ש\"ס משנה</b>: ראה גם לעיל פ' משפטים רצב, ג. וש\"נ."],["8070","1042","<b>בשש שנים</b>: טזיז: בוא\"ש — נסמן לעיל הערה 444."],["8071","1043","<b>הרמב\"ן בחומש</b>: כאן (לה, ב)."],["8072","1044","<b>נסמכה פ' שבת לפ' המשכן</b>: להבא לקמן ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' רלז ואילך (הנחת כ\"ק אדה\"א). תקס\"ד ע' עח ואילך (הנחת הר\"מ) ובהנסמן במ\"מ לשם."],["8073","1045","<b>כמובן במס' שבת</b>: ראה גם שבת מט, ב. צז, ב."],["8074","1046","<b>דאל\"ה אותיות אה\"ל</b>: לקו\"ת להאריז\"ל ס\"פ תולדות. מאמרי אדה\"ז שם. אוה\"ת ויקהל ע' ב'קלג."],["8075","1047","<b>בזהר פ' ויקהל דקוב\"ה אתענג</b>: ראה שם רד, ב. לעיל פ' בשלח רטו, ד. וש\"נ."],["8076","1048","<b>או' דא היא סעודתא דע\"י</b>: ראה גם לעיל שצא, ג. וש\"נ."],["8077","1049","<b>ובמה מענגו</b>: נסמן להלן הערה 1066."],["8078","1050","<b>בשינוי</b>: יבטז: בשיניי'. יז: בשיניו."],["8079","1051","<b>שמפרר</b>: יב: כבפנים. טז: כתב תיבה זו ומחקה. יז: שמפריד."],["8080","1052","<b>וההגשמה</b>: טז: וההרגשה."]]],[2300550807,"הלב ביותר כמו מלא כעס<sup data-n=\"8081\">1053</sup> כו' וכגיאות הסוס והבהמה מן השעורי'. ולהיפך יש במאכל הלחם להוסיף כח חלק הטוב כמו <span data-k=\"pg\">תרכז</span> ּ במדות [ה]טובות בגשמיות כמו ונשבע לחם ונהי' טובים<sup data-n=\"8082\">1054</sup> וברוחני' במדות טובות בדרכי החיים [ה]טוב שיעבוד ה' בכח האכילה ויוברר החום הטבעי מן המאכל להיות בהתלהבות אלקי כו', וכן מוסיף כח השכל האנושי' וגם כח השכל באלקו' ביחו\"ע כו'. וראי' לכל זה מבהמ\"ז שאחר שאכל לשובע מברך להוי' כמ\"ש ואכלת ושבעת דוקא וברכת את הוי'<sup data-n=\"8083\">1055</sup> כו' (וכן הקרבנות מבשר ודם וחלב בהמה גשמי' שנקרב ע\"ג המזבח נעשה מזה לריח ניחוח להוי' דאצי' כו'). ולכך נק' לחם ל' מלחמה<sup data-n=\"8084\">1056</sup> כמו לח\"ם שערים<sup data-n=\"8085\">1057</sup> שיש מלחמה בסעודת הלחם אם יגבר חלק הרע שבו על הטוב [או] שיגבר חלק הטוב על הרע, וזהו מא' הינוקא מאן דבעי למיכל נהמא אפום חרבא<sup data-n=\"8086\">1058</sup> כו' (וכידוע ומבואר במ\"א שהאכילה היא הבירור במלחמה בין טו\"ר כמו התפלה<sup data-n=\"8087\">1059</sup> שנק' קרבא שנה\"ב מתגבר על הנה\"א כו') ולכך כמו שמזבח מכפר בקרבנות על נפש החוטאת כך שולחנו של אדם מכפר עליו<sup data-n=\"8088\">1060</sup> עכשיו מטעם הנ\"ל). ולפ\"ז הרי הי' ראוי לאסור האכילה בשבת כמו ל\"ט מלאכות ממש שמבררי' הטוב מן הרע [כו' כך האכילה מברר לטוב מן הרע] כנ\"ל ובורר אסור בשבת להיות ששובת ונח מכל מלאכה ובירור שבו' ימי החול כידוע (ומה שהקרבנו' מקריבים בשבת כמו בחול אע\"פ שגם הן כמו בחי' הבירורי' בהקרבת חו\"ד וכמוסף שבת בב' כבשי'<sup data-n=\"8089\">1061</sup> ונק' עולת שבת<sup data-n=\"8090\">1062</sup> כו' מאחר שנק' לחמי לאשי<sup data-n=\"8091\">1063</sup> כו', גם זה יש להבין מאיזה טעם הותרו בשבת כו' (כמשי\"ת). וא\"כ לפ\"ז יותר יפלא מ\"ש בזהר דקוב\"ה מתענג מענוגי' דישראל בסעודות השבת כו', מאחר שנק' בירור כמו מלחמה ואם חלק הרע יגבר יגשם לנפש ויטמא אותו בעונג גשמי זה עד שיופרד מאלקות ולא יגורך רע<sup data-n=\"8092\">1064</sup> כתיב ואיך אומר שיתענג כו' ואיך או' ע\"ז דא הוא סעודתא כו'. ואם לפי שבשבת אין הרע שבמאכל גובר כלל וכלל ולכך מותר לאכול לתיאבון בשבת<sup data-n=\"8093\">1065</sup> וכמו שא' במה מענגו בבשר ודגים<sup data-n=\"8094\">1066</sup> כו' וכמ\"ש במ\"א בענין פרש חגיכם ולא פרש שבתכם<sup data-n=\"8095\">1067</sup> כו', הא גופא י\"ל למה אין פרש ופסולת<sup data-n=\"8096\">1068</sup> במאכלים דשבת עד שלא יגשם<sup data-n=\"8097\">1069</sup> בע[ו]נג הגשמי בחלק הרע הגם שיש במאכל בהכרח מאחר שהוא מעה\"ד טו\"ר).",[["8081","1053","<b>מלא כעס</b>: טז: מלי כריסא. יז: מלא כריסי' — ברכות לב, א. ראה גם אוה\"ת האזינו ע' א'תרצד. המשך תער\"ב ח\"א ר\"ע תקסט."],["8082","1054","<b>ונשבע לחם ונהי' טובים</b>: ירמי' מד, יז."],["8083","1055","<b>ואכלת ושבעת. . וברכת את הוי'</b>: עקב ח, י."],["8084","1056","<b>לחם ל' מלחמה</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'עד. וש\"נ. שמות ח\"א ע' קפ. וש\"נ. הנחות תקע\"ז ע' קכט."],["8085","1057","<b>לח\"ם שערים</b>: שופטים ה, ח."],["8086","1058","<b>מא' הינוקא. . נהמא אפום חרבא</b>: ראה זהר בלק קפח, ב. וראה גם לקו\"ש אחרי (כרך ג) ע' 988 הערה *8."],["8087","1059","<b>שהאכילה. . כמו התפלה</b>: ראה מאמרי אדה\"ז תקס\"ו ע' רכט. מאמרי אדה\"א שמות שם. וש\"נ."],["8088","1060","<b>שולחנו של אדם מכפר עליו</b>: ברכות נה, א. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שסה. וש\"נ."],["8089","1061","<b>וכמוסף שבת בב' כבשים</b>: ראה סה\"מ להרמב\"ם מ\"ע מא."],["8090","1062","<b>ונק' עולת שבת</b>: פינחס כח, י."],["8091","1063","<b>לחמי לאשי</b>: פינחס כח, ב."],["8092","1064","<b>ולא יגורך רע</b>: תהלים ה, ה."],["8093","1065","<b>מותר לאכול </b>[טזיז: באכילה]<b> לתיאבון בשבת</b>: ראה גם לעיל פ' בשלח רי, ד. וש\"נ."],["8094","1066","<b>במה מענגו בבשר ודגים</b>: ראה שבת קיח, ב. שו\"ע אדה\"ז הל' שבת סרמ\"ב, ס\"ב."],["8095","1067","<b>פרש חגיכם ולא פרש שבתכם</b>: מלאכי ב, ג. ראה זהר יתרו פח, ב. ראה גם לעיל פ' בא קכ, ג. וש\"נ."],["8096","1068","<b>ופסולת</b>: טז ניתוסף: כלל."],["8097","1069","<b>במאכלים דשבת עד שלא יגשם</b>: ראה מכתב ז' טבת תשי\"ד נדפס בלקו\"ש בשלח כרך לא ע' 247. אג\"ק שלו ח\"ח ע' צא."]]],[2300550808,"<b>אך</b> הנה יש להקדים תחלה בשרש ענין הל\"ט מלאכות שכולם הן בבחי' הבירורי' לברר בין טו\"ר כנ\"ל אבל הן נחלקו לג' חלוקות כמבואר במשנה שמונה מלאכות שבסידורא דפת<sup data-n=\"8098\">1070</sup> בפ\"ע כו', והיינו ג' מדרגות בכלל מזון ולבוש ובית והיכל כו', המזון בלחם יש מלאכות אבות ותולדות והוא סדורא דפת דקתני ברישא [ה]חורש וזורע<sup data-n=\"8099\">1071</sup> וקוצר ודש<sup data-n=\"8100\">1072</sup> כו' עד אופה ומבשל<sup data-n=\"8101\">1073</sup>, והחלוקה הב' בלבושי' כטוה ואורג כו', והחלוקה הג' בבית והיכל כבונה וסותר כו', ושארי מלאכות דקתני במתני' נכללו בג' אלה מיני מלאכות בכלל שנחלקו לפי אופן האדם שהוא בג' מדרגות הללו, הא' במזון שהוא<sup data-n=\"8102\">1074</sup> החיות שיחי' האדם בנפשו בגופו שהוא חיבור הצורה בחומר<sup data-n=\"8103\">1075</sup> שאינו אלא ע\"י המזון דלחם דוקא שעל הלחם יחי' האדם בנפשו שתתקיים בגופו כלחם לבב אנוש יסעד<sup data-n=\"8104\">1076</sup> כידוע, ולכך מונה תחלה המלאכות שבסידורא <span data-k=\"pg\">1256</span> ּ דפת כו' (ואע\"פ שמאכל הלחם אינו עצם החיות לנפש הרוחני' עצמה כ\"א לחזק האור וחיות שתחי' לאברי' בסיבת חיות הדם הוא הנפש שמתחזק כחו ע\"י המאכל שנהפך לדם כידוע, וא\"כ עיקר המזון דלחם הוא לכלי וחומר הגוף מ\"מ הרי כלי חומר האברי' פנימי' וחיצוני' מתאחדי' עם הנפש ממש ואין אור בלא כלי שמתחבר בו כו' א\"כ זהו שיחי' האדם ממש (וזהו שנק' או\"פ המוגבל בכלים דנר\"נ במוחא ולבא<sup data-n=\"8105\">1077</sup> כו' (כמשי\"ת). וחלוקה הב' בלבושים כאורג וטווה כו' זהו ג\"כ שייך לאדם שיתלבש בלבוש וכיסוי שיכסה א\"ע מראש לרגל וזהו כבודו והדרו (כר\"י קארי למאני מכבדותא<sup data-n=\"8106\">1078</sup> כו') שנבדל מן הבהמה וחי' שא\"צ ללבושי' כו', ואע\"פ שהלבושי' אינם שייכים לגוף האדם בעצם להיות חיותו וקיומו מהם כמו ע\"י המזון, מ\"מ א\"א לו בלי לבושים לעולם שאין אדם ילך ערום וגם מפני הקור והגשמים להגן עליו כידוע, ויש בהן יתרון מעלה מן המזון במה שהלבושים נק' מקיפים כידוע (כענין שארה כסותה<sup data-n=\"8107\">1079</sup> כו' שארה אלו המזונות<sup data-n=\"8108\">1080</sup> כו' (וכמבואר בסידור באריכות בענין מזון לבוש בית<sup data-n=\"8109\">1081</sup> בענין חנוכת הבית) כי המקיפים דנר\"נ שורי' הן על הלבושי'<sup data-n=\"8110\">1082</sup> דוקא כידוע, ולכך מנה המלאכו' שבלבושי' בחלק בפ\"ע כו'. והחלוקה הג' הוא בבחי' הבנין דבית והיכל שגם שהאדם יוכל להיות בלא בית א\"א לו",[["8098","1070","<b>שבסידורא דפת</b>: שבת עד, ב (עג, א)."],["8099","1071","<b>[ה]חורש וזורע</b>: כ\"ה גם במאמרי אדה\"ז שבהערה 1044. אבל באוה\"ת ויקהל ע' ב'קלד הזורע והחורש. ראה שבת עג, ב: ליתני חורש והדר ליתני זורע. פי' רע\"ב־ מלאכת שלמה־ שנויי נוסחאות ודק\"ס במשנה שם. רמב\"ם רפ\"ז מהל' שבת. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380046\" data-slug=\"likkutei-torah\" data-id=\"4001380046\">לקו\"ת בשלח ב, א</a>."],["8100","1072","<b>ודש</b>: במשנה שם: והמעמר והדש."],["8101","1073","<b>אופה ומבשל</b>: ראה שבת עד, ב. שו\"ע אדה\"ז הל' שבת סשי\"ח, ס\"ז."],["8102","1074","<b>שהוא</b>: טזיז: שזהו."],["8103","1075","<b>הצורה בחומר</b>: ראה מו\"נ ח\"א, פי\"ז. לעיל פ' בשלח רי, ב הערה 54."],["8104","1076","<b>כלחם לבב אנוש יסעד</b>: ע\"פ תהלים קד, טו."],["8105","1077","<b>דנר\"נ במוחא ולבא</b>: ראה אבן עזרא משפטים כג, כה. לעיל בפ' בשלח קמה, א. וש\"נ."],["8106","1078","<b>כר\"י קארי למאני מכבדותא</b>: ראה שבת קיג, א."],["8107","1079","<b>שהלבושים. . כענין </b>[טזיז: בענין]<b> שארה כסותה</b>: משפטים כא, י. ראה מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע תקמו ואילך. ע' תקמט. ע' תקסב וע' תקסו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380366\" data-slug=\"likkutei-torah\" data-id=\"4001380366\">לקו\"ת במדבר יד, ג</a>."],["8108","1080","<b>שארה אלו המזונות</b>: כתובות מז, ב. מכילתא ורש\"י משפטים שם."],["8109","1081","<b>בסידור. . מזון לבוש בית</b>: שער התפלה יט, ד ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381122\" data-slug=\"likkutei-torah\" data-id=\"4001381122\">לקו\"ת ברכה צח, ד</a>. מאמרי אדה\"ז הנחות הר\"פ ע' עט."],["8110","1082","<b>המקיפים דנר\"נ שורי' הן על הלבושי'</b>: ראה גם לעיל פ' בשלח קפ, ג. וש\"נ."]]],[2300550809,"להתקיים בלי דירה בבית והיכל שמקיף עליו לדור בו ולישן בו ונק' מקיף למקיף כידוע (שהוא ד\"א שלו כידוע ) שנק' מקומו ש\"א<sup data-n=\"8111\">1084</sup> כו'<sup data-n=\"8112\">1085</sup> ([ו]כמ\"ש בסידור שם<sup data-n=\"8113\">1083</sup> ) וכמו שא' כל תפארת<sup data-n=\"8114\">1086</sup> אדם לשבת בית<sup data-n=\"8115\">1087</sup> כו'. והנה ג' מדרגות הללו דמזון ולבוש ובית נכללי' באדם בג' מדרגות שבו באו\"כ ומקיף למקיף כנ\"ל וד\"ל.\n<b>וכך</b> הוא למעלה שבצלם אלקי' עשה לאדם התחתון כידוע שיש בעולם האצי' ג\"כ ג' מדרגות הללו דאו\"כ שנק' גופא כמ\"ש גופין תקינת לון<sup data-n=\"8116\">1088</sup> כו' (וכמו אי אנת כו' אשתארו כגופא<sup data-n=\"8117\">1089</sup> כו' וכחכ' מוחא חסד דרועא<sup data-n=\"8118\">1090</sup> כו'), וענין חיבור וקישור האורות בכלים למעלה זהו כדוגמא [ל]אדם למטה שהוא ע\"י העלא' דקרבנות שנק' לחמי לאשי כו' וכמ\"ש בזהר בענין הקרבנות שעולה הבירורי' מהם בבחי' או\"ח בג' שלישי'<sup data-n=\"8119\">1091</sup> דלעילא מוחא<sup data-n=\"8120\">1092</sup> לבא וכבדא כו' כמו שהמאכל נהפך לדם בכבד ועולה ללב המובחר ומן הלב עולה המובחר למוח כו' ואח\"כ יומשך באו\"י מלמעלה למטה תוס' אור וחיות מן המוח ללב ומן הלב לאברים כו' (וכמ\"ש במ\"א באריכות<sup data-n=\"8121\">1093</sup> ). והמדריג' הב' באדם העליון דאצי' בבחי' לבושי' שבהן שורי' המקיפי' דנר\"נ כנ\"ל, וז\"ש לבושין תקינת לון<sup data-n=\"8122\">1094</sup> כו' והוא כמ\"ש עוטה אור כשלמה כו' וכמ\"ש<sup data-n=\"8123\">1095</sup> לבושי' כתלג<sup data-n=\"8124\">1096</sup> כו', וכה\"ג שיש בהן יתרון מעלה מן המזון כנ\"ל. והמדרגה הג' למעלה הוא שנק' בחי' היכלות ובית כמו שנק' אדרין עילאין<sup data-n=\"8125\">1097</sup> כמו כתפארת אדם לשבת בית<sup data-n=\"8126\">1098</sup> כו' וכהיכל ובהמ\"ק למטה שנק' בית הוי' ממ\"ש כמו שבתי בבית ה'<sup data-n=\"8127\">1099</sup> כו' ונק' בחי' מקיף [למקיף] למעלה כו' וד\"ל (וכמו הנה מקום אתי<sup data-n=\"8128\">1101</sup> כו' וכמו [הנה] ה' יוצא ממקומו<sup data-n=\"8129\">1102</sup> שנק' <span data-k=\"pg\">תרכח</span> ּ מקומו דוקא שהוא כמו ד\"א של אדם וכן ד\"א של הלכה שנתפס בהן כמו בהיכל ק\"ק<sup data-n=\"8130\">1103</sup> דאורייתא היכלא עילאה דקוב\"ה<sup data-n=\"8131\">1104</sup> כמ\"ש בזהר (וכמשי\"ת<sup data-n=\"8132\">1100</sup> ).\n<b>והנה</b> מאחר של\"ט מלאכות הללו בכלל הן בבחי' בירורי' דוקא שמברר בטו\"ר ומפריד הרע מן הטוב כו' א\"כ זהו בכל מדרג' מג' מדרגות הנ\"ל, [ש]כמו שבמזון דלחם ודאי יש בחי'",[["8111","1084","<b>ד\"א. . מקומו ש\"א </b>[טז: של אדם]: ראה אנציק' תלמודית בערכו. וש\"נ."],["8112","1085","<b>כידוע). . כו'</b>: טזיז: כידוע. . יז: כו')."],["8113","1083","<b>מקיף למקיף. . בסידור שם</b>: כ, ב. כא, א."],["8114","1086","<b>כל תפארת</b>: יב: כתפארת. טז: דתפארת. יז: בתפארת."],["8115","1087","<b>כל תפארת אדם לשבת בית</b>: נסמן לקמן הערה 1098."],["8116","1088","<b>גופין תקינת לון</b>: ת\"ז בהקדמה (יז, א)."],["8117","1089","<b>אי אנת. . כגופא</b>: ראה ת\"ז שם (יז, ב)."],["8118","1090","<b>וכחכ' מוחא חסד דרועא</b>: ראה ת\"ז שם (יז, א)."],["8119","1091","<b>בג' שלישי'</b>: טזיז: בג' שליטי'."],["8120","1092","<b>בג' שליטי' דלעילא מוחא</b>: ראה זהר תרומה קנג, א. (מדהנ\"ע) תולדות קלח, א. רות פ, א."],["8121","1093","<b>בג' שליטי'. ֿ. שהמאכל נהפך. . במ\"א באריכות</b>: ראה גם שע\"ת מג, ב ואילך. מאמרי אדה\"א בראשית ר\"ע קטז וע' תעג."],["8122","1094","<b>לבושי' תקינת לון</b>: ת\"ז בהקדמה (יז, א)."],["8123","1095","<b>וכמ\"ש</b>: טזיז: וכתיב."],["8124","1096","<b>לבושי' כתלג</b>: דניאל ז, ט."],["8125","1097","<b>אדרין עילאין</b>: ראה ז\"ח לך כו, א. ויצא כח, ב. שה\"ש סח, ב."],["8126","1098","<b>כתפארת אדם לשבת בית</b>: ישעי' מד, יג."],["8127","1099","<b>שבתי בבית ה'</b>: תהלים כז, ד."],["8128","1101","<b>הנה מקום אתי</b>: תשא לג, כא."],["8129","1102","<b>[הנה] ה' יוצא ממקומו</b>: ישעי' כו, כא."],["8130","1103","<b>ד\"א של הלכה. . בהיכל ק\"ק</b>: ראה הנסמן לעיל פ' תרומה שיא, ג הערה 12."],["8131","1104","<b>דאורייתא היכלא עילאה דקוב\"ה</b>: ראה זהר ויקהל ר, א. מאמרי אדה\"א דברים ח\"ב ע' תיג."],["8132","1100","<b>[וכמו. . (וכמשי\"ת)</b>: יז: ליתא."]]],[2300550810,"הבירור בזריעה וקצירה כו' עד לישה ואפי' ואכילה עצמה שאוכל ולועס בשיניו ואח\"כ מתעכל במעיו עד שנברר בירור הרוחני' והחיות עולה ללב כו', שזהו בחיבור האור בכלי צורה וחומר כנ\"ל שע\"י הבירור הזה העולה מלמטה למעלה גורם המשכת האור ושפע [ה]רוחני' [ד]נפש שיאיר בתוס' אור במוחא ולבא וכבדא בג' כלים דנר\"נ ומשם לכל האברים עד כח [ה]הילוך שברגל כו'. וכך הוא במזון דלחם דתורה כמ\"ש לכו לחמו [בלחמי] כו' כנ\"ל דאותיות התורה עצמן הוא שמבררי' בין טו\"ר באמרו כשר פסול כו', וכשגור[ס] בדבור בפה זהו כמו שטוחן היטב בשיניו כו' שמדקדק היטב ומחלק לחלקים כמו גר\"ש כרמ\"ל<sup data-n=\"8133\">1105</sup> כו' ואז נעשה לו התורה מזון וחיות לנפשו האלקי' כמו ותורתך בתוך מעי ממש דהיינו לחבר האור בכלי השכל האלקי' כמו בהשגות יחו\"ע ויחו\"ת<sup data-n=\"8134\">1106</sup> במוח ומדות שכליי' בלב עד דו\"ר טבעי' שנמשך חיות לכל האברי' במעשה המצות כו'. [ו]כמו כח ההילוך בדרכי ה' בנגלה ונסתר כמ\"ש ילכו מחיל<sup data-n=\"8135\">1107</sup> כו' שתלוי בכח המזון דלחם דתורה הנגלי' דוקא שבאה בבחי' הבירורי' דטו\"ר בסומ\"ר וע\"ט דמ\"ע ול\"ת שנברר במלאכות דחורש וזורע כו' שנק' עמ\"ל תורה כו' עד שנעשה לחם ומזון לנשמה האלקי'. וראי' לזה ממה שמכריזי' בג\"ע אשרי מי שבא לכאן להשיג השגות אלקות מזיו השכינה ותלמודו שלמד בעוה\"ז בידו<sup data-n=\"8136\">1108</sup> שיש עי\"ז כח השכל האלקי' להשיג יותר עד כח ההילוך ברגל שילך ממדרגה למדרגה כו'.\n<b>וכך</b> הוא במדרגה הב' שנק' לבוש שהן מעשה המצות שנק' לבושי' לנשמה כמ\"ש וילבש צדקה<sup data-n=\"8137\">1109</sup> כו' שהמצות שנק' צדקה<sup data-n=\"8138\">1110</sup> נק' לבוש כשריון, וכמו שלבוש הגשמי נעשה מצמר ופשתן לכסות את האדם שלא ילך ערום ויגן עליו מן חום השמש והגשמים כנ\"ל והן חיצוני' יותר שמובדלים הלבושי' מעצם גוף האדם שאין בהם חיות ממש לגוף כמזון, מ\"מ יש במצות שנק' לבושי' לנשמה לכסות אותה מראשה לרגלה בהילוכה (כמו בהילוכה בג\"ע שאמר והלך לפניך צדקיך<sup data-n=\"8139\">1111</sup> וכבוד<sup data-n=\"8140\">1112</sup> ה' יאספ\"ך שהן לבושי' של אור זך ובהיר לנשמה שנעשי' מבירורי' דק\"נ שנעשה בהן המצות כידוע) (וכמו ביהושע כה\"ג שא' ישימו הצניף הטהור על ראשו<sup data-n=\"8141\">1113</sup> ויסירו",[["8133","1105","<b>וכשגור[ס]. . גר\"ש כרמ\"ל</b>: ויקרא ב, יד. וראה לעיל הערה 966."],["8134","1106","<b>יחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["8135","1107","<b>ילכו מחיל </b>[יז: מחא\"ח]: תהלים פד, ח."],["8136","1108","<b>אשרי מי שבא לכאן. . ותלמודו. . בידו</b>: פסחים נ, א. ראה גם לעיל פ' שמות ה, א. וש\"נ."],["8137","1109","<b>וילבש צדקה</b>: ישעי' נט, יז."],["8138","1110","<b>שהמצות שנק' צדקה</b>: ראה לעיל יד, א ובהערה 628."],["8139","1111","<b>והלך לפניך צדקיך</b>: ישעי' נח, ח. ראה לעיל פ' וארא סב, ג הערה 133."],["8140","1112","<b>וכבוד</b>: טזיז: כבוד — ראה לעיל פ' משפטים שב, ב הערה 498."],["8141","1113","<b>ישימו הצניף הטהור על ראשו</b>: זכרי' ג, ה [ושם: צניף טהור]. ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' סז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010174\" data-slug=\"or-hatorah-hb\" data-id=\"8159010174\">אוה\"ת בראשית כרך ז ע' תתתמד</a>."]]],[2300550811,"ממנו בגדי' הצואי'<sup data-n=\"8142\">1114</sup> שנק' לבושי' דמסאבותא<sup data-n=\"8143\">1115</sup> כו' כמ\"ש במ\"א). וראי' לזה שהרי א' אלה המצות שיעשה<sup data-n=\"8144\">1117</sup> אותם האדם וחי בהם<sup data-n=\"8145\">1116</sup> מחיי החיים<sup data-n=\"8146\">1118</sup> כו', אלא שבחי' האור וחיות לנשמה מן המצות שנק' לבושי' אינן באי' בבחי' גילוי אור וחיות ממש כאור בכלי ע\"י מזון דלחם רק באי' בבחי' מקיף בהעלם שהוא בחי' הלבוש שמלביש מבחוץ לשומר ולמגן כנ\"ל, וכך [א'] שומר מצוה לא ידע דבר רע<sup data-n=\"8147\">1119</sup> כו'. והיינו מה שבחי' מקיפי' דנר\"נ שורים על בחי' הלבושי' דמעשה המצות כמו אך בצל\"ם יתהלך <span data-k=\"pg\">1258</span> ּ איש בצל\"ם דמוקף<sup data-n=\"8148\">1120</sup> דנר\"נ שמחמת כח המקיף יתעורר במוחא ולבא כו' כמו ע\"י עטיפת הטלית והנחת תפילין קודם התפלה כידוע, וכן א' אני בצדק דוקא אחזה פניך<sup data-n=\"8149\">1121</sup> כו' במוח ולב בפנימי' דשם הוי' רק ע\"י צדקה דמצות. וכמו שהמזון דתורה באה בבחי' הבירורי' דוקא כנ\"ל, כך הוא בענין המצות שנק' לבושי' שנעש[ים] בדברים גשמיי' דק\"נ בבחי' בירור הטוב הגנוז ברע בשבה\"כ כו' וזהו כמו האורג וטווה בצמר או פשתן עד שעושה בגד ולבוש ללבוש כו'. וזהו שא' בא\"ח שהן כנ\"י<sup data-n=\"8150\">1122</sup> שמבררים בעה\"ד טו\"ר במצות דרשה צמר ופשתים<sup data-n=\"8151\">1123</sup> כו' וכמו סדין עשתה ותמכור<sup data-n=\"8152\">1124</sup> כו' שזהו הרמז על כללות הבירורי' דחשמ\"ל דנוג\"ה<sup data-n=\"8153\">1125</sup> שהן כתנו\"ת עו\"ר דאדה\"ר כידוע שנעשי' לבושי' דכיא<sup data-n=\"8154\">1126</sup> לנשמות בג\"ע (וזהו שא' יעקב ונתן לי לחם לאכול בבחי' מזון דתורה שהוא בבחי' או\"פ ובגד ללבוש הן מעשה המצות<sup data-n=\"8155\">1127</sup> כו' והי' הוי' לי לאלקי'<sup data-n=\"8156\">1128</sup> ביחו\"ע דמקיף ופנימי בתוס' אור מן הבירורי' דרפ\"ח כו' כידוע).\n<b>והמדרגה</b> הג' בבחי' בית והיכל שנק' מקיף למקיף כנ\"ל והיינו בחי' אותיות התורה עצמן שנעשי' בבחי' היכל ובית כמ\"ש אחת שאלתי<sup data-n=\"8157\">1129</sup> כו', והיינו כמו היכל ק\"ק שבצמצום<sup data-n=\"8158\">1130</sup> שצמצם שכינתו שם בין ב' בדי הארון<sup data-n=\"8159\">1131</sup> כו' וכמו שא' דאוריי' היכלא עילאה כו', והוא כענין מקומו של אדם בד\"א שלו שמתפשט במקום זה מבחי' מקיף למקיף דהיינו מ\"ם דצל\"ם בחי' יחידה<sup data-n=\"8160\">1132</sup> שבו כו' שעי\"ז נעשה לו הגנה מכל צד מלמעלה [ו]למטה שמ[ו]קף בו ודר שם בקביעות. כך בהיכל דתורה שנק' אה\"ל תורה כיעקב יושב אוהלים<sup data-n=\"8161\">1133</sup> שהאהל בא בבחי' מקיף מלמעלה ולמטה וצדדי' ושם יוכל להיות יחו\"ע",[["8142","1114","<b>ויסירו ממנו בגדי' הצואי'</b>: זכרי' שם, ד [ושם הסירו הבגדים הצאים מעליו]. ראה גם לעיל פ' שמות ו, א. מאמרי אדה\"ז אתהלך לאזניא ע' סח ד\"ה ויען. נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650178\" data-slug=\"or-hatorah-hb\" data-id=\"8316650178\">אוה\"ת</a> זכרי' [וכצ\"ל ב]אוה\"ת נ\"ך ח\"ב ע' תתקז. מאמרי אדה\"א נ\"ך ע' קצב. הנחות תקע\"ז ע' רמד. שע\"ת ק, ב (ספ\"א). שה\"א מז, א."],["8143","1115","<b>לבושי' דמסאבותא</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."],["8144","1117","<b>שיעשה</b>: טזיז: אשר יעשה."],["8145","1116","<b>אלה המצות. . וחי בהם</b>: חיבור שני פסוקים בחוקותי כז, לד. אחרי יח, ה. ראה גם הנסמן לעיל פ' בשלח קעה, ד."],["8146","1118","<b>מחיי החיים</b>: ראה יומא עא, א."],["8147","1119","<b>שומר מצוה לא ידע דבר רע</b>: קהלת ח, ה."],["8148","1120","<b>דמוקף</b>: יב: מקיף. טזיז: ומקיף."],["8149","1121","<b>אני בצדק. . אחזה פניך</b>: תהלים יז, טו. ראה גם סידור שער התפלה כא, סע\"ד."],["8150","1122","<b>בא\"ח שהן כנ\"י</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' י."],["8151","1123","<b>דרשה צמר ופשתים</b>: משלי לא, יג."],["8152","1124","<b>סדין עשתה ותמכור</b>: משלי לא, כד."],["8153","1125","<b>דנוגה</b>: יב: כבפנים. טזיז: דוקא."],["8154","1126","<b>לבושי' דכיא</b>: זהר שלח קסט, ב."],["8155","1127","<b>ונתן לי לחם לאכול. . דתורה. . ובגד. . המצות</b>: ויצא כח, כ. ראה גם לעיל פ' בשלח ריז, א. וש\"נ."],["8156","1128","<b>והי' הוי' לי לאלקי'</b>: ויצא כח, כא. ראה גם לעיל פ' שמות מח, ג. וש\"נ."],["8157","1129","<b>אחת שאלתי</b>: תהלים כז, ד."],["8158","1130","<b>שבצמצום</b>: טזיז: ליתא."],["8159","1131","<b>שצמצם שכינתו שם בין ב' בדי הארון</b>: נסמן לעיל פ' תרומה שטו, ג."],["8160","1132","<b>מקומו של אדם בד\"א. . יחידה</b>: ראה גם לעיל פ' בשלח קעט, ד. וש\"נ."],["8161","1133","<b>כיעקב יושב אוהלים</b>: תולדות כה, כז."]]],[2300550812,"דקוב\"ה ושכינתי' שהקב\"ה יושב וקורא ושונה כנגדו<sup data-n=\"8162\">1134</sup> בהיכל זה עצמו, וכמו שא' למען אחיי<sup data-n=\"8163\">1135</sup> כו' למען בית ה'<sup data-n=\"8164\">1136</sup> כו' שהיכל הזה מקיף לשניהם יחד<sup data-n=\"8165\">1137</sup> כמ\"ש במ\"א וד\"ל.\n[כא]<b> והנה</b> מובן מכל הנ\"ל עכ\"פ בג' מדרגות דל\"ט מלאכות במזון ולבוש ובית והיכל דהמזון הוא בחי' פנימי' אור וחיות יותר שהרי גופו ונפשו שמורכבי' מד\"י גשמיי' עיקר חיות וקיום שלהם הוא מן המאכלים שהן מן הצומח והחי כלחם ובשר כנ\"ל, והב' בבחי' הלבוש הרי הוא חיצוני יותר שאין בהן אור וחיות לאדם כלל רק לכסותו מבחוץ בלבד כנ\"ל, והג' הוא הבית והיכל חיצוני יותר מן הלבוש שאינו אלא לדור בהן כנ\"ל וכל שחיצוני יותר נמשך בו ממדרג' העליונה יותר, שהרי במזון שהוא בחי' פנימי' יותר אינו אלא בבחי' או\"כ המוגבל ובלבוש החיצוני יותר נמשך האו\"מ כנ\"ל ובבית והיכל החיצוני יותר נמשך מקיף למקיף כנ\"ל לפי שזהו הכלל דבחיצוני' יותר נמשך מהעלם דמקיף<sup data-n=\"8166\">1138</sup> דוקא (אבל בחי' הכלי לאו\"מ כלבוש מתקיים יותר זמן ויקר יותר מן המאכל שכלה וצריך לאכול מחדש שאינו אלא לחדש חיות האו\"פ המוגבל בכלי הגוף, משא\"כ בלבוש דאע\"פ שהוא חיצוני אדרבה בזה דוקא שורה מאו\"מ שלא יוכל ליכנס באו\"כ וכך מתקיים זמן רב יותר. והיכל ובית מתקיים זמן רב יותר ויקר יותר <span data-k=\"pg\">תרכט</span> ּ מן הלבוש להיותו חיצוני יותר ששורה בו מקיף למקיף כנ\"ל (וכמ\"ש בסידור<sup data-n=\"8167\">1139</sup> ). וכך יובן בהפרש שבין מזון דתורה ללבוש דמצות שע\"י לבוש דמצות נמשך או\"מ שמתקיים יותר ויש בכחו להעלות לנשמה בעילוי גדול בלא הדרגה וערך כמו והלך לפניך צדקיך כו' וכמ\"ש במ\"א במ\"ש והיתה נפש אדוני צרור\"ה<sup data-n=\"8168\">1140</sup> כו' ונק' ימים שהן הלבושי' משא\"כ במזון דתורה שאין כח ההילוך רק לפ\"ע האו\"פ בכלי כו').\n<b>וכמו\"כ</b> יובן למעלה באדם העליון דאצי' שיש ג\"כ ג'<sup data-n=\"8169\">1141</sup> מדרגות הללו דמזון ולבוש ובית כנ\"ל ובחי' מזון הוא בבחי' פנימי' יותר שזהו לחבר האורות דע\"ס דז\"א בכלים שנק' גופא כו' כנ\"ל, ואעפ\"י שבחי' גופא שהן הכלים הן מגבילים לאור ואינם מעיקר האור רק בחי' התגלות דאור כמו אותיות השכל והמדות כו' וכאברים שבאדם למטה שאינם [כמו] בחי' רוחניות החיות שבנפש עצמה כידוע וד\"ל<sup data-n=\"8170\">1142</sup>, עכ\"ז הרי האברים מתאחדים בעצם הנפש ונעשי' כמו עצם א' עם הנפש",[["8162","1134","<b>שהקב\"ה. . ושונה כנגדו</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."],["8163","1135","<b>למען אחיי</b>: תהלים קכב, ח."],["8164","1136","<b>למען בית ה'</b>: תהלים שם, ט."],["8165","1137","<b>שהיכל הזה מקיף לשניהם יחד</b>: ראה גם לעיל פ' בשלח קפ, א ובהערה 709."],["8166","1138","<b>שזהו הכלל דבחיצוני'. . דמקיף</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670124\" data-slug=\"torat-chaim\" data-id=\"2300670124\">תו\"ח נח מז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670492\" data-slug=\"torat-chaim\" data-id=\"2300670492\">נה, ג</a>."],["8167","1139","<b>וכמ\"ש בסידור</b>: שער התפלה יט, ד ואילך."],["8168","1140","<b>והיתה נפש אדוני צרור\"ה</b>: שמו\"א כה, כט. ראה גם לעיל פ' משפטים רפה, ב ובהנסמן שם. שא, ב."],["8169","1141","<b>ג'</b>: יאיז: ליתא. יב: כבפנים."],["8170","1142","<b>וד\"ל</b>: שם: וכנ\"ל."]]],[2300550813,"(עד שהפגם באבר א' הוא כמו שנפגם האור וחיות הרוחני שבו ממש כו'). וכך למעלה באדם העליון שאע\"פ שאין לו גוף ולא דמות גוף ולא נערוך אליו<sup data-n=\"8171\">1143</sup> בדמיון וציור אדם וכל תואר אדם כי לא אדם הוא<sup data-n=\"8172\">1144</sup> כו', עכ\"ז דברה תורה כל[שון] בנ\"א<sup data-n=\"8173\">1145</sup> בכמה מקומות כמו וירא ה'<sup data-n=\"8174\">1146</sup> וישמע ה'<sup data-n=\"8175\">1147</sup> וישב כו'<sup data-n=\"8176\">1148</sup> ויתעצב אל לבו וינחם<sup data-n=\"8177\">1149</sup> כו' וישמח הוי'<sup data-n=\"8178\">1150</sup> כו' וכה\"ג. וכ\"ז הוא בבחי' אורות דע\"ס שנאצלו מן המאציל בכלים כמו חכמה מוחא חסד דרועא כו' שנק' גופא דמלכא כו', והפגם בשם הוי' באור ע\"י הפגם בכלי דוקא כמו בחילול שבת שפוגם ביו\"ד דשם הוי' דחכמה בראש ופגם בוי\"ו במדות<sup data-n=\"8179\">1151</sup> ובכלל כל הפגמי' דעונות נק' פושעים בי בגופא דמלכא<sup data-n=\"8180\">1152</sup> שהוא בכלים ואורות. ולהיפוך במע\"ט מוסיפים אורות בכלים כו', והיותר מוסיף ומחבר האורות בכלים זהו בחי' מזון דלחם דתורה וכמ\"ש אכלו ריעים לעילא כו' שזהו מאכל דחכ' דתורה דאצי' וכנ\"ל באדם למטה בנשמה האלקי' (וכמו הקרבנות ע\"ג המזבח שנק' לחמי לאשי כו' ועכשיו התפלה במקום קרבן<sup data-n=\"8181\">1153</sup> שמקריב לנה\"ב בשלהבת י\"ה החו\"ד דתאוות זרות כו'). והמדרגה הב' למעלה באצי' זהו בחי' לבוש העליון שמלביש ומכסה לגופא דמלכא כו', [ד]היינו כמו שנמשך מעצמו' המאציל בחי' מזון כלחם דתוש\"מ (כמו ג\"ש יושב ועוסק בתורה<sup data-n=\"8182\">1154</sup> דאצי' כו') כאכלו ריעים כו' (שזהו בצומח דתבואה ובשר מבהמות וחיות דאצי' וכה\"ג) כך נמשך מעצמות המאציל בחי' לבוש שהוא מבחי' הצומח [דצו\"פ<sup data-n=\"8183\">1155</sup> ] (כמו ויעש ה' לאד\"ם ולאשת\"ו<sup data-n=\"8184\">1156</sup> שהן זו\"נ דאצי' כתנות או\"ר בא' לבוש של אור זך ונק' חשמל העליון<sup data-n=\"8185\">1157</sup> ) (שנעשה מחיצוניות דבינה עילאה להלביש לזו\"נ עד מתחת רגליהם<sup data-n=\"8186\">1158</sup> וזהו בשלו\"ם אותיות מלבו\"ש<sup data-n=\"8187\">1159</sup> ). והמדרגה הג' למעלה בחי' היכל ובית שיהי' לדירה לבחי' אדם העליון כמו כתפארת אדם לשבת בית שזהו נמשך ממקיף למקיף כנ\"ל וכאפריון עשה לו המלך<sup data-n=\"8188\">1160</sup> כו' (וכמו מכון לשבתך פעלת הוי' [כו'] שהוא בבית המל' ששם כסא המל' ונק' בתי <span data-k=\"pg\">1260</span> ּ גוואי והיכלות פנימי', ויש היכלות חיצוני' ושער לחצר הפנימי' וחיצוני' שנק' חצרות ה'<sup data-n=\"8189\">1161</sup> כו').\n<b>אך</b> הנה כ\"ז הוא שנמשך כבר בעצמות המאציל בג' מדרגות הנ\"ל בבחי' מזון ולבוש ובית (וכל שחיצוני יותר יותר מתקיים ושורה בו ממקיף העליון ביותר כעוטה אור כשלמה",[["8171","1143","<b>שאין לו גוף. . ולא נערוך אליו</b>: ע\"פ פיוט יגדל."],["8172","1144","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["8173","1145","<b>דברה תורה כל[שון] בנ\"א</b>: ברכות לא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["8174","1146","<b>וירא ה'</b>: בראשית ו, ה."],["8175","1147","<b>וישמע ה'</b>: בהעלותך יא, א."],["8176","1148","<b>וישב כו' </b>[יאיז: הוי']: תהלים כט, י."],["8177","1149","<b>ויתעצב אל לבו וינחם </b>[יא ניתוסף: ה']: בראשית ו, ו [בהיפך הסדר]."],["8178","1150","<b>וישמח הוי'</b>: [כנראה הכוונה ל]תהלים קד, לא."],["8179","1151","<b>בחילול שבת שפוגם ביו\"ד. . ופגם בוי\"ו במדות</b>: ראה גם לעיל פ' בשלח רכט, א. מאמרי אדה\"א שמות ח\"ב ע' תפג. וש\"נ. ש\"א לד, ב ובהערה 5."],["8180","1152","<b>פושעים בי בגופא דמלכא</b>: ראה זהר יתרו פה, ב. עט\"ר דרוש לעשי\"ת ע' 132."],["8181","1153","<b>התפלה במקום קרבן</b>: ראה ברכות כו, א-ב. לעיל פ' יתרו רסח, ב. וש\"נ."],["8182","1154","<b>ג\"ש יושב ועוסק בתורה</b>: ראה ע\"ז ג, ב."],["8183","1155","<b>דצו\"פ</b>: דצמר ופשתים."],["8184","1156","<b>ויעש ה' לאד\"ם ולאשת\"ו</b>: נסמן לעיל פ' תרומה שיא, א הערה 372."],["8185","1157","<b>חשמל העליון</b>: ראה גם לעיל פ' שמות א, ג. וש\"נ."],["8186","1158","<b>חשמל. . מחיצוניות דבינה. . רגליהם</b>: הובא לעיל פ' בשלח קצא, א בשם הע\"ח. וש\"נ."],["8187","1159","<b>בשלו\"ם אותיות מלבו\"ש</b>: ראה סידור האריז\"ל בסיום תפלת העמידה. עמק המלך (שער שעשועי המלך) ש\"א, פנ\"ה (ט, ג). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670572\" data-slug=\"torat-chaim\" data-id=\"2300670572\">תו\"ח נח נח</a>, א ובהערה 15. שעה\"י קמ, ב."],["8188","1160","<b>וכאפריון עשה לו המלך</b>: שה\"ש ג, ט."],["8189","1161","<b>חצרות ה'</b>: ראה תהלים פד, ג. ועוד."]]],[2300550814,"כיריעות שלמה<sup data-n=\"8190\">1163</sup> כו') (וכמו\"כ הי' במשכן במשה ג' מדרגות דמזון ולבוש ובית<sup data-n=\"8191\">1162</sup> לג' מדריגות דאו\"כ ומקיף [ומקיף] למקיף הנ\"ל, דהקרבנות וקטרת הסמים שהי' בבישול ואפי' כלחם הפנים ושמן למאור (שז\"ש אכלתי יערי כו' אריתי מורי עם בשמי<sup data-n=\"8192\">1164</sup> כו') זהו בחי' מזון להיות חיבור האורות בכלים, כמו אור החסד דאה\"ר במנורה ושולחן בגבו' בצפון<sup data-n=\"8193\">1165</sup> בשפע מזונות ומזבח הזהב לקטרת בחי' ת\"ת. שהן בחי' חג\"ת דמדות דז\"א, והארון וכפורת הוא בחי' הכלי לאור הח\"ע וכת\"ר כו'<sup data-n=\"8194\">1166</sup>, וכך כל הכלים דמשכן בפרט עד מזבח החיצון שהוא בבחי' מל'<sup data-n=\"8195\">1167</sup> כידוע. ולבוש זהו בבגד תכלת וארגמן שפרשו על הכלים<sup data-n=\"8196\">1168</sup> בבחי' מקיף לכסות את הקדש כידוע. ויריעות עזים ועורות תחשים לאהל ומכסה שזהו כמו בית והיכל בבחי' מקיף למקיף כנ\"ל, שכ\"ז נחלק בג' מדרגות באדם העליון כנ\"ל באו\"כ ומקיף [ומקיף] למקיף שזהו כללות ענין המשכן וכליו). אבל בענין ל\"ט מלאכות הנ\"ל שמהן נעשה ג' מיני דברים הנ\"ל מזון ולבוש ובית זהו שנעשה בבחי' בירור והעלאה מלמטלמ\"ע דוקא, והיינו ענין הבירור דרפ\"ח כו' שמברר בעה\"ד טו\"ר למטה ונעשה מזה בחי' מזון רוחני דלחם דתורה אור להחיות לנשמה וכן ע\"י המצות נעשה בחי' לבוש כו' וכנ\"ל. וידוע שבאתעדל\"ת בהעלא' מ\"ן דכנ\"י שעולה מלמטה למעלה בתו\"מ שלהם ובאוי\"ר במס\"נ בק\"ש עי\"ז נתעורר אתעדל\"ע<sup data-n=\"8197\">1169</sup> בהמשכת החסדי' העליונים כפי אופן ההעלאה באו\"ח דוקא.\n<b>וכמו\"כ</b> יובן שבדרך זה ג\"כ בענין ל\"ט מלאכות ברוחני' הנ\"ל הנעשי' בג' חלוקות הנ\"ל במזון ולבוש ובית מלמטה למעלה באדם התחתון שהוא הנשמה שבגוף שנעשה בצלם אדם העליון ממש כמ\"ש נעשה אדם בצלמנו כדמותנו ממש (כמשי\"ת) עי\"ז נמשך למעלה ונעשה שם ג\"כ באצי' ג' דברים הללו דמזון ולבוש ובית בבחי' האצי' (וכמו שכנ\"י נק'<sup data-n=\"8198\">1170</sup> רעייתי פרנסתי שמפרנסים לאביהם שבשמים דמזון ולחם דתורה וקרבנות שהוא התפלה דעכשיו וכמ\"ש באתי לגני כו' אכלתי יערי כו' שזהו בחי' האוכל ומזון דתורה שנעשה מלמטה למעלה שנק' לחם מן הארץ ארץ דמפקא מזון לשובע לאדם העליון שז\"ש עוב\"ד אדמת\"ו ישבע לחם ) כו'. וכן ע\"י המצות שנק' לבושי'<sup data-n=\"8199\">1171</sup> נק' יפתי<sup data-n=\"8200\">1172</sup> שמייפים לאדם העליון בלבוש הוד מל' דמצות וזהו דרשה צו\"פ כו'. וכה\"ג בבית והיכל בד\"א של הלכה כו' שבמקום היכל ק\"ק עכשיו כנ\"ל, וזהו שנעשה הכל מלמעלה למטה באו\"ח דהעלאה דכנ\"י. וזהו ענין הל\"ט מלאכות שהי' במשכן בג' מיני חלוקות הנ\"ל בהעלאה מלמטה למעלה כמ\"ש קחו מאתכם דוקא תרומה להוי' כנ\"ל זהב וכסף ונחשת",[["8190","1163","<b>כיריעות שלמה</b>: שה\"ש א, ה."],["8191","1162","<b>וכל. . ובית</b>: יז: ליתא. וכנראה נשמט מפני תיבות הדומות: ובית. . ובית."],["8192","1164","<b>אריתי מורי עם בשמי</b>: שה\"ש ה, א."],["8193","1165","<b>ושולחן. . בצפון</b>: פקודי מ, כב. יומא כא, ב."],["8194","1166","<b>וכפורת. . וכתר כו'</b>: ראה גם לעיל פ' תרומה שטז, א."],["8195","1167","<b>מזבח החיצון. . מל'</b>: נסמן לעיל פ' יתרו רסט, ד."],["8196","1168","<b>בבגד תכלת וארגמן שפרשו על הכלים</b>: במדבר ד, ו. ז. ט. יא. יב. יג."],["8197","1169","<b>שבאתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["8198","1170","<b>נק'</b>: יאיז: ליתא."],["8199","1171","<b>המצות שנק' לבושי'</b>: ראה לעיל פ' בשלח קעו, א. וש\"נ."],["8200","1172","<b>יפתי</b>: שה\"ש ב, י. יג."]]],[2300550815,"לכלים לאורות במנורה וארון ושולחן וכל <span data-k=\"pg\">תרל</span> ּ הכלים, ויריעות תכלת וארגמן למקיפים דאהל, ולבושים דתכלת לכסות הקדש עד שהקמת המשכן הי' הכל ע\"י נדיבות הלב שנעשה מלמטה למעלה. ובהכרח שהי' ג' חלוקות הנ\"ל בל\"ט מלאכות דמשכן ג\"כ מלמטה למעלה כמו במזון דקרבנות וקטרת ולחם הפנים כו' לחבר האורות בכלים כנ\"ל ולבוש דמקיפים דיריעות והיכל ובית דאה\"ל המשכן שנק' מקיף למקיף שנעשה ההיכל<sup data-n=\"8201\">1173</sup> כמו דוגמא דמשכן העליון ששורה בו אדם העליון ע\"י הבירורים שעולים מלמטה למעלה דוקא, וכ\"ז מלבד מה שנמשך כבר מלמעלה למטה מעצמות המאציל שלא ע\"י אתעדל\"ת כלל מן הבירורי' כו' ג\"כ ג' מדרגות הללו דמזון ולבוש ובית כנ\"ל וד\"ל (והוא משכן העליון שלפני האצי' שנמשך לאדם דאצי' בבחי' אהל וכלים כו' וכמ\"ש למשה בפ' תרומה ועשו לי מקדש<sup data-n=\"8202\">1174</sup> ושכנתי בתוכם ככל אשר אני מראה אותך<sup data-n=\"8203\">1175</sup> את תבנית המשכן כו' וכן וראה ועשה בתבניתם<sup data-n=\"8204\">1176</sup> כו').\n<b>וכך</b> יובן ג\"כ ע\"ד הפשוט להיות שאדם שלמטה הוא בצלם אדם העליון ממש כי נר הוי' נשמת אדם ולזאת בהתקשרות העצמי' בנפשו האלקי' בק\"ש ותפלה במס\"נ באמת באחדות ה' כמו אליך הוי' נפשי אשא ממש, אז ודאי גם בג' דברים הנ\"ל במזון ולבוש ובית שלו יהי' קשור ודבוק ויעלה כל הטוב מהם למעלה ויהי' מזה בחי' מזון ולבוש ובית והיכל למעלה, כמו במזונו באכילתו בכוונה לש\"ש ולא למלאות כריסו כבהמה לפי שנפשו<sup data-n=\"8205\">1177</sup> דבוק למעלה באלקי' חיים וצדיק אוכל לשובע נפשו<sup data-n=\"8206\">1178</sup> האלקי' שיתחזק כחו בהשגות ועבוד' דאלקי' כנ\"ל, יוציא כל הטוב הגנוז במאכל שאוכל ויעלה לה' להיות בחי' מזון למעלה, וכמו קרבן בשר הבהמה ע\"ג המזבח ממש שעולה באש ונעשה לריח ניחוח להוי' והוא הקטרת חלבים דבהמה גשמי' כו'. וכך א' שמזונו של אדם בשולחנו מכפר כמזבח כו' כמ\"ש פתח במזבח וסיים בשולחן<sup data-n=\"8207\">1179</sup> כו', וגם הרי מקבל משולחן העליון שלפני הוי' כו' שנק' שולחן המלך כמ\"ש בזהר<sup data-n=\"8208\">1180</sup> (שזהו לחם הפנים שהי' בשולחן שבבהמ\"ק) [ו]כמו מלחם דתורה שנעשה מזון לנשמה האלקי' כנ\"ל. וכך הוא בבחי' לבושי' שאדם לובש עצמו להגן ולכבוד ולתפארת יעלה למעלה להיות בחי' לבוש לאדם העליון בהתבררות בחי' הטוב שבזה נעשה מזה בחי' מקיף העליון (כדוגמא שעשה בגדי קדש ממש לאהרן ובניו שהי' בדוגמא לבגדי קדש העליון כמו לבושי' כתלג כו') וכמו שנעשה לבושי' זכים ממעשה המצות כנ\"ל (וכמ\"ש ביהושע כה\"ג הלבש אותו מחלצות<sup data-n=\"8209\">1181</sup> [ו]כלבושי הנשמות בג\"ע<sup data-n=\"8210\">1182</sup> ). וכך הוא בבחי' היכל ודירה שנק' אהל",[["8201","1173","<b>ההיכל</b>: יאיז: הכל."],["8202","1174","<b>ועשו לי מקדש</b>: תרומה כה, ח."],["8203","1175","<b>ככל אשר אני מראה אותך</b>: תרומה שם, ט."],["8204","1176","<b>וראה ועשה בתבניתם</b>: שם כה, מ."],["8205","1177","<b>שנפשו</b>: יז: שנעשה."],["8206","1178","<b>וצדיק אוכל לשובע נפשו</b>: משלי יג, כה."],["8207","1179","<b>פתח במזבח וסיים בשולחן</b>: ברכות נה, א."],["8208","1180","<b>שולחן המלך כמ\"ש בזהר</b>: ראה זהר תרומה קנג, א. סידור שער בהמ\"ז קיד, ג ואילך. לעיל פ' יתרו רנז, א. מאמרי אדה\"א שמות ע' שכה."],["8209","1181","<b>הלבש אותו מחלצות</b>: זכרי' ג, ד [ושם: והלבש אותך — נסמן לעיל פ' שמות ז, ג הערה 319]."],["8210","1182","<b>[ו]כלבושי הנשמות בג\"ע</b>: ראה גם לעיל פ' וארא סב, ג ובהערה 133."]]],[2300550816,"שבאהל ודירה דאדם כשהוא בצלם אדם העליון במס\"נ בק\"ש בתו\"מ נעשה בחי' אהל למעלה כאהל המשכן שהי' השכינה שורה שם בגילוי גמור כמ\"ש וכבוד ה' מלא את המשכן<sup data-n=\"8211\">1183</sup> כידוע וד\"ל.\n<b>ונמצא</b> שבהעלאות במס\"נ באדם למטה גם במזונו ומלבושו והיכלו גורם לעשות מזון ולבוש והיכל למעלה באצי' להיות חיבור האורות בכלים ע\"י מזונו (כמו ואכלת ושבעת וברכת את הוי'<sup data-n=\"8212\">1184</sup> כו' שנמשך תוס' ברכה בשם הוי' ממזון זה שאכל לשובע נפשו האלקי' וכלחם הפנים כו' וכקרבנות שנק' לחמי כו', וכך ע\"י תורה ותפלה כנ\"ל) (וזהו עולה למעלה יותר ממזל<sup data-n=\"8213\">1185</sup> העליון דעצמות המאציל <span data-k=\"pg\">1262</span> ּ כאכל\"ו ריעי\"ם [שהן חו\"ב תרדל\"מ כו'] שנק' לחם מן השמים כדוגמא דמן שנמשך מזונא דח\"ע למטה ונק' טל תורה<sup data-n=\"8214\">1186</sup> שזהו טל אורות טליך<sup data-n=\"8215\">1187</sup> שיחי' בו מתים כו' כידוע). וכן מלבוש שנברר למטה בחשמ\"ל דנוגה מבחי' הטוב שבה (שנעשה כתנות אור בא' כנ\"ל) יותר עולה למעלה במדרגות מלבוש דחשמ\"ל העליון כמו עוטה אור כשלמה וכה\"ג. וכן מבחי' בירור דאבני' שבונין בית והיכל למטה שנעשה היכל ואהל למעלה יותר עלי[ון] מהיכל העליון כמו האפריו\"ן כו') (והוא מטעם דבירור דאו\"ח עולה למעלה מאו\"י מטעם יתרון האור שבא מבירור והיפך דחושך לאור מדברים גשמיי' דד\"י דק\"נ שמעורב טו\"ר כמו במזון ולבוש דלחם לאכול ובגד ללבוש אפי' בתו\"מ וכ\"ש במזון ולבוש גשמי' כו').\n<b>והטעם</b> הוא ע\"ד הפשוט כי ע\"י מס\"נ האמיתי' שבאדם שנעשה בצלם אדם העליון שורה בנר\"נ שבו מבחי' נר\"נ דאצי' ואז ודאי נברר כל בחי' הטוב שבמזונו ומאכלו להיות מזון לנר\"נ דאצי', והטוב שבמלבושי' עולים ג\"כ למעלה להיות לבושים לאדם העליון, וכן בהיכלו ודירתו (ואין זה פלא כ\"כ מאחר שנצטוינו על מצות מזוזה בפתח הבית וההיכל שהוא בא בכתב ובאותיות פ' שמע והא\"ש<sup data-n=\"8216\">1188</sup> כו' שיהי' שמירה לבית<sup data-n=\"8217\">1189</sup> וגם בשעריך כו'). וכמו שתפילין שבראש ויד מקיפי' למוחי' ומדות שבלב על [בחי'] נר\"נ כך המזוזות שבבית בחי' מקיף למקיף כו', והיינו כדוגמא דבית והיכל למעלה באצי' ובהיכלות ובתים בג\"ע, וכמו שהי' בבהמ\"ק ושעריו וחצריו והב'<sup data-n=\"8218\">1190</sup> בקד\"ש העליון כו'). והיינו לפי שהאדם נברא בצלם אלקים ממש כמ\"ש ויברא אלקי' את האדם בצלמו<sup data-n=\"8219\">1191</sup> כו' דהיינו בצלם ודמות כמ\"ש",[["8211","1183","<b>וכבוד ה' מלא את המשכן</b>: פקודי מ, לה."],["8212","1184","<b>את הוי'</b>: יאיז: להוי'."],["8213","1185","<b>ממזל</b>: שם: ממזון."],["8214","1186","<b>טל תורה</b>: יל\"ש ואתחנן ד, ד (רמז תתכד). ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט הערה ד\"ה דתו' אור."],["8215","1187","<b>טל אורות טליך </b>[יאיז: ליתא]: ישעי' כו, יט. ירושלמי ברכות פ\"ה, ה\"ב."],["8216","1188","<b>מזוזה. . פ' שמע והא\"ש</b>: מנחות כח, א וברש\"י (במשנה). רמב\"ם רפ\"ה מהל' מזוזה."],["8217","1189","<b>מזוזה. . שיהי' שמירה לבית</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' שעא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191121\" data-slug=\"likkutei-sichot\" data-id=\"1300191121\">לקו\"ש עקב (כרך יט) ע' 121</a> ואילך. וש\"נ."],["8218","1190","<b>והב'</b>: ויאיז: הם. יב: הב'."],["8219","1191","<b>ויברא אלקי' את האדם בצלמו</b>: בראשית א, כז."]]],[2300550817,"בצלמנו כדמותנו<sup data-n=\"8220\">1192</sup>, וידוע ההפרש בין צלם ודמות שהצלם הוא צורה עצמי' ודמות זהו המצוייר בדבר נבדל שנק' צורה לצורה העצמי' כדמות שבלוח המרא[ות] לצורה העצמי' דפנים. וכה\"ג הוא ההפרש בין יחו\"ע דע\"ס דאצי' אף בכלים בחכ' מוחא חסד דרועא כו' נק' צורה העצמי' כצלם ותואר האדם בעצמו שזהו בחי' גופא דמלכא באצי' דאיהו וגרמוהי חד<sup data-n=\"8221\">1193</sup> כו', ואמנם בהמשכה וגילוי דאו\"כ דאד\"ם עילאה דאצי' בהתגלות לחוץ ממנו כמו אותיות הדבור ומעשה שזהו בחי' המל' (שנק' אדם תתאה<sup data-n=\"8222\">1194</sup> שמקבל מאדם עילאה כידוע) זהו שנק' יחו\"ת דבשכמל\"ו דמל' דאצי' בבי\"ע שנק' דמו\"ת כבוד הוי'<sup data-n=\"8223\">1195</sup> דז\"א דאצי' כידוע, שנק' מקור להתהוות הנבראי' ב\"ג מאין ליש ממש ולכך נק' דמות כציור בדבר נבדל להוות<sup data-n=\"8224\">1196</sup> אותיות שנבראו בהן כל העולמות שאינו רק בחי' הארה דהארה כידוע. אך הנה האדם התחתון שנתקשרה ונדבקה נפשו במס\"נ ביחו\"ע ויחו\"ת באחד אמיתי דוקא (כאברהם שמצא לבבו נאמן כו'), הרי נברר ונתעלה גם כל בחי' הטוב שנפל במאכלו ומזונו שאכל וכל בחי' הטוב שבמלבושיו ובהיכלו ודירתו [ו]עולים עמו לה' אחד להיות בחי' מזון ולבוש והיכל למעלה בבחי' האצי' ממש, מאחר שמוסר נפשו באחד<sup data-n=\"8225\">1197</sup> ביח\"ע ויח\"ת כנ\"ל. אזי הוא ממש בצלם ודמות האדם העליון ביח\"ע ויח\"ת כו' להיות מאכלו מאכל אדם העליון ביח\"ע ויח\"ת<sup data-n=\"8226\">*1198</sup> בצלם ודמות כו', להיות מאכלו מאכל [ל]אדם העליון ומלבושיו מלבוש<sup data-n=\"8227\">1198</sup> למעלה וכן היכלו ודירתו נעשה היכל לה' <span data-k=\"pg\">תרלא</span> ּ אחד כמו היכל ה' המה<sup data-n=\"8228\">1199</sup>. ואין זה פלא כ\"כ שכבר הי' לעולמים בעוה\"ז באבות שהן המרכבה<sup data-n=\"8229\">1200</sup>, שהיו במס\"נ אמיתי' באחד במרכבה בתמידות בהפשט' הגשמיות לגמרי ע\"כ הי' כל אשר להם כמזון ולבוש והיכל הכל לה' אחד שזהו כמזון ולבוש והיכל דאצי' ממש (וכמו שישב פתח האהל<sup data-n=\"8230\">1201</sup> כאהל העליון כו', וגם מלאכים אכלו מאכלו דאברהם<sup data-n=\"8231\">1202</sup> כו'). כי במס\"נ שלהם בכל מעשיהם ממש ביררו כל חלקי ניצוצות הטובים שבמאכל ומזון ולבוש והיכלות שלהם כדוגמא<sup data-n=\"8232\">1203</sup> להיכלות ולבושי' ומזון דאצי' ממש וד\"ל (וכמו שיהי' בעוה\"ב מיש ליש<sup data-n=\"8233\">1204</sup> בלי פירוד כלל כו' כמ\"ש במ\"א דרוחני' וגשמיות היו שוין באבות<sup data-n=\"8234\">1205</sup> שהטעימן מעין העוה\"ב<sup data-n=\"8235\">1206</sup> כידוע).\n[כב]<b> והנה</b> כמו שמבואר למעלה בענין הבירורי' דל\"ט מלאכות בג' מדרגות הנ\"ל במזון ולבוש ובית מלמטה למעלה כמו שנעשה ע\"י אתעדל\"ת בנפש האדם [ו]ע\"י",[["8220","1192","<b>בצלמנו כדמותנו</b>: בראשית א, כו. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ס\"ע עתר ואילך. שע\"ת קז, א ואילך. ש\"א לא, סע\"א. מאמרי אדה\"א דברים ח\"ב ע' תקנג."],["8221","1193","<b>דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["8222","1194","<b>המל'. . אדם תתאה</b>: ראה גם לעיל פ' בשלח קצח, ד. וש\"נ."],["8223","1195","<b>דמל'. . דמו\"ת כבוד הוי'</b>: נסמן לעיל פ' תצוה שע, א."],["8224","1196","<b>להוות</b>: יאיז: להיות."],["8225","1197","<b>שמוסר נפשו באחד</b>: נסמן לעיל פ' תרומה שטז, ג."],["8226","*1198","<b>כו' להיות. . ויח\"ת</b>: יאיז: ליתא."],["8227","1198","<b>מלבוש</b>: יאיז: לבוש."],["8228","1199","<b>היכל ה' המה</b>: ירמי' ז, ד."],["8229","1200","<b>באבות שהן המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["8230","1201","<b>שישב פתח האהל</b>: וירא יח, א."],["8231","1202","<b>מלאכים אכלו מאכלו דאברהם</b>: וירא שם, ח."],["8232","1203","<b>כדוגמא</b>: ויב: להיות בדוגמא."],["8233","1204","<b>בעוה\"ב מיש ליש</b>: ראה גם לעיל פ' בשלח קנט, ב הערה 466."],["8234","1205","<b>דרוחני' וגשמיות היו שוין באבות</b>: ראה גם לעיל פ' יתרו רנא, סע\"ד ואילך. מאמרי אדה\"א שמות ח\"ב ע' שסא וע' שעד."],["8235","1206","<b>באבות שהטעימן מעין העוה\"ב</b>: ב\"ב טז, סע\"ב ואילך."]]]]});
